INSERT INTO ref.source (source_id, title, kind, tier, as_of, origin, note) VALUES ('src.rr.transition_finances', 'Military-to-Civilian Transition Finances: A Data-Driven Roadmap for VetBuddy', 'research_report', 4, '2026-10-20', 'upload: Military-to-Civilian_Transition_Finances_A_Data-Driven_Roadmap_for_VetBuddy.md', 'Rates are FY2025 by design; its own caveats name the 2026 changes. Rule-of-thumb multipliers are not DoD-published.');
