INSERT INTO ref.source (source_id, title, kind, tier, as_of, origin, note) VALUES ('src.mod.sentinel', 'Operation Sentinel — Duty Status & Benefits Determination (Module 01)', 'module_source', 4, '2026-08-05', 'upload: sentinel.html', 'Single-file tool. Each record cites its authority; its ''verified'' label means cross-checked by that build, not signed by a named human, so it maps to SOURCE_CHECKED here.');
