INSERT INTO ref.source (source_id, title, kind, tier, as_of, origin, note) VALUES ('src.cfr.38_4_25', '38 CFR 4.25 — Combined ratings table (eCFR via LII)', 'primary', 1, '2026-10-20', 'https://www.law.cornell.edu/cfr/text/38/4.25', 'Read 2026-10-20 for the combining and single-rounding rule and the regulation''s worked examples; backs backend/app/domains/kernel/ratings.py.');
