INSERT INTO ref.conflict (conflict_id, subject, status, readings, why_it_matters, next_action, resolution, blocking_for, source_ids) VALUES ('conflict.al.veteran_population', 'Alabama veteran population', 'contested_unresolved', '[{"basis": "VA VetPop2023", "source": "src.rr.alabama_landscape", "value": "303,253"}, {"basis": "BLS CPS 2024, civilian non-institutional 18+", "source": "src.rr.alabama_tap", "value": "334,000"}, {"basis": "ADVA citing VetPop", "source": "src.rr.alabama_tap", "value": "377,310"}]'::jsonb, 'Every per-veteran figure (spending, density) changes with the denominator.', 'Cite one methodology per screen and name it.', NULL, '{}'::text[], ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.conflict (conflict_id, subject, status, readings, why_it_matters, next_action, resolution, blocking_for, source_ids) VALUES ('conflict.al.va_education_beneficiaries', 'Alabama all-program VA education beneficiaries, FY2023', 'contested_unresolved', '[{"source": "src.rr.alabama_landscape", "value": "20,334"}, {"source": "src.rr.alabama_tap", "value": "23,000+"}]'::jsonb, NULL, 'Pull the VA education benefits state table.', NULL, '{}'::text[], ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.conflict (conflict_id, subject, status, readings, why_it_matters, next_action, resolution, blocking_for, source_ids) VALUES ('conflict.al.adva_per_veteran', 'ADVA budget per veteran', 'contested_unresolved', '[{"basis": "$230M / 303K (VetPop)", "source": "src.rr.alabama_landscape", "value": "$575"}, {"basis": "$230M / 334K (BLS)", "source": "src.rr.alabama_tap", "value": "~$300"}]'::jsonb, 'Both divide the same budget by a different population; neither nets out federal per diem for state homes (landscape report puts the pure state general fund at $20–40M).', NULL, NULL, '{}'::text[], ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.conflict (conflict_id, subject, status, readings, why_it_matters, next_action, resolution, blocking_for, source_ids) VALUES ('conflict.va_comp.2025_70pct_single', 'VA compensation, 70%, veteran alone, effective 2024-12-01', 'contested_unresolved', '[{"note": "also implied by va-rating-app.html (2026 rate $1,808.45 / 1.028)", "source": "src.rr.transition_finances", "value": "$1,759.19"}, {"source": "src.legacy.gen3_client", "value": "$1,759.05"}, {"source": "src.legacy.va_claims_data", "value": "$1,759.05"}]'::jsonb, 'Quoted payment amounts must be reproducible to the cent.', 'Read the VA rate table for that period; correct the losing value with a named reviewer.', NULL, '{}'::text[], ARRAY['src.legacy.gen3_client','src.legacy.va_claims_data','src.rr.transition_finances']::text[]);
INSERT INTO ref.conflict (conflict_id, subject, status, readings, why_it_matters, next_action, resolution, blocking_for, source_ids) VALUES ('conflict.base_pay.gate_labels', 'FY2025 base pay longevity gates in the legacy client', 'contested_unresolved', '[{"source": "src.legacy.gen3_client", "value": "Gen-3 client: E-8 ''18yr'' = 6739, E-9 ''20yr'' = 7448, O-3 ''6yr'' = 7113"}, {"source": "src.rr.transition_finances", "value": "Finance report table: E-8 over 18 = 6562 (6739 is over 20); E-9 over 18 = 7448; O-3 over 4 = 7113 (over 6 = 7454)"}]'::jsonb, 'A one-column shift changes a separation-cliff estimate by $150–$340 a month.', 'Use the DFAS table; the legacy client constants are not carried.', NULL, '{}'::text[], ARRAY['src.legacy.gen3_client','src.rr.transition_finances']::text[]);
INSERT INTO ref.conflict (conflict_id, subject, status, readings, why_it_matters, next_action, resolution, blocking_for, source_ids) VALUES ('conflict.wv.cohen_clinic_count', 'Cohen Veterans Network clinic count', 'contested_unresolved', '[{"source": "src.rr.women_veterans_50_state", "value": "23 clinics in 22 states + DC (23 listed)"}, {"source": "src.mod.women_veterans", "value": "22 clinics"}, {"source": "src.rr.women_veterans_50_state", "value": "22 clinics / 21 states (older CVN materials, cited by the report)"}]'::jsonb, NULL, NULL, NULL, '{}'::text[], ARRAY['src.mod.women_veterans','src.rr.women_veterans_50_state']::text[]);
