INSERT INTO ref.conflict (conflict_id, subject, status, readings, why_it_matters, next_action, resolution, blocking_for, source_ids) VALUES ('conflict.tx.hazlewood_legacy_age', 'Hazlewood Legacy Act child age ceiling', 'contested_unresolved', '[{"basis": "agency and university sources", "source": "src.mod.sentinel", "value": "25 or younger on the first day of the term"}, {"basis": "one secondary source", "source": "src.mod.sentinel", "value": "under 21"}]'::jsonb, NULL, 'Resolve against the TVC policy manual before advising anyone.', NULL, '{}'::text[], ARRAY['src.mod.sentinel']::text[]);
