INSERT INTO ref.conflict (conflict_id, subject, status, readings, why_it_matters, next_action, resolution, blocking_for, source_ids) VALUES ('conflict.state_tax.full_exempt_count', 'How many jurisdictions fully exempt military retirement (TY2025)', 'contested_unresolved', '[{"source": "src.rr.transition_finances", "value": "38 of 51 including the 9 with no income tax"}, {"source": "src.rr.transition_finances", "value": "approximately 28 income-tax states"}, {"source": "src.rr.transition_finances", "value": "30 states named in the report''s own full-exemption list"}]'::jsonb, 'The report is internally inconsistent; the per-state summary is carried, the headline count is not.', NULL, NULL, '{}'::text[], ARRAY['src.rr.transition_finances']::text[]);
