INSERT INTO ref.conflict (conflict_id, subject, status, readings, why_it_matters, next_action, resolution, blocking_for, source_ids) VALUES ('conflict.ednav.al_award_cap', 'Alabama G.I. Dependents'' Scholarship award cap (Education Navigator oq.al.31-6.award_cap)', 'contested_unresolved', '[{"source": "src.rr.alabama_tap", "value": "$400 per credit hour (HB284, effective 2024-07-31)"}, {"source": "src.mod.education_navigator", "value": "unretrieved: cap form unknown (dollar, rate, credit-hour or semester limit)"}, {"source": "src.legacy.state_benefits_all", "value": "up to $250 per semester hour and $1,000 for books, after federal grants"}]'::jsonb, 'The funding stack cannot compute an Alabama dependent''s remaining gap without it. A tier-4 report is a lead, not the amended chapter text.', NULL, NULL, ARRAY['funding_stack:AL','benefit_result:al.gi_dependents_scholarship']::text[], ARRAY['src.legacy.state_benefits_all','src.mod.education_navigator','src.rr.alabama_tap']::text[]);
INSERT INTO ref.conflict (conflict_id, subject, status, readings, why_it_matters, next_action, resolution, blocking_for, source_ids) VALUES ('conflict.design.crisis_floor_copies', 'Crisis contacts: one source of truth vs deliberate redundancy', 'resolved_by_design', '[{"source": "src.gov.master_record", "value": "One config file every surface reads (VetBuddy config/crisis_floor.yaml)"}, {"source": "src.mod.women_veterans", "value": "Four independent copies so a dead API or DB still shows a hotline (Women Veterans module)"}]'::jsonb, NULL, NULL, 'One authored source; generated copies. The API reads config/crisis_floor.yaml, the standalone app embeds a generated copy (web/kernel_data.js), and a test fails if any copy drifts. Redundant delivery, single authorship.', '{}'::text[], ARRAY['src.gov.master_record','src.mod.women_veterans']::text[]);
INSERT INTO ref.conflict (conflict_id, subject, status, readings, why_it_matters, next_action, resolution, blocking_for, source_ids) VALUES ('conflict.va_comp.2026_60pct_single', 'VA compensation, 60%, veteran alone, effective 2025-12-01', 'contested_unresolved', '[{"basis": "summary table", "source": "src.legacy.va_rating_app", "value": "$1,435.01"}, {"basis": "dependents table, same file", "source": "src.legacy.va_rating_app", "value": "$1,435.02"}]'::jsonb, 'One file disagrees with itself; quoted amounts must be reproducible to the cent.', 'Read VA''s 2026 rate table; correct the losing value with a named reviewer.', NULL, '{}'::text[], ARRAY['src.legacy.va_rating_app']::text[]);
INSERT INTO ref.conflict (conflict_id, subject, status, readings, why_it_matters, next_action, resolution, blocking_for, source_ids) VALUES ('conflict.license_reciprocity.two_datasets', 'State license reciprocity (teacher, Uniform Bar Exam, real estate), 51 jurisdictions', 'contested_unresolved', '[{"source": "src.legacy.vault_license_reciprocity", "value": "Vault table: e.g. TX, MS, OR lawyer_ube = false; teacher full reciprocity = true in most states"}, {"source": "src.legacy.state_benefits_all", "value": "Uploaded summary: e.g. TX, MS, OR lawyer_ube = true; teacher full reciprocity = false in most states; 42 of 51 states differ on at least one field"}]'::jsonb, 'Spouses and members who move use this to plan a license transfer; neither reading names a primary source.', 'Check lawyer_ube against NCBE''s UBE jurisdiction list and teacher/real-estate fields against each state licensing board; correct with a named reviewer.', NULL, ARRAY['benefit_result:license_reciprocity']::text[], ARRAY['src.legacy.state_benefits_all','src.legacy.vault_license_reciprocity']::text[]);
