INSERT INTO ref.directory_entry (entry_id, kind, jurisdiction_code, name, place, org_type, program, care_types, phone, phone_e164, text_line, mailbox, url, eligibility_note, caveat, dedicated_coordinator, also_in_crisis_floor, last_checked, status, source_ids) VALUES ('nat.va.hud_vash', 'national', 'FEDERAL', 'HUD-VASH', NULL, 'va', NULL, ARRAY['wv_housing']::text[], NULL, NULL, NULL, NULL, 'https://www.va.gov/homeless/hud-vash.asp', 'HUD Housing Choice Voucher plus VA case management. Source states: no time limit; income cap 80% of Area Median Income; registered sex offenders ineligible; apply through a VA medical center or the homeless call center in the crisis floor.', NULL, NULL, NULL, NULL, 'UNVERIFIED', ARRAY['src.rr.women_veterans_50_state']::text[]);
