INSERT INTO ref.directory_entry (entry_id, kind, jurisdiction_code, name, place, org_type, program, care_types, phone, phone_e164, text_line, mailbox, url, eligibility_note, caveat, dedicated_coordinator, also_in_crisis_floor, last_checked, status, source_ids) VALUES ('nat.dod.child_care_aware', 'national', 'FEDERAL', 'Child Care Aware of America — DoD MCCYN / MCCYN-PLUS fee assistance', NULL, 'nonprofit', NULL, ARRAY['wv_childcare']::text[], '800-424-2246', '+18004242246', NULL, NULL, 'https://www.childcareaware.org/', 'Primarily active-duty, Guard and Reserve members, not general veterans.', 'Eligibility must be flagged in the app; most veterans will not qualify.', NULL, NULL, NULL, 'UNVERIFIED', ARRAY['src.rr.women_veterans_50_state']::text[]);
INSERT INTO ref.directory_entry (entry_id, kind, jurisdiction_code, name, place, org_type, program, care_types, phone, phone_e164, text_line, mailbox, url, eligibility_note, caveat, dedicated_coordinator, also_in_crisis_floor, last_checked, status, source_ids) VALUES ('nat.np.swan', 'national', 'FEDERAL', 'Service Women''s Action Network (SWAN)', NULL, 'nonprofit', NULL, ARRAY['wv_mst','wv_legal']::text[], '888-502-8755', '+18885028755', NULL, 'info@servicewomen.org', 'https://www.servicewomen.org/', '24/7 assistance hotline (888-502-8755); case management (301-578-2049, casemanager@servicewomen.org); office (202) 798-5570; advocacy and pro-bono legal referrals. Founded 2007.', NULL, NULL, NULL, NULL, 'UNVERIFIED', ARRAY['src.rr.women_veterans_50_state']::text[]);
