INSERT INTO ref.statistic (stat_id, jurisdiction_code, metric, value, unit, period, note, conflict_id, status, source_ids) VALUES ('stat.al.vet_unemployment_2024', 'AL', 'Veteran unemployment rate', '1.1', 'percent', '2024', 'Rank 2 of 51 (NH 0.2%). Sample-based (BLS CPS Table 6A); read as ''very low, 0–2%''. 156,000 veteran labor force, ~2,000 unemployed.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.statistic (stat_id, jurisdiction_code, metric, value, unit, period, note, conflict_id, status, source_ids) VALUES ('stat.us.vet_unemployment_2024', 'FEDERAL', 'Veteran unemployment rate', '3.0', 'percent', '2024', 'Nonveterans 3.9%. Kansas highest at 7.2%.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.statistic (stat_id, jurisdiction_code, metric, value, unit, period, note, conflict_id, status, source_ids) VALUES ('stat.al.vet_lfpr_2024', 'AL', 'Veteran labor force participation', '46.7', 'percent', '2024', 'National 48.0%. Low unemployment partly reflects an older, retired population.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_tap']::text[]);
