INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.TX.income', 'TX', 'income', 'No state individual income tax. Military pay, retired pay and VA compensation are untaxed at the state level.', 'Tex. Const. art. VIII', NULL, NULL, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel','src.rr.transition_finances']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.TX.property', 'TX', 'property', '100% rating or Individual Unemployability: total homestead exemption. Ratings 10–90%: assessed-value reduction of $5,000–$12,000 scaled to rating. Surviving spouses qualify.', 'Tex. Tax Code ch. 11; Comptroller form 50-114', 'County add-ons not captured.', NULL, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel','src.rr.transition_finances']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.TX.hazlewood', 'TX', 'edu_member', 'Hazlewood Act: up to 150 credit hours of tuition and most fees exempted at state institutions. Requires 181 days active duty, honorable discharge, Texas home of record or residence at entry, and exhaustion of federal VA education benefits.', 'Tex. Educ. Code 54.341', 'Federal-exhaustion requirement makes it a back-end benefit. The 181-day active-duty test can exclude a full Guard career with no Title 10 mobilization.', NULL, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel','src.rr.transition_finances','src.rr.alabama_landscape']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.TX.strp', 'TX', 'edu_member', 'State Tuition Reimbursement Program: up to 12 credit hours per fall and spring semester, subject to appropriation.', 'Texas Military Department', 'Last payer; sequence against FTA and Chapter 33.', NULL, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.TX.hazlewood_legacy', 'TX', 'edu_family', 'Hazlewood Legacy Act: a veteran may assign unused hours to one child at a time who meets GPA and progress requirements.', 'Tex. Educ. Code 54.3411', NULL, 'conflict.tx.hazlewood_legacy_age', 'CONTESTED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.TX.hazlewood_dependents', 'TX', 'edu_family', 'Spouses and dependent children of members (including Texas National Guard) who died in the line of duty, are MIA, or became totally disabled for employability receive tuition-free credit hours.', 'Tex. Educ. Code 54.341', NULL, 'conflict.tx.hazlewood_dependent_hours', 'CONTESTED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.TX.employment', 'TX', 'employ', 'State hiring preference; surviving spouses of members killed on active duty also receive preference.', 'Tex. Gov''t Code ch. 657', NULL, NULL, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.TX.recreation', 'TX', 'rec', '50%+ rating: free Super Combo hunting and fishing license and state park access.', 'Texas Parks & Wildlife', NULL, NULL, 'UNVERIFIED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.TX.business', 'TX', 'biz', 'New veteran-owned businesses: free LLC formation and a five-year franchise tax exemption.', 'Tex. Tax Code 171.0005', NULL, NULL, 'UNVERIFIED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.FL.income', 'FL', 'income', 'No state individual income tax.', 'Fla. Const. art. VII s.5', NULL, NULL, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel','src.rr.transition_finances']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.FL.property', 'FL', 'property', '100% permanent and total: complete homestead exemption. Service-connected rating: $5,000 assessed-value reduction. Age 65+ with service-connected permanent partial disability: discount matching the rating. Deployed members: exemption proportional to days deployed outside the continental US.', 'Fla. Stat. ch. 196', 'HARD DEADLINE: applications due 1 March for that tax year; late filing only through the property appraiser.', 'conflict.fl.5000_threshold', 'SOURCE_CHECKED', ARRAY['src.mod.sentinel','src.rr.transition_finances']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.FL.homestead', 'FL', 'property', 'Standard homestead exemption up to $51,411 assessed value plus Save Our Homes 3% cap; veteran exemptions layer on top.', 'Fla. Stat. 196.031', 'Indexed figure from a secondary source; re-verify annually.', NULL, 'UNVERIFIED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.FL.edd', 'FL', 'edu_member', 'Educational Dollars for Duty: Florida National Guard members, 100% of the resident rate at Florida public institutions; highest current resident rate at accredited private institutions.', 'Fla. Stat. 250.10', 'Graduate rate documented at $265.35 per credit with approval required before 1 Jan 2026; re-verify current-year rules.', NULL, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.FL.purple_heart', 'FL', 'edu_member', 'Purple Heart or superior combat decoration: undergraduate tuition waived at state universities, Florida College System institutions and career centers.', 'Fla. Stat. 1009.26', NULL, NULL, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.FL.out_of_state_waiver', 'FL', 'edu_member', 'Out-of-state fees waived for honorably discharged veterans residing in Florida.', 'Fla. Stat. 1009.21', NULL, NULL, 'UNVERIFIED', ARRAY['src.mod.sentinel','src.rr.transition_finances']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.FL.csddv', 'FL', 'edu_family', 'CSDDV scholarship: tuition and registration fees for children aged 16–22 and unremarried spouses of veterans rated 100% P&T, who died of service-connected causes, or who are POW/MIA.', 'Fla. Stat. 295.01', 'Narrow 16–22 age band; a delayed enrollment can age out.', NULL, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.FL.survivor_waiver', 'FL', 'edu_family', 'Tuition waiver for surviving spouses and children of deceased active-duty members.', 'Florida DVA', 'Relationship to CSDDV not mapped.', NULL, 'UNVERIFIED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.FL.employment', 'FL', 'employ', 'Veterans'' preference adds 10 to 15 points to civil service scoring depending on disability status.', 'Fla. Stat. ch. 295', NULL, NULL, 'UNVERIFIED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.FL.recreation', 'FL', 'rec', 'Service-connected disability: free lifetime state park pass. 100%: free five-year hunting and fishing license. 50%+: free hunting and fishing.', 'FWC; Fla. DEP', 'Rating thresholds vary between sources.', 'conflict.fl.recreation_thresholds', 'CONTESTED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.FL.vehicle', 'FL', 'vehicle', '100% P&T, or vision or limb loss: exempt from vehicle property tax. Reduced-cost ($20) comprehensive license for active, retired and reserve Florida residents.', 'Fla. Stat. ch. 320', NULL, NULL, 'UNVERIFIED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.FL.business', 'FL', 'biz', 'Ten-year business occupation tax exemption for veteran-owned businesses; procurement preferences and license fee waivers.', 'Fla. Stat. ch. 205', NULL, NULL, 'UNVERIFIED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.PR.income', 'PR', 'income', 'Veteran income tax exemption of $1,500 ($3,000 where both spouses are veterans) plus a $500 lifetime deduction. Military pension income is fully exempt with DD-214 or 1099-R support.', 'P.R. Internal Revenue Code', NULL, NULL, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.PR.property', 'PR', 'property', 'Standard: ten years up to $5,000 appraised value. 50%+ VA disability: first $50,000 exempt with annual VA certification as of 1 January. 100%: total exemption on a home built, acquired or remodeled by the veteran (cap 1,000 m² urban or one cuerda rural).', 'P.R. Laws Ann. tit. 21; CRIM', 'Residence at the dwelling since 1 January of the preceding year required.', NULL, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.PR.figna', 'PR', 'edu_member', 'FIGNA Military Education Incentive for PRNG members contributing $5 monthly: up to $50 per credit (bachelor''s or below), $75 per credit (master''s or doctoral), up to 18 credits per year.', 'Puerto Rico National Guard Institutional Trust (FIGNA)', 'Contributory; breaks a naive comparison model.', NULL, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.PR.upr', 'PR', 'edu_member', 'Free tuition at the University of Puerto Rico and regional colleges for veterans without VA education benefits or whose benefits are exhausted.', 'P.R. Laws Ann. tit. 18', NULL, NULL, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.PR.figna_family', 'PR', 'edu_family', 'FIGNA extends to a spouse or child under 23 (children to bachelor''s, spouses to master''s, members to doctoral); one family member at a time.', 'FIGNA', NULL, NULL, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.PR.dependents', 'PR', 'edu_family', 'Dependents of Puerto Rico veterans: 50% tuition reduction at UPR and regional colleges. Survivors of members killed on active duty: 100% exemption at Puerto Rico–supported schools.', 'P.R. Laws Ann. tit. 18', NULL, NULL, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.PR.gray_area', 'PR', 'retire', 'PRNG retirees aged 55–59 with 20+ years and an honorable discharge receive $175 monthly until age 60.', 'Puerto Rico National Guard Retiree Annuity', 'Addresses the federal gray-area gap; few jurisdictions do this.', NULL, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.GU.income', 'GU', 'income', 'Guam does not tax military disability retirement pay.', 'Guam Territorial Income Tax', NULL, NULL, 'UNVERIFIED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.GU.property', 'GU', 'property', 'Qualifying disabled veterans, surviving spouses, Gold Star parents and a veteran''s legal guardian may be exempt from all Guam property taxes.', 'Guam Code Ann. tit. 11', 'Gold Star parents and guardians as eligible classes is unusual; verify directly.', NULL, 'UNVERIFIED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.CA.income', 'CA', 'income', 'Active-duty residents stationed outside California pay no state income tax on military pay; military pay is taxable if stationed in-state.', 'Cal. Rev. & Tax. Code', 'Verify against FTB guidance.', NULL, 'UNVERIFIED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.CA.property', 'CA', 'property', 'A veterans'' exemption and a separate disabled veterans'' exemption exist, administered by county assessors.', 'Cal. Rev. & Tax. Code 205.5', 'The finance report gives statewide 2025 amounts ($175,298 basic / $262,950 low-income); Sentinel says no single statewide figure is publishable. Both kept; the amounts are indexed and need annual verification.', NULL, 'UNVERIFIED', ARRAY['src.mod.sentinel','src.rr.transition_finances']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.CA.business', 'CA', 'biz', 'Honorably discharged veterans selling goods from a fixed location may be exempt from municipal, county and state business license fees (excludes alcohol).', 'Cal. Bus. & Prof. Code 16001.7', NULL, NULL, 'UNVERIFIED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.CO.income', 'CO', 'income', 'Active-duty pay tax-free if stationed outside the continental US 305+ days. Retirees may deduct up to $15,000 (<55), $20,000 (55–64) or $24,000 (65+) of retirement income including SBP.', 'Colo. Rev. Stat. 39-22-104', NULL, NULL, 'UNVERIFIED', ARRAY['src.mod.sentinel','src.rr.transition_finances']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.CO.property', 'CO', 'property', 'Qualifying disabled veterans, surviving spouses and Gold Star spouses: 50% of the first $200,000 of primary residence value exempt; the state reimburses counties.', 'Colo. Const. art. X s.3.5', NULL, NULL, 'UNVERIFIED', ARRAY['src.mod.sentinel','src.rr.transition_finances']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.AR.income', 'AR', 'income', 'Active-duty pay, retired pay and SBP payments are tax-free.', 'Ark. Code Ann. 26-51-307', NULL, NULL, 'UNVERIFIED', ARRAY['src.mod.sentinel','src.rr.transition_finances']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.AR.property', 'AR', 'property', 'Loss of limbs, total blindness or 100% service-connected: full homestead and personal property exemption; unremarried surviving spouses and dependent children may qualify where death was in service or service-connected.', 'Ark. Code Ann. 26-3-306', NULL, NULL, 'UNVERIFIED', ARRAY['src.mod.sentinel','src.rr.transition_finances']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.AZ.vehicle', 'AZ', 'vehicle', 'Vehicle license tax exemptions, special plates and CDL skills-test waivers through ADOT.', 'Ariz. Rev. Stat. tit. 28', NULL, NULL, 'UNVERIFIED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.AZ.property', 'AZ', 'property', 'Property tax exemptions vary by county.', 'Ariz. Const. art. IX', 'Finance report gives a $4,188 income-tested cap; Sentinel says no statewide figure is publishable.', NULL, 'UNVERIFIED', ARRAY['src.mod.sentinel','src.rr.transition_finances']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.AL.property', 'AL', 'property', 'Full property tax exemption at 100% disability or age 65+ (up to 160 acres).', 'pending — rule pack v2.0 ''ad valorem homestead exemption'' (unverified)', 'Same text as the Gen-3 client''s STATES_DATA; carried once. One of the eight Alabama rules awaiting G1.', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances','src.legacy.gen3_client']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.AL.retirement', 'AL', 'income', 'Military retirement pay and SBP are exempt from Alabama income tax; BAH, BAS and combat pay exempt.', 'pending — rule pack v2.0 ''military retirement income tax exemption'' (unverified)', NULL, NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances','src.rr.alabama_landscape','src.legacy.gen3_client']::text[]);
INSERT INTO ref.benefit_lead (lead_id, jurisdiction_code, category, text, authority, note, conflict_id, status, source_ids) VALUES ('sb.AL.gi_dependents', 'AL', 'edu_family', 'Alabama G.I. Dependents'' Scholarship: HB284 (2024) raised the tuition cap from $250 to $400 per credit hour effective 2024-07-31; for dependents of veterans rated 40%+.', 'Ala. Code §31-6 (operative section unverified)', 'Highest-value and highest-risk Alabama item (reserved for counsel). Gives a candidate reading for Education Navigator open question oq.al.31-6.award_cap; that question stays open.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_tap','src.rr.alabama_landscape','src.rr.transition_finances','src.mod.education_navigator']::text[]);
