INSERT INTO ref.duty_authority (authority_id, citation, label, qualifies_ch33, tier_caveat, guard_only, coast_guard_only, status, source_ids) VALUES ('a8', '10 USC 12304a', 'Major disaster or emergency', true, true, false, false, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.duty_authority (authority_id, citation, label, qualifies_ch33, tier_caveat, guard_only, coast_guard_only, status, source_ids) VALUES ('a9', '10 USC 12304b', 'Preplanned CCMD support', true, true, false, false, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.duty_authority (authority_id, citation, label, qualifies_ch33, tier_caveat, guard_only, coast_guard_only, status, source_ids) VALUES ('a10', '14 USC 3713', 'Coast Guard Reserve active duty', true, false, false, true, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.duty_authority (authority_id, citation, label, qualifies_ch33, tier_caveat, guard_only, coast_guard_only, status, source_ids) VALUES ('a11', '32 USC 502(f)', 'AGR — organize, administer, recruit, instruct, train', true, false, true, false, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.duty_authority (authority_id, citation, label, qualifies_ch33, tier_caveat, guard_only, coast_guard_only, status, source_ids) VALUES ('a12', '32 USC 502(f)', 'Declared national emergency', true, false, true, false, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.duty_authority (authority_id, citation, label, qualifies_ch33, tier_caveat, guard_only, coast_guard_only, status, source_ids) VALUES ('a13', '32 USC 502(a)', 'Drill (IDT) and annual training', false, false, true, false, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.duty_authority (authority_id, citation, label, qualifies_ch33, tier_caveat, guard_only, coast_guard_only, status, source_ids) VALUES ('a14', 'State code', 'State Active Duty', false, false, true, false, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.duty_authority (authority_id, citation, label, qualifies_ch33, tier_caveat, guard_only, coast_guard_only, status, source_ids) VALUES ('a15', '32 USC 502(f)', 'Other full-time National Guard duty — no emergency declaration', false, false, true, false, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('hl.mst_care', 'women_veterans', 'wv_mst', '38 U.S.C. 1720D; VA MST pages', 'VA provides free care for physical and mental health conditions related to MST. Per the source, no service connection, disability rating, minimum length of service, report or documentation of the event is required, and most former members with OTH or uncharacterized discharges qualify; former Guard/Reserve qualify with federal active-duty service or a service-connected disability.', NULL, 'UNVERIFIED', ARRAY['src.rr.women_veterans_50_state']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('hl.mcc_postpartum', 'women_veterans', 'wv_parenthood', 'VA News, Office of Women''s Health', 'Maternity Care Coordinator support runs from the start of pregnancy to 12 months postpartum, effective 2023-10-01 (previously ended 8 weeks postpartum).', NULL, 'UNVERIFIED', ARRAY['src.rr.women_veterans_50_state']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('comp.tdiu', 'compensation', 'TDIU', '38 CFR 4.16(a)', 'Paid at the 100% schedular rate when service-connected conditions prevent substantially gainful employment and the veteran has one condition rated 60% or more, or a combined 70% or more with at least one condition at 40% (38 CFR 4.16(a)).', 'The rating kernel''s TDIU threshold check is PLANNED in this repo; the v2.0 build had it. Marginal-employment threshold cited by the source: about $14,580 (2025), approximate.', 'UNVERIFIED', ARRAY['src.rr.transition_finances']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('comp.pt_unlocks', 'compensation', 'Permanent and total (P&T) designation', '38 CFR 3.340 (verify)', 'CHAMPVA for spouse and dependents; Chapter 35 DEA education (source: about $1,574/month full-time, Oct 2025–Sep 2026); State property tax exemptions (state-dependent; see state_benefits); VA home loan funding fee waived; Commissary, exchange and MWR access; Space-A travel (per recent NDAA expansions); Federal student loan discharge (TPD); DIC eligibility for a surviving spouse if rated 100% for 8+ continuous years before death', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('ret.high3', 'retirement', 'High-3 (legacy)', '10 U.S.C. (verify per system)', 'multiplier_pct_per_year: 2.5; base: average of highest 36 months of base pay; eligibility: Entered service 1980-09-08 to 2017-12-31 and did not opt into BRS; 20 years of service.', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('ret.brs', 'retirement', 'Blended Retirement System', '10 U.S.C. (verify per system)', 'multiplier_pct_per_year: 2.0; base: average of highest 36 months of base pay; eligibility: Entered 2018-01-01 or later, or opted in during 2018.; tsp: 1% automatic after 60 days; matching begins at 2 years; up to 5% government total; vests at 2 years.; continuation_pay: Between 8 and 12 years of service for an added 4-year commitment; 2.5–13x monthly base pay (active), 0.5–6x (reserve); taxable.; lump_sum: 25% or 50% of discounted present value of pension before full Social Security age; pension reduced until then.', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('ret.redux', 'retirement', 'REDUX / Career Status Bonus (legacy)', '10 U.S.C. (verify per system)', 'note: Multiplier reduced 1 point per year under 30; COLA CPI minus 1% until age 62.', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('ret.ch61', 'retirement', 'Disability retirement (Chapter 61), TDRL / PDRL', '10 U.S.C. (verify per system)', 'note: Service rating 30%+ may retire before 20 years. Pay is the greater of years x multiplier x High-3 or service rating x High-3, capped at 75%. TDRL up to 3 years before PDRL or separation.', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('ret.reserve', 'retirement', 'Guard / Reserve retirement', '10 U.S.C. (verify per system)', 'note: 50 points per good year (15 membership + 35 drill); 20 good years. Pay usually starts at 60, reduced by 90 days for each 90 days of qualifying active duty after 2008-01-28 (not below 50). Formula: points / 360 x multiplier x High-3.', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('ret.crdp', 'retirement', 'CRDP', '10 U.S.C. 1413a / 1414 (verify)', '20+ years (or qualifying TERA/Reserve at 60) and VA rating 50%+; automatic; restores full retired pay; taxable.', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('ret.crsc', 'retirement', 'CRSC', '10 U.S.C. 1413a / 1414 (verify)', 'Combat-related disability, any rating; tax-free; apply with DD Form 2860 to the parent service. CRDP or CRSC, chosen annually (typically January), never both.', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('ret.sbp', 'retirement', 'Survivor Benefit Plan', '10 U.S.C. 1447–1455 (verify)', 'Premium 6.5% of base; survivor receives 55%; paid up after 30 years of payments and age 70. Eliminated January 2023; survivors may receive full SBP and full DIC. Pre-tax premium.', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('fin.income_replacement', 'finance', 'Civilian salary comparison heuristics', 'none (not DoD-published)', 'Civilian gross needed = base x 12 + (BAH + BAS) x 12 x tax multiplier + special pays + TRICARE replacement + TSP match loss + state tax adjustment; tax multiplier = 1 / (1 - marginal effective rate). By grade: E-4 30-35% / 45-55%; E-5 35-40% / 50-60%; E-6 35-40% / 55-65%; E-7/E-8 40-45% / 55-65%; W-3/W-4 35-45% / 55-65%; O-3 35-40% / 55-65%; O-4 35-40% / 55-65%; O-5/O-6 30-40% / 50-60%', 'Rule-of-thumb gross-up multipliers (35–40% low-cost, 55–65% high-cost; 1.35–1.40x base pay) are widely used but not DoD-published. The architecture of record already dropped the unsourced 1.385 gross-up factor (''documented, never applied''); these follow the same rule. Use the Greenbook RMC tables as system-of-record input.', 'HEURISTIC', ARRAY['src.rr.transition_finances']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('fin.separation_cliff', 'finance', 'What ends at separation', 'DoD Greenbook (verify)', 'BAH (ends on DD-214 date, no taper); BAS; TRICARE Prime (replacement $500–$1,400/month premium share); Commissary/exchange savings ($150–$330/month); JAG legal services; On-base CDC childcare savings ($400–$900/month); TSP 5% match (BRS); Clothing allowance; Special and incentive pays; CONUS/OCONUS COLA (OCONUS non-taxable, incl. Alaska and Hawaii)', 'What ends at separation, with typical monthly values from the source. For the financial-transition explainer only; never presented as the user''s number.', 'ILLUSTRATIVE', ARRAY['src.rr.transition_finances']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('gr.ch33', 'guard_reserve', 'Post-9/11 GI Bill', '38 USC 3301', '90 cumulative qualifying days since 11 Sep 2001 meets the eligibility threshold; percentage tier scales with total time. Drill, annual training and State Active Duty do not count.', 'At 85–89 days, orders can sometimes be extended before they expire, almost never after (March 2020 Guard activations were extended for this reason).', 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('gr.ch1606', 'guard_reserve', 'Montgomery GI Bill — Selected Reserve', '10 USC 16132', 'Requires SELRES status and a six-year obligation entered on or after 1 Jul 1985 plus a secondary-school credential. Not vested: ends on transfer out of SELRES (IRR/ING), with tuition-recoupment exposure mid-course.', NULL, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('gr.fta', 'guard_reserve', 'Federal Tuition Assistance', '10 USC 2007; DoDI 1322.25; AR 621-5', '$4,500 per fiscal year, $250 per semester hour, 18 semester hours; master''s $350 per credit hour up to 39 (Army figures). Coast Guard SELRES: $4,500 / $250, one master''s only.', 'FTA pays first; schools deduct it before billing VA. Coast Guard figures rest on a secondary source (confirm COMDTINST). Re-verify FY27 rates after 1 Oct.', 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('gr.army_ca', 'guard_reserve', 'Army Credentialing Assistance', 'AR 621-5; ALARACT 102/2025', 'Funds credentials that need not align to the MOS but must retain a military nexus. Since 19 Mar 2026 every TA and CA request needs supervisor or commander approval in ArmyIgnitED.', 'Officer restriction inferred from an agency summary, not the ALARACT itself.', 'UNVERIFIED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('gr.naturalization', 'guard_reserve', 'Naturalization during hostilities', 'INA 329; 8 USC 1440; USCIS Policy Manual vol. 12 pt. I ch. 3', 'Selected Reserve membership during a designated period of hostilities (11 Sep 2001 to present, open) is qualifying service; no activation, deployment or minimum period required. IRR/ING do not qualify on this path.', 'An earlier draft said drilling status generally does not qualify. That was wrong and is logged rather than silently fixed because it understated a member''s rights.', 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('gr.n426_180_day', 'guard_reserve', '180-day minimum service for N-426 certification', 'Samma v. DoD; service implementing messages', 'SUPERSEDED. The requirement no longer exists; certification needs only an honest assessment that service has been honorable, and the first O-6 in the chain must process it within 30 days.', NULL, 'SUPERSEDED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('gr.rudisill', 'guard_reserve', 'Dual entitlement (Rudisill)', '38 USC 3695(a); Rudisill v. McDonough (2024)', 'Entitlements from separate service periods may be used in any order up to the 48-month aggregate cap with no forced election (held for Ch. 30 and Ch. 33).', 'Extension to a Ch. 1606 + Ch. 33 pairing is reasoning by analogy, not holding; Perkins (No. 24-6515, Vet. App.) may bear on it.', 'CONTESTED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('gr.state_definition_trap', 'guard_reserve', 'State veteran status (structural)', 'State codes', 'Most state benefits key off a state-law definition of veteran requiring federal active duty. Guard service of only drill, annual training and State Active Duty often fails it (Texas Hazlewood needs 181 days).', NULL, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('gr.dod_civilian', 'guard_reserve', 'DoD civilian scope', '5 USC; DoDI 1400.25; 5 USC 2108', 'Civilian employment does not create veteran status or veterans'' preference. A civilian who is also Guard/Reserve is assessed under the military status. Coast Guard permanent civilians are documented as TA-eligible; do not extend by analogy.', NULL, 'SOURCE_CHECKED', ARRAY['src.mod.sentinel']::text[]);
INSERT INTO ref.rule_lead (lead_id, domain, benefit, citation, lead, caveat, status, source_ids) VALUES ('tap.structure', 'tap', 'Transition Assistance Program structure', '10 U.S.C. §§1142, 1144; DoDI 1332.35 (updated 2019-09-26); Army Regulation 600-81', 'TAP must begin no later than 365 days before separation. Individualized Initial Counseling assigns Tier 1 (minimum), Tier 2 (moderate), Tier 3 (maximum; mandatory two-day track). Core: Pre-separation counseling; DoD Transition Day; VA Benefits and Services (Briefings I and II; no exemption permitted); DOL Employment Fundamentals of Career Transition. Tracks: DOL Employment; DoD Education; DOL Vocational / Career Technical; SBA Boots to Business. Capstone verification at least 90 days before separation.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_tap']::text[]);
INSERT INTO ref.timeline_window (window_id, kind, anchor, offset_text, item, verify_against, status, source_ids) VALUES ('tl.tap_start', 'statutory_window', 'separation', '-365 days or earlier', 'Begin TAP (pre-separation counseling) no later than 365 days before separation.', '10 U.S.C. 1142; DoDI 1332.35', 'UNVERIFIED', ARRAY['src.rr.alabama_tap']::text[]);
INSERT INTO ref.timeline_window (window_id, kind, anchor, offset_text, item, verify_against, status, source_ids) VALUES ('tl.tap_capstone', 'statutory_window', 'separation', '-90 days or earlier', 'TAP Capstone verification at least 90 days before separation.', 'DoDI 1332.35', 'UNVERIFIED', ARRAY['src.rr.alabama_tap']::text[]);
INSERT INTO ref.timeline_window (window_id, kind, anchor, offset_text, item, verify_against, status, source_ids) VALUES ('tl.bdd', 'program_window', 'separation', '-180 to -90 days', 'Benefits Delivery at Discharge (pre-discharge VA claim) window.', 'VA BDD program page', 'UNVERIFIED', ARRAY['src.gov.service_architecture','src.rr.transition_finances']::text[]);
INSERT INTO ref.timeline_window (window_id, kind, anchor, offset_text, item, verify_against, status, source_ids) VALUES ('tl.sgli_extension', 'statutory_window', 'separation', '+120 days', 'SGLI coverage continues at no cost for 120 days after separation.', '38 U.S.C. 1968; VA SGLI page', 'UNVERIFIED', ARRAY['src.rr.transition_finances']::text[]);
INSERT INTO ref.timeline_window (window_id, kind, anchor, offset_text, item, verify_against, status, source_ids) VALUES ('tl.vgli_no_underwriting', 'statutory_window', 'separation', '+240 days', 'Convert SGLI to VGLI within 240 days without medical underwriting.', '38 U.S.C. 1977; VA VGLI page', 'UNVERIFIED', ARRAY['src.dod.vgli_afb','src.rr.transition_finances']::text[]);
INSERT INTO ref.timeline_window (window_id, kind, anchor, offset_text, item, verify_against, status, source_ids) VALUES ('tl.military_onesource', 'program_window', 'separation', '+365 days', 'Military OneSource remains available for 365 days after separation (modelled as an expiring right in Next Best Action band 2).', 'Military OneSource eligibility page', 'UNVERIFIED', ARRAY['src.gov.master_record']::text[]);
INSERT INTO ref.timeline_window (window_id, kind, anchor, offset_text, item, verify_against, status, source_ids) VALUES ('tl.sbp_election', 'program_window', 'retirement', 'election at retirement; irrevocable after the one-year window', 'Survivor Benefit Plan election.', 'DFAS SBP pages', 'UNVERIFIED', ARRAY['src.rr.transition_finances']::text[]);
INSERT INTO ref.timeline_window (window_id, kind, anchor, offset_text, item, verify_against, status, source_ids) VALUES ('tl.leave_sellback', 'limit', 'career', 'lifetime', 'Leave sell-back limited to 60 days over a career.', '37 U.S.C. 501', 'UNVERIFIED', ARRAY['src.rr.transition_finances']::text[]);
INSERT INTO ref.timeline_window (window_id, kind, anchor, offset_text, item, verify_against, status, source_ids) VALUES ('tl.itf', 'statutory_window', 'intent_to_file', '+1 year', 'An Intent to File preserves the effective date for one year (the platform tracks the expiry; it never files).', '38 CFR 3.155', 'UNVERIFIED', ARRAY['src.gov.master_record','src.gov.service_architecture']::text[]);
INSERT INTO ref.timeline_window (window_id, kind, anchor, offset_text, item, verify_against, status, source_ids) VALUES ('tl.vgli_apply', 'statutory_window', 'separation', '+1 year 120 days', 'Last day to apply for VGLI after separation (proof of good health is needed after day 240).', '38 U.S.C. 1977; VA VGLI page', 'UNVERIFIED', ARRAY['src.dod.vgli_afb']::text[]);
INSERT INTO ref.timeline_window (window_id, kind, anchor, offset_text, item, verify_against, status, source_ids) VALUES ('tl.effective_date_separation', 'statutory_window', 'separation', '+1 year', 'A disability claim received within 1 year of separation can take the day after separation as its effective date.', '38 CFR 3.400(b)(2)', 'UNVERIFIED', ARRAY['src.gov.service_architecture']::text[]);
INSERT INTO ref.timeline_window (window_id, kind, anchor, offset_text, item, verify_against, status, source_ids) VALUES ('tl.decision_review', 'statutory_window', 'decision_letter', '+1 year', 'Request a Higher-Level Review or Board Appeal within 1 year of the decision letter; a Supplemental Claim filed within 1 year keeps the original effective date.', '38 CFR 3.2500; VA decision review pages', 'UNVERIFIED', ARRAY['src.gov.service_architecture']::text[]);
INSERT INTO ref.education_program (program_id, name, authority, carried_by, stacking_notes, note, is_authority_stub, status, source_ids) VALUES ('edu.fed.ch33', 'Post-9/11 GI Bill', '38 U.S.C. ch. 33', ARRAY['ednav:fed.ch33.post911','v2.0','sentinel:gr.ch33']::text[], 'Must elect one with ch. 30, 1606 and 31 (Rudisill nuance); may not combine with TA for the same charges; sequence against the Alabama scholarship unverified.', NULL, true, 'UNVERIFIED', ARRAY['src.mod.education_navigator','src.gov.master_record','src.mod.sentinel']::text[]);
