INSERT INTO ref.installation (installation_id, jurisdiction_code, name, place, branch, role, approx_population, tap_delivery, former_name, status, source_ids) VALUES ('inst.al.maxwell_gunter', 'AL', 'Maxwell-Gunter AFB', 'Montgomery', 'Air Force', 'Air University, PME (Air War College, ACSC, SOS, CCAF)', '~12,000', 'Full TAP at 42d Force Support Squadron Airman & Family Readiness Center (Bldg 677); five-day workshop. SkillBridge applications moved into AFVEC on 2025-06-26.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.installation (installation_id, jurisdiction_code, name, place, branch, role, approx_population, tap_delivery, former_name, status, source_ids) VALUES ('inst.al.redstone', 'AL', 'Redstone Arsenal', 'Huntsville', 'Army', 'AMC, MDA, NASA Marshall, FBI HQ-South', '~40,000 (largely civilian)', 'Virtual-only SFL-TAP since 2025-05-12; was a volunteer-supported satellite, never a funded center. In-person fallback is Fort Rucker (334-255-2558); 50+ miles away use the SFL-TAP Virtual Center (1-800-325-4715).', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.installation (installation_id, jurisdiction_code, name, place, branch, role, approx_population, tap_delivery, former_name, status, source_ids) VALUES ('inst.al.fort_rucker', 'AL', 'Fort Rucker (formerly Fort Novosel)', 'Dale County', 'Army', 'U.S. Army Aviation Center of Excellence', '~12,000–15,000', 'Only fully resourced contractor-staffed SFL-TAP center in Alabama; primary live node after the Redstone change. Heavy warrant-officer and aviator flow; strong SkillBridge use.', 'Fort Novosel', 'UNVERIFIED', ARRAY['src.rr.alabama_tap','src.rr.alabama_landscape']::text[]);
INSERT INTO ref.installation (installation_id, jurisdiction_code, name, place, branch, role, approx_population, tap_delivery, former_name, status, source_ids) VALUES ('inst.al.anniston', 'AL', 'Anniston Army Depot', 'Calhoun County', 'Army', 'Tracked combat vehicles and small arms (mostly civilian workforce)', '~7,000', 'No full TAP center; Virtual Center, or travel to Fort Rucker, Fort Moore (GA) or Fort Campbell (KY). GAO small/remote-installation profile.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.installation (installation_id, jurisdiction_code, name, place, branch, role, approx_population, tap_delivery, former_name, status, source_ids) VALUES ('inst.al.uscg_mobile', 'AL', 'USCG Aviation Training Center Mobile', 'Mobile', 'Coast Guard', 'Fixed and rotary aviation training', '~700', 'Coast Guard TAP; still implementing FY19 NDAA counseling pathways as of late 2023.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('wv.dv_reconcile.1', 'data_maintenance', 'KY', 'DV coalition directory reconciliation', 'Kentucky''s coalition is now ZeroV.', NULL, 'SOURCE_CHECKED', ARRAY['src.mod.women_veterans']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('wv.dv_reconcile.2', 'data_maintenance', 'ND', 'DV coalition directory reconciliation', 'North Dakota''s is now North Dakota Domestic & Sexual Violence Coalition (formerly CAWS North Dakota).', NULL, 'SOURCE_CHECKED', ARRAY['src.mod.women_veterans']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('wv.dv_reconcile.3', 'data_maintenance', 'FEDERAL', 'DV coalition directory reconciliation', 'Verify current names for Minnesota (Violence Free Minnesota), Colorado (Violence Free Colorado), Wisconsin (End Domestic Abuse Wisconsin), Florida (Florida Partnership to End Domestic Violence), Massachusetts (Jane Doe Inc.).', NULL, 'SOURCE_CHECKED', ARRAY['src.mod.women_veterans']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('wv.dv_reconcile.4', 'data_maintenance', 'OK', 'DV coalition directory reconciliation', 'NNEDV lists no Oklahoma coalition; it points to the Oklahoma Attorney General''s certified-programs list.', NULL, 'SOURCE_CHECKED', ARRAY['src.mod.women_veterans']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('sb.decision_framework', 'product_implication', NULL, 'State-selection comparison factors', 'State income tax on retirement and civilian wages; Property tax and disabled-veteran exemption; Sales, vehicle and fuel taxes; State dependent education benefits; Cost-of-living index; Health care access and VA medical center proximity; State employment preference points', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('al.adva', 'state_program', 'AL', 'Alabama Department of Veterans Affairs (ADVA)', 'About $230M total budget including federal pass-through and trust funds; $175.6M tracked state appropriation in FY2025 ($5.08M General Fund + $170.5M earmarked). 62 county Veterans Service Offices (12 added in the past 36 months per source). Main line (334) 242-5077.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_tap','src.rr.alabama_landscape']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('al.avrc', 'state_program', 'AL', 'Alabama Veterans Resource Center (AVRC)', 'Public corporation created by Senate Bill 70 (2025) with a $5M initial appropriation, located in Montgomery; board appointments announced July 2025. Designed to fill the state flagship-program gap.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('al.gi_dependents', 'state_program', 'AL', 'Alabama G.I. Dependents'' Scholarship', 'HB284 (2024) raised the cap from $250 to $400 per credit hour effective 2024-07-31. See state_benefits sb.AL.gi_dependents.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_tap','src.rr.alabama_landscape']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('al.state_homes', 'state_program', 'AL', 'State veterans homes', 'Five homes (~700+ beds). CSM Bennie G. Adkins State Veterans Home in Enterprise opened September 2024 (~$115M federal-state cost share).', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('al.jvsg', 'state_program', 'AL', 'Jobs for Veterans State Grant staffing (Alabama Career Centers)', '21 DVOP specialists, 12 LVERs, 3 Consolidated Outreach and Development Liaisons; $2.5–4M JVSG per year (estimate).', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('al.hvrp', 'state_program', 'AL', 'Homeless Veterans Reintegration Program grantees', 'Aletheia House (Birmingham, Montgomery); Volunteers of America Southeast (Mobile Eagle''s Landing, Tuscaloosa Valor Grove); typically $300K–$500K per grantee per year.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('al.workforce_portal', 'state_program', 'AL', 'Workforce Alabama job portal and ADOL DVOP/LVER specialists', 'Above-federal-floor service without a branded state transition flagship.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('al.heroes_welcome', 'state_program', 'AL', 'Heroes Welcome Initiative (interstate licensure compact participation)', 'Named as the lever for military-spouse licensing; links to reciprocity gap CB-06.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('al.no_home_loan_program', 'state_program', 'AL', 'No state veteran home-loan program', 'Alabama veterans rely on the federal VA loan (contrast Texas VLB, CalVet, Wisconsin trust fund).', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('flagship.va', 'peer_flagship', 'VA', 'Virginia Values Veterans (V3)', 'Codified employer certification (Code of VA § 2.2-2001.2) with transition teams at installations.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('flagship.fl', 'peer_flagship', 'FL', 'Veterans Florida', 'State-authorized nonprofit integrating SkillBridge, entrepreneurship and a career portal.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('flagship.tx', 'peer_flagship', 'TX', 'Texas Veterans Commission + GLO Veterans Land Board', '170+ employment reps in 75+ cities; Hazlewood; College Credit for Heroes; Operation Welcome Home.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('flagship.nc', 'peer_flagship', 'NC', 'NC4ME', 'Public-private partnership with NCWorks priority postings and 50 veteran specialists.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('flagship.sc', 'peer_flagship', 'SC', 'Operation Palmetto Employment', 'Tiered veteran-friendly employer recognition; SC Smart Start virtual platform.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('flagship.ga', 'peer_flagship', 'GA', 'GA VECTR Center (Warner Robins)', 'Purpose-built brick-and-mortar transition center.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('flagship.ca', 'peer_flagship', 'CA', 'CalTAP', '23-module state curriculum, online and in eight regional centers.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('flagship.tn', 'peer_flagship', 'TN', 'STRONG Act / Helping Heroes Grant', 'Named by the TAP report as Tennessee''s state program.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('oversight.gao-23-104538', 'oversight_finding', 'FEDERAL', 'GAO-23-104538 (Dec 2022)', '70% of separating members did not start TAP at least one year out; about 25% of Tier 3 members skipped the mandatory two-day class; services waived the two-day class for 53% of members.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('oversight.gao-24-106248', 'oversight_finding', 'FEDERAL', 'GAO-24-106248 (Mar 2024)', '4,300 required warm handovers to VA, DOL or SBA not delivered (Apr 2021–Mar 2023); one-third of ~41,000 logged handovers unverified; 77,711 members verified by commanders with no recorded handover.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('oversight.gao-24-107752', 'oversight_finding', 'FEDERAL', 'GAO-24-107752 (2024)', 'inTransition did not connect with over 70% of eligible members it identified in 2022.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('oversight.dodig-2022-030', 'oversight_finding', 'FEDERAL', 'DODIG-2022-030', 'All five suicide-prevention recommendations for transitioning members still open as of January 2024.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('oversight.rand-rr-a1363-12', 'oversight_finding', 'FEDERAL', 'RAND RR-A1363-12 (2023)', 'Of $14.3B federal transition spending in FY2019 only $140M went to TAP; raw analysis associates TAP participation with lower wages, attributed mainly to selection effects.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('oversight.ivmf-o2o-eval', 'oversight_finding', 'FEDERAL', 'Penn State Clearinghouse evaluation of IVMF Onward to Opportunity (2022)', 'Only rigorously evaluated transition program found; positive effects on starting salary and six-month retention.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('oversight.bsf-mfls-2024', 'oversight_finding', 'FEDERAL', 'Blue Star Families Military Family Lifestyle Survey 2024', '28% of veterans used TAP and found it helpful, 23% used it and did not, 49% did not use it; 54% who found useful resources found them through peers.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('oversight.vfw-2023', 'oversight_finding', 'FEDERAL', 'VFW congressional testimony (May 2023)', '62% began TAP less than a year out; one-third did not get or did not know about required community-resource connections; nearly one-third did not know their tier; 15%+ of spouses could not attend or did not know they could.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('oversight.legion-2025', 'oversight_finding', 'FEDERAL', 'American Legion testimony ''Mission Incomplete'' (Mar 2025)', 'Veterans'' main hurdle is finding reliable resources.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('works.1', 'what_works', 'FEDERAL', 'What works in transition', 'SBA Boots to Business: 241,000+ graduates since 2013; 91% of veteran-founded businesses operating after one year (per SBA as cited).', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('works.2', 'what_works', 'FEDERAL', 'What works in transition', 'VA Benefits Briefings I and II: 94–96% satisfaction historically.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('works.3', 'what_works', 'FEDERAL', 'What works in transition', 'DoD SkillBridge: 12,000+ enrolled in Q1–Q2 FY2024; 3,000+ partner organizations.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('works.4', 'what_works', 'FEDERAL', 'What works in transition', 'DAV Transition Service Officers: 38 TSOs at 109+ installations; 39,000+ members assisted in 2024.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('works.5', 'what_works', 'FEDERAL', 'What works in transition', 'Counseling pathways: 90%+ participation Apr 2021–Mar 2022.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('works.6', 'what_works', 'FEDERAL', 'What works in transition', 'VA Solid Start: permanent under the Solid Start Act of 2022 (Pub. L. 117-205); contacted 71% of eligible veterans in 2021.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('event.01', 'policy_event', 'FEDERAL', 'FY2019 NDAA TAP reforms take effect (Pub. L. 115-232 §552)', 'FY2019 NDAA TAP reforms take effect (Pub. L. 115-232 §552): tiers, counselor meetings, self-assessment, 365-day start.', '2019-10-01', 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('event.02', 'policy_event', 'FEDERAL', 'DoD Military-Civilian Transition Office created (TVPO + Office of Reintegration ', 'DoD Military-Civilian Transition Office created (TVPO + Office of Reintegration Programs).', '2020-01', 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('event.03', 'policy_event', 'FEDERAL', 'Isakson-Roe Act §4303 (Pub. L. 116-315) authorizes DOL Off-Base Transition Train', 'Isakson-Roe Act §4303 (Pub. L. 116-315) authorizes DOL Off-Base Transition Training pilot; no Alabama site; five-year authority sunsetting absent reauthorization.', '2021-01-05', 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('event.04', 'policy_event', 'FEDERAL', 'Solid Start Act of 2022 (Pub. L. 117-205) makes VA Solid Start permanent.', 'Solid Start Act of 2022 (Pub. L. 117-205) makes VA Solid Start permanent.', '2022', 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('event.05', 'policy_event', 'FEDERAL', 'FY2024 NDAA (Pub. L. 118-31) adds TAP accountability and SkillBridge oversight.', 'FY2024 NDAA (Pub. L. 118-31) adds TAP accountability and SkillBridge oversight.', '2023', 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('event.06', 'policy_event', 'AL', 'HB284', 'HB284: Alabama G.I. Dependents'' Scholarship cap $250 → $400 per credit hour.', '2024-07-31', 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('event.07', 'policy_event', 'AL', 'CSM Bennie G. Adkins State Veterans Home opens in Enterprise.', 'CSM Bennie G. Adkins State Veterans Home opens in Enterprise.', '2024-09', 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('event.08', 'policy_event', 'AL', 'Redstone Arsenal SFL-TAP becomes virtual-only.', 'Redstone Arsenal SFL-TAP becomes virtual-only.', '2025-05-12', 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('event.09', 'policy_event', 'AL', 'SB70 creates the Alabama Veterans Resource Center with $5M.', 'SB70 creates the Alabama Veterans Resource Center with $5M.', '2025-05', 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('event.10', 'policy_event', 'AL', 'Fort Novosel redesignated Fort Rucker (ceremony 2025-07-17).', 'Fort Novosel redesignated Fort Rucker (ceremony 2025-07-17).', '2025-06-11', 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('event.11', 'policy_event', 'AL', 'Air Force SkillBridge applications move into AFVEC.', 'Air Force SkillBridge applications move into AFVEC.', '2025-06-26', 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('implication.1', 'product_implication', 'AL', 'Product implication', 'Start the transition clock at 365+ days: most members start TAP late, so the Mission Brief should surface TAP timing as a first-five action.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('implication.2', 'product_implication', 'AL', 'Product implication', 'Spouses are routinely excluded from TAP; spouse_family is already a transition track and should get its own brief.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('implication.3', 'product_implication', 'AL', 'Product implication', 'Warm handovers fail silently; the closed-loop referral state machine (Plane 2) is the countermeasure.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('implication.4', 'product_implication', 'AL', 'Product implication', 'Rural installations (Fort Rucker, Anniston) and the Redstone virtual shift raise the value of a digital state layer.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('implication.5', 'product_implication', 'AL', 'Product implication', 'First-year post-separation suicide risk is about 2.5x the active-duty rate and inTransition misses 70%+: the crisis floor must be on every screen (already true) and the crisis detector (R16) is a priority once agents exist.', NULL, 'UNVERIFIED', ARRAY['src.rr.alabama_landscape','src.rr.alabama_tap']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('prep.m18', 'preparation_step', NULL, '18 months before separation', 'Update TSP allocation and beneficiaries; Confirm state of legal residence; Start resume and LinkedIn; Check SkillBridge eligibility', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances','src.rr.alabama_tap','src.mod.women_veterans']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('prep.m15', 'preparation_step', NULL, '15 months before separation', 'Run the civilian salary comparison; Shortlist 2–3 candidate states', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances','src.rr.alabama_tap','src.mod.women_veterans']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('prep.m12', 'preparation_step', NULL, '12 months before separation', 'Start TAP; Plan a pre-discharge (BDD) claim with an accredited representative; Review BRS continuation pay window if 8–12 years of service', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances','src.rr.alabama_tap','src.mod.women_veterans']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('prep.m09', 'preparation_step', NULL, '9 months before separation', 'Review retirement-system choices; Understand the SBP election', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances','src.rr.alabama_tap','src.mod.women_veterans']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('prep.m06', 'preparation_step', NULL, '6 months before separation', 'Compare health coverage (employer, ACA marketplace, COBRA, CHCBP, TRS for Reserve); Lock the housing plan; Request a VA home loan Certificate of Eligibility if buying', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances','src.rr.alabama_tap','src.mod.women_veterans']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('prep.m04', 'preparation_step', NULL, '4 months before separation', 'Get every claimed condition documented before separation exams; Review SGLI conversion', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances','src.rr.alabama_tap','src.mod.women_veterans']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('prep.m03', 'preparation_step', NULL, '3 months before separation', 'Final pay and leave sell-back; BRS lump-sum decision', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances','src.rr.alabama_tap','src.mod.women_veterans']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('prep.m02', 'preparation_step', NULL, '2 months before separation', 'Decide on VGLI or commercial term life', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances','src.rr.alabama_tap','src.mod.women_veterans']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('prep.m01', 'preparation_step', NULL, '1 months before separation', 'Verify direct deposit; Confirm the VA claim was submitted by your representative; Finalize state residency; Update DEERS', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances','src.rr.alabama_tap','src.mod.women_veterans']::text[]);
INSERT INTO ref.finding (finding_id, kind, jurisdiction_code, title, detail, event_date, status, source_ids) VALUES ('prep.m00', 'preparation_step', NULL, 'Separation day', 'Receive DD-214; Confirm commissary and exchange access if retiring', NULL, 'UNVERIFIED', ARRAY['src.rr.transition_finances','src.rr.alabama_tap','src.mod.women_veterans']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('NN-1', 'non_negotiable', 'No guarantees. No agent states or implies that a veteran will receive a benefit, a rating percentage, a dollar amount, an approval, or a timeline. Every eligibility output is a status from the deterministic engine, never a promise.', NULL, NULL, NULL, NULL, ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('NN-2', 'non_negotiable', 'Everything is a recommendation. Resumes, plans, letters and checklists are drafts the veteran reviews, owns, and decides whether to use.', NULL, NULL, NULL, NULL, ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('NN-3', 'non_negotiable', 'The CFR is a reference, not a diagnosis. Agents may cite 38 CFR to explain how VA describes criteria; they never apply criteria to the veteran to produce a diagnosis, code or rating.', NULL, NULL, NULL, NULL, ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('NN-4', 'non_negotiable', 'Accredited representation is the path to a claim. Any conversation moving toward preparing, presenting or prosecuting a claim ends in a referral to a VA-accredited VSO representative, claims agent or attorney.', NULL, NULL, NULL, NULL, ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('T0-01', 'tier0', 'No output may guarantee a benefit, rating, amount, approval or timeline.', 'OutputGuard (guarantee patterns)', 'Replace with engine text plus standard disclaimer', 'PARTIAL', 'Pattern set in config/governance_language.yaml; scanned over task copy and the reference corpus in tests. No model output exists yet.', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('T0-02', 'tier0', 'No output may assign a disability rating percentage or diagnostic code to the user.', 'OutputGuard + ClaimsBoundaryGuard', 'Block; return referral to accredited rep', 'PARTIAL', 'Rating kernel is labelled arithmetic, not a forecast; rating patterns scanned.', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('T0-03', 'tier0', 'No output may diagnose or state the user has an undocumented condition.', 'ClaimsBoundaryGuard', 'Block; reframe as talk to your provider', 'PARTIAL', NULL, ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('T0-04', 'tier0', 'No agent may prepare, sign, submit or argue a claim, appeal or Intent to File.', 'ApprovalGate action denylist', 'Hard deny; log; referral', 'IMPLEMENTED_TESTED', 'No such path exists in the code.', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('T0-05', 'tier0', 'Every eligibility status comes from the deterministic rules engine; models only explain it.', 'Rules engine + OutputGuard', 'Model text discarded', 'PARTIAL', 'Router and rating kernel deterministic; eligibility engine PLANNED (G1).', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('T0-06', 'tier0', 'Every eligibility, rate, deadline or CFR claim carries a citation from the source registry.', 'CitationValidator', 'Downgrade to HUMAN_REQUIRED, never delete', 'PARTIAL', 'Every reference record must name a registered source (validator + DB check); no runtime validator.', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('T0-07', 'tier0', 'Absent facts stay UNKNOWN; a blank is never a no.', 'FactResolver sentinel', 'Status more_info_required', 'IMPLEMENTED_TESTED', 'Unknown date or authority becomes a task (router).', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('T0-08', 'tier0', 'Crisis resources are never suppressed, delayed or rate-limited.', 'CrisisGate, runs first', 'Halt pipeline, return contacts', 'PARTIAL', 'Crisis floor on every screen and re-injected in reference responses; no detector.', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('T0-09', 'tier0', 'Resume and outbound documents contain only verified, user-supplied facts.', 'FabricationGuard + EvidenceGate', 'Strip unverified line, flag', 'PLANNED', NULL, ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('T0-10', 'tier0', 'Protected fields (rating, diagnoses, MST, VA file number, SSN) never reach an employer-facing artifact without per-document opt-in.', 'ProtectedFieldGuard', 'Strip field, log', 'PLANNED', NULL, ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('T0-11', 'tier0', 'Cross-module reads are purpose-scoped and consented.', 'ConsentBroker', 'ConsentError, no read', 'PARTIAL', 'Consent checked in-transaction; purpose allowlist; nine foreclosed purposes (0010).', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('T0-12', 'tier0', 'No agent approves its own gated action.', 'Self-approval prohibition', 'Deny', 'PARTIAL', 'Schema CHECK no_self_approval (0005); service-layer check lands with approvals.', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('R1', 'agent_rule', 'Says it is an AI, not VA, a VSO, an attorney or a clinician.', NULL, NULL, 'PARTIAL', 'v2.0 build: Built', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('R2', 'agent_rule', 'Explains what the engine decided; never decides eligibility, a rating or an amount.', NULL, NULL, 'IMPLEMENTED_TESTED', 'v2.0 build: Built', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('R3', 'agent_rule', 'Never prepares, signs or submits a claim, ITF, review or Form 21-22.', NULL, NULL, 'IMPLEMENTED_TESTED', 'v2.0 build: Partly', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('R4', 'agent_rule', 'Every claims-help feature is free.', NULL, NULL, 'PLANNED', 'v2.0 build: Add. No billing exists.', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('R5', 'agent_rule', 'Refers to an accredited rep the veteran chooses; discloses partners; ranking blind to them.', NULL, NULL, 'PARTIAL', 'v2.0 build: Add', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('R6', 'agent_rule', 'Cites a tier 1–3 source for every factual sentence.', NULL, NULL, 'PLANNED', 'v2.0 build: Built', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('R7', 'agent_rule', 'Missing fact is unknown and asked for; never ''not eligible'', never estimated.', NULL, NULL, 'IMPLEMENTED_TESTED', 'v2.0 build: Built', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('R8', 'agent_rule', 'Never guarantees, diagnoses, or suggests a medical nexus.', NULL, NULL, 'PARTIAL', 'v2.0 build: Partly', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('R9', 'agent_rule', 'Never coaches overstating symptoms or inventing events.', NULL, NULL, 'PLANNED', 'v2.0 build: Partly', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('R10', 'agent_rule', 'Every number comes from the engine, never the model.', NULL, NULL, 'IMPLEMENTED_TESTED', 'v2.0 build: Partly', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('R11', 'agent_rule', 'Sees data only through a Guardian ContextPacket.', NULL, NULL, 'PLANNED', 'v2.0 build: Built', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
INSERT INTO ref.governance_rule (rule_id, family, text, enforced_by, on_violation, repo_status, note, source_ids) VALUES ('R12', 'agent_rule', 'Acts only for the signed-in person.', NULL, NULL, 'IMPLEMENTED_TESTED', 'v2.0 build: Add', ARRAY['src.gov.agent_rules','src.gov.master_record']::text[]);
