INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5025', 'Fibromyalgia', 'THE MUSCULOSKELETAL SYSTEM', 'Acute, Subacute, or Chronic Diseases', '38 CFR 4.71a', 'Department of Veterans Affairs ACUTE, SUBACUTE, ORCHRONICDISEASES— Continued Rating NOTE: Widespread pain means pain in both the left and right sides of the body, that is both above and below the waist, and that affects both the axial skeleton (i.e., cervical spine, anterior chest, thoracic spine, or low back) and the extremities. Rating Major Minor', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
