INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5148', 'Index and little', 'THE MUSCULOSKELETAL SYSTEM', 'Multiple Finger Amputations', NULL, NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5149', 'Long and ring', 'THE MUSCULOSKELETAL SYSTEM', 'Multiple Finger Amputations', '38 CFR 4.71a', '(a) The ratings for multiple finger amputations apply to amputations at the proximal interphalangeal joints or through proximal phalanges.. (b) Amputation through middle phalanges will be rated as prescribed for unfavorable ankylosis of the fingers.. Department of Veterans Affairs AMPUTATIONS: Rating Major Minor (c) Amputations at distal joints, or through distal phalanges, other than negligible losses, will be rated as prescribed for favorable ankylosis of the fingers.. (d) Amputation or resection of metacarpal bones (more than one-half the bone lost) in multiple fingers injuries will require a rating of 10 percent added to (not combined with) the ratings, multiple finger amputations, subject to the amputation rule applied to the forearm. (e) Combinations of finger amputations at various levels, or finger amputations with ankylosis or limitation of motion of the fingers will be rated on the basis of the grade of disability; i.e., amputation, unfavorable ankylosis, most representative of the levels or combinations. With an even number of fingers involved, and adjacent grades of disability, select the higher of the two grades. (f) Loss of use of the hand will be held to exist when no effective function remains other than that which would be equally well served by an amputation stump with a suitable prosthetic appliance.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5150', 'Long and little', 'THE MUSCULOSKELETAL SYSTEM', 'Multiple Finger Amputations', NULL, NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
