INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5213', 'Supination and pronation, impairment', 'THE MUSCULOSKELETAL SYSTEM', 'Elbow and Forearm', '38 CFR 4.71a', 'NOTE: In all the forearm and wrist injuries, codes 5205 through 5213, multiple impaired finger movements due to tendon tie-up, muscle or nerve injury, are to be separately rated and combined not to exceed rating for loss of use of hand. Rating Major Minor', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5214', 'Wrist, ankylosis', 'THE MUSCULOSKELETAL SYSTEM', 'Wrist', '38 CFR 4.71a', 'NO T E : E x tr e m e l y u n f a v o r a b le a n k y lo s is w i ll b e r a te d a s l o s s o f u s e o f h a n d s under diagnostic code 5125.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5215', 'Wrist, limitation of motion', 'THE MUSCULOSKELETAL SYSTEM', 'Wrist', '38 CFR 4.71a', 'degrees, the metacarpophalangeal and proximal interphalangeal joints flexed to 30 degrees, and the thumb (digit I) abducted and rotated so that the thumb pad faces the finger pads. Only joints in these positions are considered to be in favorable position. For digits II through V, the metacarpophalangeal joint has a range of zero to 90 degrees of flexion, the proximal interphalangeal joint has a range of zero to 100 degrees of flexion, and the distal (terminal) interphalangeal joint has a range of zero to 70 or 80 degrees of flexion (2) When two or more digits of the same hand are affected by any combination of amputation, ankylosis, or limitation of motion that is not otherwise specified in the rating schedule, the evaluation level assigned will be that which best represents the overall disability (i.e., amputation, unfavorable or favorable ankylosis, or limitation of motion), assigning the higher level of evaluation when the level of disability is equally balanced between one level and the next higher level (3) Evaluation of ankylosis of the index, long, ring, and little fingers: (i) If both the metacarpophalangeal and proximal interphalangeal joints of a digit are ankylosed, and either is in extension or full flexion, or there is rotation or angulation of a bone, evaluate as amputation without metacarpal resection, at proximal interphalangeal joint or proximal thereto (ii) If both the metacarpophalangeal and proximal interphalangeal joints of a digit are ankylosed, evaluate', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5216', 'Five digits of one hand', 'THE MUSCULOSKELETAL SYSTEM', 'Limitation of Motion', '38 CFR 4.71a', 'Note: Also consider whether evaluation as amputation is warranted.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5217', 'Four digits of one hand', 'THE MUSCULOSKELETAL SYSTEM', 'Limitation of Motion', '38 CFR 4.71a', 'Note: Also consider whether evaluation as amputation is warranted.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
