INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5242', 'Degenerative arthritis', 'THE MUSCULOSKELETAL SYSTEM', 'Spine', '38 CFR 4.71a', 'of the spine (see also diagnostic code 5003)', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5243', 'Intervertebral disc syndrome', 'THE MUSCULOSKELETAL SYSTEM', 'Spine', '38 CFR 4.71a', 'Rating Note (1): For purposes of evaluations under diagnostic code 5243, an incapacitating episode is a period of acute signs and symptoms due to intervertebral disc syndrome that requires bed rest prescribed by a physician and treatment by a physician. Note (2): If intervertebral disc syndrome is present in more than one spinal segment, provided that the effects in each spinal segment are clearly distinct, evaluate each segment on the basis of incapacitating episodes or under the General Rating Formula for Diseases and Injuries of the Spine, whichever method results in a higher evaluation for that segment. >HPG/<300.30ua72re Department of Veterans Affairs Rating', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5250', 'Hip, ankylosis', 'THE MUSCULOSKELETAL SYSTEM', 'Hip and Thigh', '38 CFR 4.71a', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
