INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5284', 'Foot injuries, other', 'THE MUSCULOSKELETAL SYSTEM', 'The Foot', '38 CFR 4.71a', 'NOTE: With actual loss of use of the foot, rate 40 percent. Rating', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5296', 'Loss of part of', 'THE MUSCULOSKELETAL SYSTEM', 'The Skull', '38 CFR 4.71a', 'Rating NOTE: Rate separately for intracranial complications. Rating', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5297', 'Removal of', 'THE MUSCULOSKELETAL SYSTEM', 'The Ribs', '38 CFR 4.71a', 'NOTE(1): The rating for rib resection or removal is not to be applied with ratings for purrulent pleurisy, lobectomy, pneumonectomy or injuries of pleural cavity. NOTE(2): However, rib resection will be considered as rib removal in thoracoplasty performed for collapse therapy or to accomplish obliteration of space and will be combined with the rating for lung collapse, or with the rating for lobectomy, pneumonectomy or the graduated ratings for pulmonary tuberculosis. Rating', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5298', 'Removal of', 'THE MUSCULOSKELETAL SYSTEM', 'The Coccyx', '38 CFR 4.71a', '10 (Authority: 38 U.S.C. 1155) [29 FR 6718, May 22, 1964, as amended at 34 FR 5062, Mar. 11, 1969; 40 FR 42536, Sept. 15, 30 1975; 41 FR 11294, Mar. 18, 1976; 43 FR 45350, 20 Oct. 2, 1978; 51 FR 6411, Feb. 24, 1986; 61 FR 20439, May 7, 1996; 67 FR 48785, July 26, 2002; 67 FR 54349, Aug. 22, 2002; 68 FR 51456, Aug. 27, 2003; 69 FR 32450, June 10, 2004; 80 FR 30 42041, July 16, 2015] [Reserved]', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5301', 'Group I Function: Upward rotation of scapula', 'MUSCLE INJURIES', 'Shoulder Girdle and Arm', '38 CFR 4.73', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
