INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5304', 'Group IV Function: Stabilization of shoulder', 'MUSCLE INJURIES', 'Shoulder Girdle and Arm', '38 CFR 4.73', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5305', 'Group V Function: Elbow supination', 'MUSCLE INJURIES', 'Shoulder Girdle and Arm', '38 CFR 4.73', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
