INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5307', 'Group VII Function: Flexion of wrist and fingers', 'MUSCLE INJURIES', 'Forearm and Hand', '38 CFR 4.73', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5308', 'Group VIII Function: Extension of wrist, fingers, thumb', 'MUSCLE INJURIES', 'Forearm and Hand', '38 CFR 4.73', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5309', 'Group IX Function: Forearm muscles', 'MUSCLE INJURIES', 'Forearm and Hand', '38 CFR 4.73', 'Group IX. Function: The forearm muscles act in strong grasping movements and are supplemented by the intrinsic muscles in delicate manipulative movements. Intrinsic muscles of hand: 0 Thenar eminence; short flexor, opponens, abductor and adductor of thumb; hypothenar eminence; short flexor, opponens and abductor of little finger; 4 lumbricales; 4 dorsal and 3 palmar interossei. NOTE: The hand is so compact a structure that isolated muscle injuries are rare, being nearly always complicated with injuries of bones, joints, tendons, etc. Rate on limitation of motion, minimum 10 percent. Rating', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5310', 'Group X Function: Movement of forefoot and toes', 'MUSCLE INJURIES', 'Foot and Leg', '38 CFR 4.73', 'Rating NOTE: Minimum rating for through-and-through wounds of the foot—10.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
