INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5322', 'Group XXII Function: Rotary and forward movements, head', 'MUSCLE INJURIES', 'Torso and Neck', NULL, NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5323', 'Group XXIII Function: Movements of head', 'MUSCLE INJURIES', 'Torso and Neck', '38 CFR 4.73', 'Rating', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5324', 'Diaphragm, rupture', 'MUSCLE INJURIES', 'Miscellaneous', '38 CFR 4.73', 'of, with herniation. Rate under diagnostic code 7346.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5325', 'Muscle injury, facial muscles', 'MUSCLE INJURIES', 'Miscellaneous', '38 CFR 4.73', 'Evaluate functional impairment as seventh (facial) cranial nerve neuropathy (diagnostic code 8207), disfiguring scar (diagnostic code 7800), etc. Minimum, if interfering to any extent with mastication—10.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5326', 'Muscle hernia', 'MUSCLE INJURIES', 'Miscellaneous', '38 CFR 4.73', 'extensive. Without other injury to the muscle—10.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5327', 'Muscle, neoplasm of, malignant', 'MUSCLE INJURIES', 'Miscellaneous', '38 CFR 4.73', '(excluding soft tissue sarcoma)—100. NOTE: A rating of 100 percent shall continue beyond the cessation of any surgery, radiation treatment, antineoplastic chemotherapy or other therapeutic procedures. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter. If there has been no local recurrence or metastasis, rate on residual impairment of function.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5328', 'Muscle, neoplasm of, benign', 'MUSCLE INJURIES', 'Miscellaneous', '38 CFR 4.73', 'postoperative. Rate on impairment of function, i.e., limitation of motion, or scars, diagnostic code 7805, etc.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('5329', 'Sarcoma, soft tissue', 'MUSCLE INJURIES', 'Miscellaneous', '38 CFR 4.73', '(of muscle, fat, or fibrous connective tissue)—100. NOTE: A rating of 100 percent shall continue beyond the cessation of any surgery, radiation treatment, antineoplastic chemotherapy or other therapeutic procedures. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter. If there has been no local recurrence or metastasis, rate on residual impairment of function. (Authority: 38 U.S.C. 1155) [62 FR 30239, June 3, 1997] General considerations for evaluating visual impairment. (a) Visual impairment. The evaluation of visual impairment is based on impairment of visual acuity (excluding developmental errors of refraction), visual field, and muscle function. (b) Examination for visual impairment. The examination must be conducted by a licensed optometrist or by a licensed ophthalmologist. The examiner must identify the disease, injury, or other pathologic process responsible for any visual impairment found. Examina30 tions of visual fields or muscle func20 tion will be conducted only when there is a medical indication of disease or injury that may be associated with visual field defect or impaired muscle function. Unless medically contraindicated, the fundus must be examined with the claimant’s pupils dilated. (c) Service-connected visual impairment of only one eye. Subje', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6000', 'Choroidopathy, including uveitis, iritis, cyclitis, or choroiditis', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
