INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6008', 'Detachment of retina', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6009', 'Unhealed eye injury', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', 'Note: This code includes orbital trauma, as well as penetrating or non-penetrating eye injury', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6010', 'Tuberculosis of eye', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', 'Inactive: Evaluate under or of this part, whichever is appropriate.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6011', 'Retinal scars, atrophy, or irregularities', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', 'Alternatively, evaluate based on the General Rating Formula for Diseases of the Eye, if this would result in a higher evaluation', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6012', 'Angle-closure glaucoma', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6013', 'Open-angle glaucoma', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6014', 'Malignant neoplasms of the eye, orbit, and adnexa (excluding skin)', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', 'Note: Continue the 100 percent rating beyond the cessation of any surgical, X-ray, antineoplastic chemotherapy, or other therapeutic procedure. Six months after discontinuance of such treatment, the appropriate disability rating will be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination will be subject to the provisions of §3.105(e) of this chapter. If there has been no local recurrence or metastasis, evaluate based on residuals Malignant neoplasms of the eye, orbit, and adnexa (excluding skin) that do not require therapy comparable to that for systemic malignancies: Separately evaluate visual and nonvisual impairment, e.g., disfigurement (diagnostic code 7800), and combine the evaluations.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6015', 'Benign neoplasms of the eye, orbit, and adnexa (excluding skin)', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', 'Department of Veterans Affairs Rating Separately evaluate visual and nonvisual impairment, e.g., disfigurement (diagnostic code 7800), and combine the evaluations', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6016', 'Nystagmus, central', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6017', 'Conjunctivitis, trachomatous, chronic', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', 'Inactive: Evaluate based on residuals, such as visual impairment and disfigurement (diagnostic code 7800)', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6018', 'Conjunctivitis, other, chronic', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', 'Inactive: Evaluate based on residuals, such as visual impairment and disfigurement (diagnostic code 7800)', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6019', 'Ptosis unilateral or bilateral', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', 'Ptosis, unilateral or bilateral: Evaluate based on visual impairment or, in the absence of visual impairment, on disfigurement (diagnostic code 7800).', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6020', 'Ectropion', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6021', 'Entropion', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6022', 'Lagophthalmos', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
