INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6024', 'Eyelashes, loss', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6025', 'Disorders of the lacrimal apparatus (epiphora, dacrocystitis, etc.)', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6026', 'Optic neuropathy', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6027', 'Cataract', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', 'Preoperative: Evaluate under the General Rating Formula for Diseases of the Eye Postoperative: If a replacement lens is present (pseudophakia), evaluate under the General Rating Formula for Diseases of the Eye. If there is no replacement lens, evaluate based on aphakia (diagnostic code 6029)', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
