INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6034', 'Pterygium', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', 'Evaluate under the General Rating Formula for Diseases of the Eye, disfigurement (diagnostic code 7800), conjunctivitis (diagnostic code 6018), etc., depending on the particular findings, and combine in accordance with', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6035', 'Keratoconus', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6036', 'Status post corneal transplant', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', '6037 Pinguecula: Evaluate based on disfigurement (diagnostic code 7800).', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6040', 'Diabetic retinopathy', 'THE EYE', 'Diseases of the Eye', '38 CFR 4.79', NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
