INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6076', 'Other eye 20/100 (6/30)', 'THE EYE', 'Impairment of Central Visual Acuity', NULL, NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6077', 'Other eye 20/40 (6/12)', 'THE EYE', 'Impairment of Central Visual Acuity', NULL, NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6078', 'Other eye 20/100 (6/30)', 'THE EYE', 'Impairment of Central Visual Acuity', NULL, NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6079', 'Other eye 20/40 (6/12)', 'THE EYE', 'Impairment of Central Visual Acuity', NULL, NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6080', 'Field vision, impairment', 'THE EYE', 'Impairment of Central Visual Acuity', '38 CFR 4.79', 'Or evaluate each affected eye as 20/50 (6/15).', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6081', 'Scotoma', 'THE EYE', 'Impairment of Central Visual Acuity', '38 CFR 4.79', 'Alternatively, evaluate based on visual impairment due to scotoma, if that would result in a higher evaluation. 1Review for entitlement to special monthly compensation under 38 CFR 3.350. Degree of diplopia', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6090', 'Diplopia', 'THE EYE', 'Impairment of Central Visual Acuity', '38 CFR 4.79', '(double vision): (a) Central 20 degrees (b) 21 degrees to 30 degrees (1) Down (2) Lateral (3) Up (c) 31 degrees to 40 degrees (1) Down (2) Lateral (3) Up E q u i v a le n t v is u a l a c u it y 5/200 (1.5/60) 15/200 (4.5/60) 20/100 (6/30) 20/70 (6/21) 20/200 (6/60) 20/70 (6/21) 20/40 (6/12) Note: In accordance with 38 CFR 4.31, diplopia that is occasional or that is correctable with spectacles is evaluated at 0 percent.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6091', 'Symblepharon', 'THE EYE', 'Impairment of Central Visual Acuity', '38 CFR 4.79', 'decibels or more at 2000 Hertz, the rating specialist will determine the Roman numeral designation for hearing impairment from either Table VI or Table VIa, whichever results in the higher numeral. That numeral will then be elevated to the next higher Department of Veterans Affairs Roman numeral. Each ear will be evaluated separately. (Authority: 38 U.S.C. 1155) [64 FR 25209, May 11, 1999]', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6092', 'Diplopia, limited muscle function', 'THE EYE', 'Impairment of Central Visual Acuity', NULL, NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6100', 'Hearing impairment (hearing loss)', 'THE EAR', 'Impairment of Auditory Acuity', '38 CFR 4.85', 'Hearing loss is not rated on a symptom-based percentage list. Under §4.85, the evaluation (0% to 100%) is determined by an audiometric examination: puretone threshold averages and speech-discrimination (Maryland CNC) scores are converted to a Roman-numeral designation using Table VI (or Table VIa for exceptional patterns under §4.86), and the two ears are combined in Table VII to produce the assigned percentage.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6200', 'Chronic suppurative otitis media', 'THE EAR', NULL, '38 CFR 4.87', 'NOTE: Evaluate hearing impairment, and complications such as labyrinthitis, tinnitus, facial nerve paralysis, or bone loss of skull, separately.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6201', 'Chronic nonsuppurative otitis media', 'THE EAR', NULL, '38 CFR 4.87', 'with effusion (serous otitis media): Rate hearing impairment', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6202', 'Otosclerosis', 'THE EAR', NULL, '38 CFR 4.87', 'Rate hearing impairment', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6204', 'Peripheral vestibular disorders', 'THE EAR', NULL, '38 CFR 4.87', 'NOTE: Objective findings supporting the diagnosis of vestibular disequilibrium are required before a compensable evaluation can be assigned under this code. Hearing impairment or suppuration shall be separately rated and combined.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6205', 'Meniere’s syndrome', 'THE EAR', NULL, '38 CFR 4.87', 'NOTE: Evaluate Meniere’s syndrome either under these criteria or by separately evaluating vertigo (as a peripheral vestibular disorder), hearing impairment, and tinnitus, whichever method results in a higher overall evaluation. But do not combine an evaluation for hearing impairment, tinnitus, or vertigo with an evaluation under diagnostic code 6205.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6207', 'Loss of auricle', 'THE EAR', NULL, '38 CFR 4.87', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6208', 'Malignant neoplasm', 'THE EAR', NULL, '38 CFR 4.87', 'NOTE: A rating of 100 percent shall continue beyond the cessation of any surgical, radiation treatment, antineoplastic chemotherapy or other therapeutic procedure. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based on that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter. If there has been no local recurrence or metastasis, rate on residuals.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6209', 'Benign neoplasm', 'THE EAR', NULL, '38 CFR 4.87', 's of the ear (other than skin only): Rate on impairment of function.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6210', 'Chronic otitis externa', 'THE EAR', NULL, '38 CFR 4.87', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6211', 'Tympanic membrane', 'THE EAR', NULL, '38 CFR 4.87', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6260', 'Tinnitus, recurrent', 'THE EAR', NULL, '38 CFR 4.87', 'NOTE(1): A separate evaluation for tinnitus may be combined with an evaluation under diagnostic codes 6100, 6200, 6204, or other diagnostic code, except when tinnitus supports an evaluation under one of those diagnostic codes. NOTE(2): Assign only a single evaluation for recurrent tinnitus, whether the sound is perceived in one ear, both ears, or in the head. NOTE(3): Do not evaluate objective tinnitus (in which the sound is audible to other people and has a definable cause that may or may not be pathologic) under this diagnostic code, but evaluate it as part of any underlying condition causing it. (Authority: 38 U.S.C. 1155) [64 FR 25210, May 11, 1999, as amended at 68 FR 25823, May 14, 2003]', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6275', 'Smell, complete loss', 'OTHER SENSE ORGANS', NULL, '38 CFR 4.87a', 'NOTE: Evaluation will be assigned under diagnostic codes 6275 or 6276 only if there is an anatomical or pathological basis for the condition. (Authority: 38 U.S.C. 1155) [64 FR 25210, May 11, 1999] INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFI50 [Reserved] Chronic fatigue syndrome. (a) For VA purposes, the diagnosis of chronic fatigue syndrome requires: (1) new onset of debilitating fatigue severe enough to reduce daily activity to less than 50 percent of the usual level for at least six months; and (2) the exclusion, by history, physical examination, and laboratory tests, of all other clinical conditions that may produce similar symptoms; and (3) six or more of the following: (i) acute onset of the condition, (ii) low grade fever, (iii) nonexudative pharyngitis, (iv) palpable or tender cervical or axillary lymph nodes, (v) generalized muscle aches or weakness, (vi) fatigue lasting 24 hours or longer after exercise, (vii) headaches (of a type, severity, or pattern that is different from headaches in the pre-morbid state), (viii) migratory joint pains, (ix) neuropsychologic symptoms, (x) sleep disturbance. (b) [Reserved] [59 FR 60902, Nov. 29, 1994]', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6276', 'Taste, complete loss', 'OTHER SENSE ORGANS', NULL, NULL, NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6300', 'Vibriosis (Cholera, Non-cholera)', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate residuals of cholera and non-cholera vibrio infections, such as renal failure, skin, and musculoskeletal conditions, within the appropriate body system.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6301', 'Visceral Leishmaniasis', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Note 1: Continue a 100 percent evaluation beyond the cessation of treatment for active disease. Six months after discontinuance of such treatment, determine the appropriate disability rating by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter. Thereafter, rate under the appropriate body system any residual disability of infection, which includes, but is not limited to liver damage and bone marrow disease. Note 2: Confirm the recurrence of active infection by culture, histopathology, or other diagnostic laboratory testing.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6302', 'Leprosy (Hansen’s Disease)', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Note: Continue a 100 percent evaluation beyond the cessation of treatment for active disease. Six months after discontinuance of such treatment, determine the appropriate disability rating by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter. Thereafter, rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, skin lesions, peripheral neuropathy, or amputations.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6304', 'Malaria', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note 1: The diagnosis of malaria, both initially and during relapse, depends on the identification of the malarial parasites in blood smears or other specific diagnostic laboratory tests such as antigen detection, immunologic (immunochromatographic) tests, and molecular testing such as polymerase chain reaction tests. Note 2: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, liver or splenic damage, and central nervous system conditions.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6305', 'Lymphatic filariasis, to include elephantiasis', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, epididymitis, lymphangitis, lymphatic obstruction, or lymphedema affecting extremities, genitals, and/or breasts.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6306', 'Bartonellosis', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, endocarditis or skin lesions.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6307', 'Plague', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6308', 'Relapsing fever', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Department of Veterans Affairs Rating Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, liver or spleen damage, iritis, uveitis, or central nervous system involvement.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6309', 'Rheumatic fever', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, heart damage.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6310', 'Syphilis', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'and other treponema infections: Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, diseases of the nervous system, vascular system, eyes, or ears (see DC 7004, DC 8013, DC 8014, DC 8015, and DC 9301).', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6311', 'Tuberculosis, miliary', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Inactive disease: See § and 4.89. Note 1: Confirm the recurrence of active infection by culture, histopathology, or other diagnostic laboratory testing. Note 2: Rate under the appropriate body system any residual disability of infection which includes, but is not limited to, skin conditions and conditions of the respiratory, central nervous, musculoskeletal, ocular, gastrointestinal, and genitourinary systems and those residuals listed in .', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6312', 'Nontuberculosis mycobacterium infection', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Note 1: Continue the rating of 100 percent for the duration of treatment for active disease followed by a mandatory VA exam. If there is no relapse, rate on residuals. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter. Note 2: Confirm the recurrence of active infection by culture, histopathology, or other diagnostic laboratory testing. Note 3: Rate under the appropriate body system any residual disability of infection which includes, but is not limited to, skin conditions and conditions of the respiratory, central nervous, musculoskeletal, ocular, gastrointestinal, and genitourinary systems and those residuals listed in .', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6313', 'Avitaminosis', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6314', 'Beriberi', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Thereafter rate residuals under the appropriate body system.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6315', 'Pellagra', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6316', 'Brucellosis', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note 1: Culture, serologic testing, or both must confirm the initial diagnosis and recurrence of active infection. Note 2: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, meningitis, liver, spleen and musculoskeletal conditions.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6317', 'Rickettsial, ehrlichia, and anaplasma infections', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note 1: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, bone marrow, spleen, central nervous system, and skin conditions. Note 2: This diagnostic code includes, but is not limited to, scrub typhus, Rickettsial pox, African tick-borne fever, Rocky Mountain spotted fever, ehrlichiosis, or anaplasmosis.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6318', 'Melioidosis', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note 1: Confirm by culture or other specific diagnostic laboratory tests the initial diagnosis and any relapse or chronic activity of infection. Note 2: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, arthritis, lung lesions, or meningitis.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6319', 'Lyme disease', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, arthritis, Bell’s palsy, radiculopathy, ocular, or cognitive dysfunction.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6320', 'Parasitic diseases', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'otherwise not specified: Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6325', 'Hyperinfection syndrome or disseminated strongyloidiasis', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Note: Continue the rating of 100 percent through active disease followed by a mandatory VA exam. If there is no relapse, rate on residual disability. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6326', 'Schistosomiasis', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, conditions of the liver, intestinal system, female genital tract, genitourinary tract, or central nervous system.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6329', 'Hemorrhagic fevers, including dengue, yellow fever, and others', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, conditions of the central nervous system, liver, or kidney.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6330', 'Campylobacter jejuni infection', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, Guillain-Barre syndrome, reactive arthritis, or uveitis.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6331', 'Coxiella burnetii infection (Q Fever)', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, chronic hepatitis, endocarditis, osteomyelitis, post Q-fever chronic fatigue syndrome, or vascular infections.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6333', 'Nontyphoid salmonella infections', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, reactive arthritis.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6334', 'Shigella infections', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, hemolytic-uremic syndrome or reactive arthritis.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6335', 'West Nile virus infection', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Evaluate under the General Rating Formula. Note: Rate under the appropriate body system any residual disability of infection, which includes, but is not limited to, variable physical, functional, or cognitive disabilities.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6350', 'Lupus erythematosus', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'NOTE: Evaluate this condition either by combining the evaluations for residuals under the appropriate system, or by evaluating DC 6350, whichever method results in a higher evaluation.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6351', 'HIV-Related Illness', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Note 1: In addition to standard therapies and regimens, the term ‘‘approved medication(s)’’ includes treatment regimens and medications prescribed as part of a research protocol at an accredited medical institution. Note 2: Diagnosed psychiatric illness, central nervous system manifestations, opportunistic infections, and neoplasms may be rated separately under the appropriate diagnostic codes if a higher overall evaluation results, provided the disability symptoms do not overlap with evaluations otherwise assignable above. Note 3: The following list of opportunistic infections are considered AIDS-defining conditions, that is, a diagnosis of AIDS follows if a person has HIV and one more of these infections, regardless of the CD4 count— candidiasis of the bronchi, trachea, esophagus, or lungs; invasive cervical cancer; coccidioidomycosis; cryptococcosis; cryptosporidiosis; cytomegalovirus (particularly CMV retinitis); HIV-related encephalopathy; herpes simplex-chronic ulcers for greater than one month, or bronchitis, pneumonia, or esophagitis; histoplasmosis; isosporiasis (chronic intestinal); Kaposi’s sarcoma; lymphoma; mycobacterium avium complex; tuberculosis; pneumocystis jirovecii (carinii) pneumonia; pneumonia, recurrent; progressive multifocal leukoencephalopathy; salmonella septicemia, recurrent; toxoplasmosis of the brain; and wasting syndrome due to HIV.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6354', 'Chronic Fatigue Syndrome (CFS)', 'INFECTIOUS DISEASES, IMMUNE DISORDERS AND NUTRITIONAL DEFICIENCIES', NULL, '38 CFR 4.88b', 'Note: For the purpose of evaluating this disability, incapacitation exists only when a licensed physician prescribes bed rest and treatment. [61 FR 39875, July 31, 1996, as amended at 84 FR 28230, June 18, 2019] Ratings for inactive nonpulrating cases in which the protective monary tuberculosis initially entiprovisions of Pub. L. 90–493 apply, the tled after August 19, 1968. former evaluations are retained in this Rating For 1 year after date of inactivity, following active tuberculosis 100 Thereafter: Rate residuals under the specific body system or systems affected. Following the total rating for the 1 year period after date of inactivity, the schedular evaluation for residuals of nonpulmonary tuberculosis, i.e., ankylosis, surgical removal of a part, etc., will be assigned under the appropriate diagnostic code for the residual preceded by the diagnostic code for tuberculosis of the body part affected. For example, tuberculosis of the hip joint with residual ankylosis would be coded 5001–5250. Where there are existing residuals of pulmonary and nonpulmonary conditions, the evaluations for residual separate functional impairment may be combined. Where there are existing pulmonary and nonpulmonary conditions, the total rating for the 1 year, after attainment of inactivity, may not be applied to both conditions during the same period. However, the total rating during the 1-year period for the pulmonary or for the nonpulmonary condition will be utilized, combined with evaluatio', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6502', 'Septum, nasal, deviation', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6504', 'Nose, loss of part of, or scars', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', 'Note: Or evaluate as DC 7800, scars, disfiguring, head, face, or neck.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6510', 'Sinusitis, pansinusitis, chronic', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
