INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6513', 'Sinusitis, maxillary, chronic', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6514', 'Sinusitis, sphenoid, chronic', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', 'Note: An incapacitating episode of sinusitis means one that requires bed rest and treatment by a physician.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6515', 'Laryngitis, tuberculous', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', 'active or inactive. Rate under § or 4.89, whichever is appropriate.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6516', 'Laryngitis, chronic', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6518', 'Laryngectomy, total', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', '1100 Rate the residuals of partial laryngectomy as laryngitis (DC 6516), aphonia (DC 6519), or stenosis of larynx (DC 6520).', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6519', 'Aphonia, complete organic', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', 'Note: Evaluate incomplete aphonia as laryngitis, chronic (DC 6516).', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6520', 'Larynx, stenosis of', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', 'Note: Or evaluate as aphonia (DC 6519).', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6521', 'Pharynx, injuries to', 'THE RESPIRATORY SYSTEM', 'Nose and Throat', '38 CFR 4.97', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
