INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6722', 'Inactive, moderately advanced', 'THE RESPIRATORY SYSTEM', 'Lungs and Pleura Tuberculosis', '38 CFR 4.97', 'Tuberculosis, pulmonary, chronic, moderately advanced, inactive.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6723', 'Inactive, minimal', 'THE RESPIRATORY SYSTEM', 'Lungs and Pleura Tuberculosis', '38 CFR 4.97', 'Tuberculosis, pulmonary, chronic, minimal, inactive.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6724', 'Inactive, advancement unspecified', 'THE RESPIRATORY SYSTEM', 'Lungs and Pleura Tuberculosis', '38 CFR 4.97', 'Note (1): The 100-percent rating under codes 6701 through 6724 is not subject to a requirement of precedent hospital treatment. It will be reduced to 50 percent for failure to submit to examination or to follow prescribed treatment upon report to that effect from the medical authorities. When a veteran is placed on the 100-percent rating for inactive tuberculosis, the medical authorities will be appropriately notified of the fact, and of the necessity, as given in footnote 1 to 38 U.S.C. 1156 (and formerly in 38 U.S.C. 356, which has been repealed by Public Law 90–493), to notify the Veterans Service Center in the event of failure to submit to examination or to follow treatment. Note (2): The graduated 50-percent and 30-percent ratings and the permanent 30 percent and 20 percent ratings for inactive pulmonary tuberculosis are not to be combined with ratings for other respiratory disabilities. Following thoracoplasty the rating will be for removal of ribs combined with the rating for collapsed lung. Resection of the ribs incident to thoracoplasty will be rated as removal. Ratings for Pulmonary Tuberculosis Initially Evaluated After August 19, 1968', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6730', 'Chronic, active', 'THE RESPIRATORY SYSTEM', 'Lungs and Pleura Tuberculosis', '38 CFR 4.97', 'Note: Active pulmonary tuberculosis will be considered permanently and totally disabling for non-service-connected pension purposes in the following circumstances: (a) Associated with active tuberculosis involving other than the respiratory system. (b) With severe associated symptoms or with extensive cavity formation. (c) Reactivated cases, generally. (d) With advancement of lesions on successive examinations or while under treatment. (e) Without retrogression of lesions or other evidence of material improvement at the end of six months hospitalization or without change of diagnosis from ‘‘active’’ at the end of 12 months hospitalization. Material improvement means lessening or absence of clinical symptoms, and X-ray findings of a stationary or retrogressive lesion.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6731', 'Chronic, inactive', 'THE RESPIRATORY SYSTEM', 'Lungs and Pleura Tuberculosis', '38 CFR 4.97', 'Tuberculosis, pulmonary, chronic, inactive: Depending on the specific findings, rate residuals as interstitial lung disease, restrictive lung disease, or, when obstructive lung disease is the major residual, as chronic bronchitis (DC 6600). Rate thoracoplasty as removal of ribs under DC 5297. Note: A mandatory examination will be requested immediately following notification that active tuberculosis evaluated under DC 6730 has become inactive. Any change in evaluation will be carried out under the provisions of §3.105(e).', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6732', 'Pleurisy, active or inactive', 'THE RESPIRATORY SYSTEM', 'Lungs and Pleura Tuberculosis', '38 CFR 4.97', 'Pleurisy, tuberculous, active or inactive: Rate under § or 4.89, whichever is appropriate. NONTUBERCULOUS DISEASES', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6817', 'Pulmonary Vascular Disease', 'THE RESPIRATORY SYSTEM', 'Nontuberculous Diseases', '38 CFR 4.97', 'Note: Evaluate other residuals following pulmonary embolism under the most appropriate diagnostic code, such as chronic bronchitis (DC 6600) or chronic pleural effusion or fibrosis (DC 6844), but do not combine that evaluation with any of the above evaluations.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6819', 'Neoplasms, malignant', 'THE RESPIRATORY SYSTEM', 'Nontuberculous Diseases', '38 CFR 4.97', 'Note: A rating of 100 percent shall continue beyond the cessation of any surgical, X-ray, antineoplastic chemotherapy or other therapeutic procedure. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter. If there has been no local recurrence or metastasis, rate on residuals.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6820', 'Neoplasms, benign', 'THE RESPIRATORY SYSTEM', 'Nontuberculous Diseases', '38 CFR 4.97', 'any specified part of respiratory system. Evaluate using an appropriate respiratory analogy. Rating Bacterial Infections of the Lung', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6822', 'Actinomycosis', 'THE RESPIRATORY SYSTEM', 'Bacterial Infections of the Lung', '38 CFR 4.97', NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6823', 'Nocardiosis', 'THE RESPIRATORY SYSTEM', 'Bacterial Infections of the Lung', '38 CFR 4.97', NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6824', 'Chronic lung abscess', 'THE RESPIRATORY SYSTEM', 'Bacterial Infections of the Lung', '38 CFR 4.97', 'Depending on the specific findings, rate residuals as interstitial lung disease, restrictive lung disease, or, when obstructive lung disease is the major residual, as chronic bronchitis (DC 6600). Interstitial Lung Disease', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6825', 'Fibrosis of lung, diffuse interstitial', 'THE RESPIRATORY SYSTEM', 'Interstitial Lung Disease', '38 CFR 4.97', 'Diffuse interstitial fibrosis (interstitial pneumonitis, fibrosing alveolitis).', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6826', 'Desquamative interstitial pneumonitis', 'THE RESPIRATORY SYSTEM', 'Interstitial Lung Disease', '38 CFR 4.97', NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6827', 'Pulmonary alveolar proteinosis', 'THE RESPIRATORY SYSTEM', 'Interstitial Lung Disease', '38 CFR 4.97', NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6828', 'Eosinophilic granuloma', 'THE RESPIRATORY SYSTEM', 'Interstitial Lung Disease', '38 CFR 4.97', 'of lung.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6829', 'Drug-induced, pneumonitis & fibrosis', 'THE RESPIRATORY SYSTEM', 'Interstitial Lung Disease', '38 CFR 4.97', 'Drug-induced pulmonary pneumonitis and fibrosis.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6830', 'Radiation-induced, pneumonitis & fibrosis', 'THE RESPIRATORY SYSTEM', 'Interstitial Lung Disease', '38 CFR 4.97', 'Radiation-induced pulmonary pneumonitis and fibrosis.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6831', 'Hypersensitivity pneumonitis', 'THE RESPIRATORY SYSTEM', 'Interstitial Lung Disease', '38 CFR 4.97', '(extrinsic allergic alveolitis).', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6832', 'Pneumoconiosis', 'THE RESPIRATORY SYSTEM', 'Interstitial Lung Disease', '38 CFR 4.97', '(silicosis, anthracosis, etc.).', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6833', 'Asbestosis', 'THE RESPIRATORY SYSTEM', 'Interstitial Lung Disease', '38 CFR 4.97', 'Mycotic Lung Disease', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6834', 'Histoplasmosis', 'THE RESPIRATORY SYSTEM', 'Mycotic Lung Disease', '38 CFR 4.97', 'Histoplasmosis of lung.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6835', 'Coccidioidomycosis', 'THE RESPIRATORY SYSTEM', 'Mycotic Lung Disease', '38 CFR 4.97', NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6836', 'Blastomycosis', 'THE RESPIRATORY SYSTEM', 'Mycotic Lung Disease', '38 CFR 4.97', NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6837', 'Cryptococcosis', 'THE RESPIRATORY SYSTEM', 'Mycotic Lung Disease', '38 CFR 4.97', NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6838', 'Aspergillosis', 'THE RESPIRATORY SYSTEM', 'Mycotic Lung Disease', '38 CFR 4.97', NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6839', 'Mucormycosis', 'THE RESPIRATORY SYSTEM', 'Mycotic Lung Disease', '38 CFR 4.97', 'Note: Coccidioidomycosis has an incubation period up to 21 days, and the disseminated phase is ordinarily manifest within six months of the primary phase. However, there are instances of dissemination delayed up to many years after the initial infection which may have been unrecognized. Accordingly, when service connection is under consideration in the absence of record or other evidence of the disease in service, service in southwestern United States where the disease is endemic and absence of prolonged residence in this locality before or after service will be the deciding factor. Restrictive Lung Disease', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6840', 'Diaphragm paralysis or paresis', 'THE RESPIRATORY SYSTEM', 'Restrictive Lung Disease', '38 CFR 4.97', NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6841', 'Spinal cord injury with respiratory insufficiency', 'THE RESPIRATORY SYSTEM', 'Restrictive Lung Disease', '38 CFR 4.97', NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6842', 'Kyphoscoliosis, pectus excavatum/carinatum', 'THE RESPIRATORY SYSTEM', 'Restrictive Lung Disease', '38 CFR 4.97', 'Kyphoscoliosis, pectus excavatum, pectus carinatum.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6843', 'Traumatic chest wall defect', 'THE RESPIRATORY SYSTEM', 'Restrictive Lung Disease', '38 CFR 4.97', 'pneumothorax, hernia, etc.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6844', 'Post-surgical residual', 'THE RESPIRATORY SYSTEM', 'Restrictive Lung Disease', '38 CFR 4.97', '(lobectomy, pneumonectomy, etc.).', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6845', 'Pleural effusion or fibrosis', 'THE RESPIRATORY SYSTEM', 'Restrictive Lung Disease', '38 CFR 4.97', 'Or rate primary disorder. Note (1): A 100-percent rating shall be assigned for pleurisy with empyema, with or without pleurocutaneous fistula, until resolved. Note (2): Following episodes of total spontaneous pneumothorax, a rating of 100 percent shall be assigned as of the date of hospital admission and shall continue for three months from the first day of the month after hospital discharge. Note (3): Gunshot wounds of the pleural cavity with bullet or missile retained in lung, pain or discomfort on exertion, or with scattered rales or some limitation of excursion of diaphragm or of lower chest expansion shall be rated at least 20-percent disabling. Disabling injuries of shoulder girdle muscles (Groups I to IV) shall be separately rated and combined with ratings for respiratory involvement. Involvement of Muscle Group XXI (DC 5321), however, will not be separately rated.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6846', 'Sarcoidosis', 'THE RESPIRATORY SYSTEM', 'Restrictive Lung Disease', '38 CFR 4.97', 'Or rate active disease or residuals as chronic bronchitis (DC 6600) and extra-pulmonary involvement under specific body system involved.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('6847', 'Sleep Apnea Syndromes', 'THE RESPIRATORY SYSTEM', 'Restrictive Lung Disease', '38 CFR 4.97', '1Review for entitlement to special monthly compensation under §3.350 of this chapter. [61 FR 46728, Sept. 5, 1996, as amended at 71 FR 28586, May 17, 2006] THECARDIOVASCULARSYSTEM evaluate based on the alternative cri- Application of the evaluation criteria for diagnostic codes 7000– 7007, 7011, and 7015–7020. (a) Whether or not cardiac hypertrophy or dilatation (documented by electrocardiogram, echocardiogram, or X-ray) is present and whether or not there is a need for continuous medication must be ascertained in all cases. (b) Even if the requirement for a 10% (based on the need for continuous medication) or 30% (based on the presence of cardiac hypertrophy or dilatation) evaluation is met, METs testing is required in all cases except: (1) When there is a medical contraindication. (2) When the left ventricular ejection fraction has been measured and is 50% or less. (3) When chronic congestive heart failure is present or there has been more than one episode of congestive heart failure within the past year. (4) When a 100% evaluation can be assigned on another basis. (c) If left ventricular ejection fraction (LVEF) testing is not of record, teria unless the examiner states that the LVEF test is needed in a particular case because the available medical information does not sufficiently reflect the severity of the veteran’s cardiovascular disability. [71 FR 52460, Sept. 6, 2006] § –4.103 [Reserved]', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7000', 'Valvular heart disease', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7001', 'Endocarditis', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7002', 'Pericarditis', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7003', 'Pericardial adhesions', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7004', 'Syphilitic heart disease', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Department of Veterans Affairs Rating NOTE: Evaluate syphilitic aortic aneurysms under DC 7110 (aortic aneurysm).', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7005', 'Arteriosclerotic heart disease', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'NOTE: If nonservice-connected arteriosclerotic heart disease is superimposed on service-connected valvular or other non-arteriosclerotic heart disease, request a medical opinion as to which condition is causing the current signs and symptoms.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7006', 'Myocardial infarction', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7007', 'Hypertensive heart disease', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7008', 'Hyperthyroid heart disease', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Rate under the appropriate cardiovascular diagnostic code, depending on particular findings.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7010', 'Supraventricular arrhythmias', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7011', 'Ventricular arrhythmias', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Rating NOTE: A rating of 100 percent shall be assigned from the date of hospital admission for initial evaluation and medical therapy for a sustained ventricular arrhythmia or for ventricular aneurysmectomy. Six months following discharge, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7015', 'Atrioventricular block', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Workload of greater than 7 METs but not greater than 10 METs results in dyspnea, fatigue, angina, dizziness, or syncope, or; continuous medication or a pacemaker required NOTE: Unusual cases of arrhythmia such as atrioventricular block associated with a supraventricular arrhythmia or pathological bradycardia should be submitted to the Director, Compensation Service. Simple delayed P-R conduction time, in the absence of other evidence of cardiac disease, is not a disability.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7016', 'Heart valve replacement', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Rating NOTE: A rating of 100 percent shall be assigned as of the date of hospital admission for valve replacement. Six months following discharge, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7017', 'Coronary bypass surgery', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'NOTE: Evaluate implantable Cardioverter-Defibrillators (AICD’s) under DC 7011. 100 7019 Cardiac transplantation: For an indefinite period from date of hospital admission for cardiac transplantation 100 Thereafter: Chronic congestive heart failure, or; workload of 3 METs or less results in dyspnea, fatigue, angina, dizziness, or syncope, or; left ventricular dysfunction with an ejection fraction of less than 30 percent 100 More than one episode of acute congestive heart failure in the past year, or; workload of greater than 3 METs but not greater than 5 METs results in dyspnea, fatigue, angina, dizziness, or syncope, or; left ventricular dysfunction with an ejection fraction of 30 to 50 percent 60 Minimum 30 NOTE: A rating of 100 percent shall be assigned as of the date of hospital admission for cardiac transplantation. One year following discharge, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter. Department of Veterans Affairs Rating', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7018', 'Implantable cardiac pacemakers', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', NULL, NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7019', 'Cardiac transplantation', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', NULL, NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7020', 'Cardiomyopathy', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Heart', '38 CFR 4.104', 'Diseases of the Arteries and Veins', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7101', 'Hypertensive vascular disease', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'NOTE (1): Hypertension or isolated systolic hypertension must be confirmed by readings taken two or more times on at least three different days. For purposes of this section, the term hypertension means that the diastolic blood pressure is predominantly 90mm. or greater, and isolated systolic hypertension means that the systolic blood pressure is predominantly 160mm. or greater with a diastolic blood pressure of less than 90mm. NOTE(2): Evaluate hypertension due to aortic insufficiency or hyperthyroidism, which is usually the isolated systolic type, as part of the condition causing it rather than by a separate evaluation. NOTE(3): Evaluate hypertension separately from hypertensive heart disease and other types of heart disease.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7110', 'Aortic aneurysm', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'Rating Evaluate residuals of surgical correction according to organ systems affected. NOTE: A rating of 100 percent shall be assigned as of the date of admission for surgical correction. Six months following discharge, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7111', 'Aneurysm, large artery', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'NOTE(1): The ankle/brachial index is the ratio of the systolic blood pressure at the ankle (determined by Doppler study) divided by the simultaneous brachial artery systolic blood pressure. The normal index is 1.0 or greater. NOTE(2): These evaluations are for involvement of a single extremity. If more than one extremity is affected, evaluate each extremity separately and combine (under ), using the bilateral factor, if applicable. NOTE(3): A rating of 100 percent shall be assigned as of the date of hospital admission for surgical correction. Six months following discharge, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7112', 'Aneurysm, small artery', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'NOTE: If symptomatic, evaluate according to body system affected. Following surgery, evaluate residuals under the body system affected.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7113', 'Arteriovenous fistula, traumatic', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7114', 'Arteriosclerosis obliterans', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'NOTE(1): The ankle/brachial index is the ratio of the systolic blood pressure at the ankle (determined by Doppler study) divided by the simultaneous brachial artery systolic blood pressure. The normal index is 1.0 or greater. NOTE(2): Evaluate residuals of aortic and large arterial bypass surgery or arterial graft as arteriosclerosis obliterans. NOTE(3): These evaluations are for involvement of a single extremity. If more than one extremity is affected, evaluate each extremity separately and combine (under ), using the bilateral factor ( ), if applicable.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7115', 'Thrombo-angiitis obliterans (Buerger’s Disease)', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'NOTE(1): The ankle/brachial index is the ratio of the systolic blood pressure at the ankle (determined by Doppler study) divided by the simultaneous brachial artery systolic blood pressure. The normal index is 1.0 or greater. NOTE(2): These evaluations are for involvement of a single extremity. If more than one extremity is affected, evaluate each extremity separately and combine (under ), using the bilateral factor ( ), if applicable.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7117', 'Raynaud’s syndrome', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'Rating NOTE: For purposes of this section, characteristic attacks consist of sequential color changes of the digits of one or more extremities lasting minutes to hours, sometimes with pain and paresthesias, and precipitated by exposure to cold or by emotional upsets. These evaluations are for the disease as a whole, regardless of the number of extremities involved or whether the nose and ears are involved. 40 7118 Angioneurotic edema: Attacks without laryngeal involvement lasting one to seven days or longer and occurring more than eight times a year, or; attacks with laryngeal involvement of any duration occurring more than twice a year 40 Attacks without laryngeal involvement lasting one to seven days and occurring five to eight times a year, or; attacks with laryngeal involvement of any duration occurring once or twice a year 20 Attacks without laryngeal involvement lasting one to seven days and occurring two to four times a year 10', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7118', 'Angioneurotic edema', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', NULL, NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7119', 'Erythromelalgia', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'NOTE: For purposes of this section, a characteristic attack of erythromelalgia consists of burning pain in the hands, feet, or both, usually bilateral and symmetrical, with increased skin temperature and redness, occurring at warm ambient temperatures. These evaluations are for the disease as a whole, regardless of the number of extremities involved.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7120', 'Varicose veins', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'NOTE: These evaluations are for involvement of a single extremity. If more than one extremity is involved, evaluate each extremity separately and combine (under ), using the bilateral factor ( ), if applicable. Department of Veterans Affairs Rating', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7121', 'Post-phlebitic syndrome', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'NOTE: These evaluations are for involvement of a single extremity. If more than one extremity is involved, evaluate each extremity separately and combine (under ), using the bilateral factor ( ), if applicable.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7122', 'Cold injury residuals', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'With the following in affected parts: Arthralgia or other pain, numbness, or cold sensitivity plus two or more of the following: tissue loss, nail abnormalities, color changes, locally impaired sensation, hyperhidrosis, X-ray abnormalities (osteoporosis, subarticular punched out lesions, or osteoarthritis) Arthralgia or other pain, numbness, or cold sensitivity plus tissue loss, nail abnormalities, color changes, locally impaired sensation, hyperhidrosis, or X-ray abnormalities (osteoporosis, subarticular punched out lesions, or osteoarthritis) Arthralgia or other pain, numbness, or cold sensitivity NOTE(1): Separately evaluate amputations of fingers or toes, and complications such as squamous cell carcinoma at the site of a cold injury scar or peripheral neuropathy, under other diagnostic codes. Separately evaluate other disabilities that have been diagnosed as the residual effects of cold injury, such as Raynaud’s phenomenon, muscle atrophy, etc., unless they are used to support an evaluation under diagnostic code 7122. NOTE (2): Evaluate each affected part (e.g., hand, foot, ear, nose) separately and combine the ratings in accordance with § and 4.26.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7123', 'Soft tissue sarcoma', 'THE CARDIOVASCULAR SYSTEM', 'Diseases of the Arteries and Veins', '38 CFR 4.104', 'Rating NOTE: A rating of 100 percent shall continue beyond the cessation of any surgical, X-ray, antineoplastic chemotherapy or other therapeutic procedure. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter. If there has been no local recurrence or metastasis, rate on residuals. 40 (Authority: 38 U.S.C. 1155) [62 FR 65219, Dec. 11, 1997, as amended at 63 FR 37779, July 14, 1998; 71 FR 52460, Sept. 6, 20 2006; 79 FR 2100, Jan. 13, 2014; 82 FR 50804, Nov. 2, 2017] Ulcers. Experience has shown that the term ‘‘peptic ulcer’’ is not sufficiently specific for rating purposes. Manifest differences in ulcers of the stomach or duodenum in comparison with those at an anastomotic stoma are sufficiently recognized as to warrant two separate graduated descriptions. In evaluating the ulcer, care should be taken that the findings adequately identify the particular location. Postgastrectomy syndromes. There are various postgastrectomy 30 symptoms which may occur following anastomotic operations of the stomach. When present, those occurring during or immediately after eating and known as the ‘‘dumping syndrome’’ are characterized by gastrointestinal com20 plaints and generalized symptoms simulating hypoglycemia; those occurring 10 from 1 to 3 hours after eating usually present ', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7200', 'Mouth, injuries', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'of. Rate as for disfigurement and impairment of function of mastication.', false, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7201', 'Lips, injuries', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'of. Rate as for disfigurement of face.', false, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7202', 'Tongue, loss', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7203', 'Esophagus, stricture', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7204', 'Esophagus, spasm', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'of (cardiospasm). If not amenable to dilation, rate as for the degree of obstruction (stricture).', false, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7205', 'Esophagus, diverticulum', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'of, acquired. Rate as for obstruction (stricture).', false, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7301', 'Peritoneum, adhesions', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'NOTE: Ratings for adhesions will be considered when there is history of operative or other traumatic or infectious (intraabdominal) process, and at least two of the following: disturbance of motility, actual partial obstruction, reflex disturbances, presence of pain.', true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7304', 'Ulcer, gastric', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, false, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7305', 'Ulcer, duodenal', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7306', 'Ulcer, marginal', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7307', 'Gastritis, hypertrophic', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Gastritis, atrophic. A complication of a number of diseases, including pernicious anemia. Rate the underlying condition.', true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7308', 'Postgastrectomy syndromes', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7309', 'Stomach, stenosis', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'of. Rate as for gastric ulcer.', false, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7310', 'Stomach, injury of, residuals', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate as peritoneal adhesions.', false, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7311', 'Liver, injury of, residuals', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Residuals of injury of the liver: Depending on the specific residuals, separately evaluate as adhesions of peritoneum (diagnostic code 7301), cirrhosis of liver (diagnostic code 7312), and chronic liver disease without cirrhosis (diagnostic code 7345).', false, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7312', 'Liver, cirrhosis', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'NOTE: For evaluation under diagnostic code 7312, documentation of cirrhosis (by biopsy or imaging) and abnormal liver function tests must be present.', true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7314', 'Cholecystitis, chronic', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7315', 'Cholelithiasis, chronic', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate as for chronic cholecystitis.', false, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7316', 'Cholangitis, chronic', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate as for chronic cholecystitis.', false, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7317', 'Gall bladder, injury', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'of. Rate as for peritoneal adhesions.', false, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7318', 'Gall bladder, removal', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Spleen, disease or injury of. See Hemic and Lymphatic Systems.', true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7319', 'Colon, irritable syndrome', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Mild; disturbances of bowel function with occasional episodes of abdominal distress', true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7321', 'Amebiasis', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'NOTE: Amebiasis with or without liver abscess is parallel in symptomatology with ulcerative colitis and should be rated on the scale provided for the latter. Similarly, lung abscess due to amebiasis will be rated under the respiratory system schedule, diagnostic code 6809.', true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7322', 'Dysentery, bacillary', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate as for ulcerative colitis..', false, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7323', 'Colitis, ulcerative', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7324', 'Distomiasis, intestinal or hepatic', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7325', 'Enteritis, chronic', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate as for irritable colon syndrome. 100 7326 Enterocolitis, chronic. Rate as for irritable colon syndrome.', false, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7326', 'Enterocolitis, chronic', 'THE DIGESTIVE SYSTEM', NULL, NULL, NULL, false, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7327', 'Diverticulitis', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate as for irritable colon syndrome, peritoneal adhesions, or colitis, ulcerative, depending upon the predominant disability picture.', false, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7328', 'Intestine, small, resection', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'NOTE: Where residual adhesions constitute the predominant disability, rate under diagnostic code 7301.', true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7329', 'Intestine, large, resection', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'NOTE: Where residual adhesions constitute the predominant disability, rate under diagnostic code 7301.', true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7330', 'Intestine, fistula', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Inactive: See § and 4.89.', true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
