INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7334', 'Rectum, prolapse', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7335', 'Ano, fistula in', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate as for impairment of sphincter control.', false, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7336', 'Hemorrhoids', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7337', 'Pruritus ani', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate for the underlying condition.', false, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7338', 'Hernia, inguinal', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'NOTE: Add 10 percent for bilateral involvement, provided the second hernia is compensable. This means that the more severely disabling hernia is to be evaluated, and 10 percent, only, added for the second hernia, if the latter is of compensable degree.', true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7339', 'Hernia, ventral, postoperative', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7340', 'Hernia, femoral', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Rate as for inguinal hernia.', false, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7342', 'Visceroptosis', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7343', 'Neoplasms, malignant', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'NOTE: A rating of 100 percent shall continue beyond the cessation of any surgical, X-ray, antineoplastic chemotherapy or other therapeutic procedure. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter. If there has been no local recurrence or metastasis, rate on residuals.', true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7344', 'Neoplasms, benign', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'Benign neoplasms, exclusive of skin growths: Evaluate under an appropriate diagnostic code, depending on the predominant disability or the specific residuals after treatment.', false, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7345', 'Liver disease, chronic, without cirrhosis', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'NOTE (1): Evaluate sequelae, such as cirrhosis or malignancy of the liver, under an appropriate diagnostic code, but do not use the same signs and symptoms as the basis for evaluation under DC 7354 and under a diagnostic code for sequelae. (See .). NOTE(2): For purposes of evaluating conditions under diagnostic code 7345, ‘‘incapacitating episode’’ means a period of acute signs and symptoms severe enough to require bed rest and treatment by a physician. NOTE (3): Hepatitis B infection must be confirmed by serologic testing in order to evaluate it under diagnostic code 7345.', true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7346', 'Hernia, hiatal', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', NULL, true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7347', 'Pancreatitis', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'NOTE 1: Abdominal pain in this condition must be confirmed as resulting from pancreatitis by appropriate laboratory and clinical studies. NOTE 2: Following total or partial pancreatectomy, rate under above, symptoms, minimum rating 30 percent.', true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7348', 'Vagotomy', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'NOTE: Rate recurrent ulcer following complete vagotomy under diagnostic code 7305, minimum rating 20 percent; and rate dumping syndrome under diagnostic code 7308.', true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7351', 'Liver transplant', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'NOTE: A rating of 100 percent shall be assigned as of the date of hospital admission for transplant surgery and shall continue. One year following discharge, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter.', true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7354', 'Hepatitis C', 'THE DIGESTIVE SYSTEM', NULL, '38 CFR 4.114', 'NOTE (1): Evaluate sequelae, such as cirrhosis or malignancy of the liver, under an appropriate diagnostic code, but do not use the same signs and symptoms as the basis for evaluation under DC 7354 and under a diagnostic code for sequelae. (See .). NOTE(2): For purposes of evaluating conditions under diagnostic code 7354, ‘‘incapacitating episode’’ means a period of acute signs and symptoms severe enough to require bed rest and treatment by a physician. (Authority: 38 U.S.C. 1155) [29 FR 6718, May 22, 1964, as amended at 34 FR 5063, Mar. 11, 1969; 40 FR 42540, Sept. 15, 1975; 41 FR 11301, Mar. 18, 1976; 66 FR 29488, May 31, 2001] Nephritis. Albuminuria alone is not nephritis, nor will the presence of transient albumin and casts following acute febrile illness be taken as nephritis. The glomerular type of nephritis is usually preceded by or associated with severe infectious disease; the onset is sudden, and the course marked by red blood cells, salt retention, and edema; it may clear up entirely or progress to a chronic condition. The nephrosclerotic type, originating in hypertension or arteriosclerosis, develops slowly, with minimum laboratory findings, and is associated with natural progress. Separate ratings are not to be assigned for disability from disease of the heart and any form of nephritis, on account of the close interrelationships of cardiovascular disabilities. If, however, absence of a kidney is the sole renal disability, even if removal was required because of n', true, 'SUPERSEDED', '38 CFR 4.110-4.114 were revised effective 2024-05-19; this is the 2020 text.', ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7500', 'Kidney, removal', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Or rate as renal dysfunction if there is nephritis, infection, or pathology of the other.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7501', 'Kidney, abscess', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'of: Rate as urinary tract infection Department of Veterans Affairs Rating', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7502', 'Nephritis, chronic', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as renal dysfunction.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7504', 'Pyelonephritis, chronic', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as renal dysfunction or urinary tract infection, whichever is predominant.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7505', 'Kidney, tuberculosis', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'of: Rate in accordance with § or 4.89, whichever is appropriate.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7507', 'Nephrosclerosis, arteriolar', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate according to predominant symptoms as renal dysfunction, hypertension or heart disease. If rated under the cardiovascular schedule, however, the percentage rating which would otherwise be assigned will be elevated to the next higher evaluation.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7508', 'Nephrolithiasis', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7509', 'Hydronephrosis', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7510', 'Ureterolithiasis', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7511', 'Ureter, stricture', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7512', 'Cystitis, chronic', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'includes interstitial and all etiologies, infectious and non-infectious: Rate as voiding dysfunction.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7515', 'Bladder, calculus', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'in, with symptoms interfering with function: Rate as voiding dysfunction', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7516', 'Bladder, fistula', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7517', 'Bladder, injury', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'of: Rate as voiding dysfunction.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7518', 'Urethra, stricture', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'of: Rate as voiding dysfunction.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7519', 'Urethra, fistula', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7520', 'Penis, removal of half or more', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Or rate as voiding dysfunction.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7521', 'Penis, removal of glans', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Or rate as voiding dysfunction.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7522', 'Penis, deformity, with loss of erectile power', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', '— 201. Rating', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7523', 'Testis, atrophy, complete', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Testis, atrophy complete:. Both—201 One—01', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7524', 'Testis, removal', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', '. Both—301 One—01 Note: In cases of the removal of one testis as the result of a service-incurred injury or disease, other than an undescended or congenitally undeveloped testis, with the absence or nonfunctioning of the other testis unrelated to service, an evaluation of 30 percent will be assigned for the service-connected testicular loss. Testis, underscended, or congenitally undeveloped is not a ratable disability.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7525', 'Epididymo-orchitis, chronic only', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as urinary tract infection. For tubercular infections: Rate in accordance with § or 4.89, whichever is appropriate.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7527', 'Prostate gland', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'injuries, infections, hypertrophy, postoperative residuals: Rate as voiding dysfunction or urinary tract infection, whichever is predominant.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7528', 'Malignant neoplasms', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Note—Following the cessation of surgical, X-ray, antineoplastic chemotherapy or other therapeutic procedure, the rating of 100 percent shall continue with a mandatory VA examination at the expiration of six months. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter. If there has been no local reoccurrence or metastasis, rate on residuals as voiding dysfunction or renal dysfunction, whichever is predominant.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7529', 'Benign neoplasms', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'of the genitourinary system: Rate as voiding dysfunction or renal dysfunction, whichever is predominant.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7530', 'Renal disease, chronic', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Chronic renal disease requiring regular dialysis: Rate as renal dysfunction.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7531', 'Kidney transplant', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rating Note—The 100 percent evaluation shall be assigned as of the date of hospital admission for transplant surgery and shall continue with a mandatory VA examination one year following hospital discharge. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7532', 'Renal tubular disorders', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Or rate as renal dysfunction.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7533', 'Kidneys, cystic diseases', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Cystic diseases of the kidneys (polycystic disease, uremic medullary cystic disease, Medullary sponge kidney, and similar conditions): Rate as renal dysfunction.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7534', 'Atherosclerotic renal disease', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', '(renal artery stenosis or atheroembolic renal disease): Rate as renal dysfunction.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7535', 'Toxic nephropathy', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', '(antibotics, radiocontrast agents, nonsteroidal anti-inflammatory agents, heavy metals, and similar agents): Rate as renal dysfunction.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7536', 'Glomerulonephritis', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as renal dysfunction.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7537', 'Interstitial nephritis', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as renal dysfunction.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7538', 'Papillary necrosis', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as renal dysfunction.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7539', 'Renal amyloid disease', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Rate as renal dysfunction.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7540', 'Disseminated intravascular coagulation', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'with renal cortical necrosis: Rate as renal dysfunction.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7541', 'Renal involvement in systemic diseases', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Renal involvement in diabetes mellitus, sickle cell anemia, systemic lupus erythematosus, vasculitis, or other systemic disease processes. Rate as renal dysfunction.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7542', 'Neurogenic bladder', 'THE GENITOURINARY SYSTEM', NULL, '38 CFR 4.115b', 'Neurogenic bladder: Rate as voiding dysfunction. 1Review for entitlement to special monthly compensation under §3.350 of this chapter. [59 FR 2527, Jan. 18, 1994; 59 FR 14567, Mar. 29, 1994, as amended at 59 FR 46339, Sept. 8, 1994]', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7610', 'Vulva or clitoris, disease or injury of (including vulvovaginitis)', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7611', 'Vagina, disease or injury', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'of.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7612', 'Cervix, disease or injury', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'of.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7613', 'Uterus, disease or injury', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'Uterus, disease, injury, or adhesions of.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7614', 'Fallopian tube, disease or injury', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'Fallopian tube, disease, injury, or adhesions of (including pelvic inflammatory disease (PID)).', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7615', 'Ovary, disease or injury', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'Note: For the purpose of VA disability evaluation, a disease, injury, or adhesions of the ovaries resulting in ovarian dysfunction affecting the menstrual cycle, such as dysmenorrhea and secondary amenorrhea, shall be rated under diagnostic code 7615', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7617', 'Uterus and both ovaries, removal', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'of, complete: For three months after removal 1100 Thereafter 150', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7618', 'Uterus, removal', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'of, including corpus: For three months after removal 1100 Thereafter 130', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7619', 'Ovary, removal', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'Note: In cases of the removal of one ovary as the result of a service-connected injury or disease, with the absence or nonfunctioning of a second ovary unrelated to service, an evaluation of 30 percent will be assigned for the service-connected ovarian loss', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7620', 'Ovaries, atrophy of both', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'complete 120 Department of Veterans Affairs Rating', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7621', 'Complete or incomplete pelvic organ prolapse due to injury or disease or surgical complica- tions of pregnancy.', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'Note: Pelvic organ prolapse occurs when a pelvic organ such as bladder, urethra, uterus, vagina, small bowel, or rectum drops (prolapse) from its normal place in the abdomen. Conditions associated with pelvic organ prolapse include: uterine or vaginal vault prolapse, cystocele, urethrocele, rectocele, enterocele, or any combination thereof. Evaluate pelvic organ prolapse under DC 7621. Evaluate separately any genitourinary, digestive, or skin symptoms under the appropriate diagnostic code(s) and combine all evaluations with the 10 percent evaluation under DC 7621', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7624', 'Fistula, rectovaginal', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'Vaginal fecal leakage one to three times per week requiring wearing of pad Vaginal fecal leakage less than once a week Without leakage', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7625', 'Fistula, urethrovaginal', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7626', 'Breast, surgery', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'Note: For VA purposes: (1) Radical mastectomy means removal of the entire breast, underlying pectoral muscles, and regional lymph nodes up to the coracoclavicular ligament.. (2) Modified radical mastectomy means removal of the entire breast and axillary lymph nodes (in continuity with the breast). Pectoral muscles are left intact.. (3) Simple (or total) mastectomy means removal of all of the breast tissue, nipple, and a small portion of the overlying skin, but lymph nodes and muscles are left intact.. Rating (4) Wide local excision (including partial mastectomy, lumpectomy, tylectomy, segmentectomy, and quadrantectomy) means removal of a portion of the breast tissue..', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7627', 'Malignant neoplasms of gynecological system', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'Note: A rating of 100 percent shall continue beyond the cessation of any surgical, radiation, antineoplastic chemotherapy or other therapeutic procedures. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter. Rate chronic residuals to include scars, lymphedema, disfigurement, and/or other impairment of function under the appropriate diagnostic code(s) within the appropriate body system 30 7628 Benign neoplasms of gynecological system. Rate chronic residuals to include scars, 10 lymphedema, disfigurement, and/or other impair0 ment of function under the appropriate diagnostic code(s) within the appropriate body system 100 7629 Endometriosis: Lesions involving bowel or bladder confirmed by laparoscopy, pelvic pain or heavy or irregular bleeding not controlled by treatment, and bowel or bladder symptoms 50 Pelvic pain or heavy or irregular bleeding not controlled by treatment 30 Pelvic pain or heavy or irregular bleeding requiring continuous treatment for control 10 Note: Diagnosis of endometriosis must be substantiated by laparoscopy.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7628', 'Benign neoplasms of gynecological system', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, NULL, NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7629', 'Endometriosis', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, NULL, NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7630', 'Malignant neoplasms of the breast', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'Note: A rating of 100 percent shall continue beyond the cessation of any surgical, radiation, antineoplastic chemotherapy or other therapeutic procedure. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter. Rate chronic residuals according to impairment of function due to scars, lymphedema, or disfigurement (e.g., limitation of arm, shoulder, and wrist motion, or loss of grip strength, or loss of sensation, or residuals from harvesting of muscles for reconstructive purposes), and/or under diagnostic code 7626', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7631', 'Benign neoplasms of the breast and other injuries of the breast', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', 'Rate chronic residuals according to impairment of function due to scars, lymphedema, or disfigurement (e.g., limitation of arm, shoulder, and wrist motion, or loss of grip strength, or loss of sensation, or residuals from harvesting of muscles for reconstructive purposes), and/or under diagnostic code 7626', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7632', 'Female sexual arousal disorder (FSAD)', 'GYNECOLOGICAL CONDITIONS AND DISORDERS OF THE BREAST', NULL, '38 CFR 4.116', '1Review for entitlement to special monthly compensation under §3.350 of this chapter. (Authority: 38 U.S.C. 1155) [60 FR 19855, Apr. 21, 1995, as amended at 67 FR 6874, Feb. 14, 2002; 67 FR 37695, May 30, 2002; 83 FR 15071, Apr. 9, 2018]', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7700', '[Removed]', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, NULL, NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7702', 'Agranulocytosis, acquired', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Note: A 100 percent evaluation for bone marrow transplant shall be assigned as of the date of hospital admission and shall continue with a mandatory VA examination six months following hospital discharge. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7703', 'Leukemia', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Note (1): A 100 percent evaluation shall continue beyond the cessation of any surgical therapy, radiation therapy, antineoplastic chemotherapy, or other therapeutic procedures. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter. If there has been no recurrence, rate on residuals Note (2): Evaluate symptomatic chronic lymphocytic leukemia that is at Rai Stage I, II, III, or IV the same as any other leukemia evaluated under this diagnostic code Note (3): Evaluate residuals of leukemia or leukemia therapy under the appropriate diagnostic code(s). Myeloproliferative Disorders: (Diagnostic Codes 7704, 7718, 7719) Rating', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7704', 'Polycythemia vera', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Note (1): Rate complications such as hypertension, gout, stroke, or thrombotic disease separately Note (2): If the condition undergoes leukemic transformation, evaluate as leukemia under diagnostic code 7703 Note (3): A 100 percent evaluation shall be assigned as of the date of hospital admission for peripheral blood or bone marrow stem cell transplant; or during the period of treatment with chemotherapy (including myelosuppressants). Six months following hospital discharge or, in the case of chemotherapy treatment, six months after completion of treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any reduction in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7705', 'Immune thrombocytopenia', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Note (1): Separately evaluate splenectomy under diagnostic code 7706 and combine with an evaluation under this diagnostic code Note (2): A 100 percent evaluation shall continue beyond the cessation of chemotherapy. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any reduction in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7706', 'Splenectomy', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Department of Veterans Affairs Rating Note: Separately rate complications such as systemic infections with encapsulated bacteria Note: Separately rate complications such as systemic infections with encapsulated bacteria', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7707', 'Spleen, injury of, healed', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Rate for any residuals.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7709', 'Hodgkin’s lymphoma', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Note: A 100 percent evaluation shall continue beyond the cessation of any surgical therapy, radiation therapy, antineoplastic chemotherapy, or other therapeutic procedures. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any reduction in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter. If there has been no local recurrence or metastasis, rate on residuals under the appropriate diagnostic code(s).', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7710', 'Adenitis, tuberculous', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'active or inactive: Rate under or 4.89 of this part, whichever is appropriate.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7712', 'Multiple myeloma', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Note (1): Current validated biomarkers of symptomatic multiple myeloma and asymptomatic multiple myeloma, smoldering, or monoclonal gammopathy of undetermined significance (MGUS) are acceptable for the diagnosis of multiple myeloma as defined by the American Society of Hematology (ASH) and International Myeloma Working Group (IMWG) Note (2): The 100 percent evaluation shall continue for five years after the diagnosis of symptomatic multiple myeloma, at which time the appropriate disability evaluation shall be determined by mandatory VA examination. Any reduction in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) and §3.344 (a) and (b) of this chapter', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7714', 'Sickle cell anemia', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Note: Sickle cell trait alone, without a history of directly attributable pathological findings, is not a ratable disability. Cases of symptomatic sickle cell trait will be forwarded to the Director, Compensation Service, for consideration under §3.321(b)(1) of this chapter', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7715', 'Non-Hodgkin’s lymphoma', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Note: A 100 percent evaluation shall continue beyond the cessation of any surgical therapy, radiation therapy, antineoplastic chemotherapy, or other therapeutic procedures. Two years after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any reduction in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter. If there has been no recurrence, rate on residuals under the appropriate diagnostic code(s)', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7716', 'Aplastic anemia', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Note (1): A 100 percent evaluation for peripheral blood or bone marrow stem cell transplant shall be assigned as of the date of hospital admission and shall continue with a mandatory VA examination six months following hospital discharge. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter Note (2): The term ‘‘newer platelet stimulating factors’’ includes medication, factors, or other agents approved by the United States Food and Drug Administration', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7717', 'AL amyloidosis (primary amyloidosis)', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7718', 'Essential thrombocythemia and primary myelofibrosis', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Note (1): If the condition undergoes leukemic transformation, evaluate as leukemia under diagnostic code 7703 Rating Note (2): A 100 percent evaluation shall be assigned as of the date of hospital admission for peripheral blood or bone marrow stem cell transplant; or during the period of treatment with chemotherapy (including myelosuppressants). Six months following hospital discharge or, in the case of chemotherapy treatment, six months after completion of treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any reduction in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7719', 'Chronic myelogenous leukemia (CML) (chronic myeloid leukemia or chronic granulocytic leu- kemia).', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Note (1): If the condition undergoes leukemic transformation, evaluate as leukemia under diagnostic code 7703 Note (2): A 100 percent evaluation shall be assigned as of the date of hospital admission for peripheral blood or bone marrow stem cell transplant; or during the period of treatment with chemotherapy (including myelosuppressants). Six months following hospital discharge or, in the case of chemotherapy treatment, six months after completion of treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any reduction in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105 of this chapter', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7720', 'Iron deficiency anemia', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Note: Do not evaluate iron deficiency anemia due to blood loss under this diagnostic code. Evaluate iron deficiency anemia due to blood loss under the criteria for the condition causing the blood loss', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7721', 'Folic acid deficiency', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7722', 'Pernicious anemia and Vitamin B12 deficiency anemia', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Note: A 100 percent evaluation for pernicious anemia and Vitamin B12deficiency shall be assigned as of the date of the initial diagnosis requiring transfusion due to severe anemia or parenteral B12therapy and shall continue with a mandatory VA examination six months following hospital discharge or cessation of parenteral B12 therapy. Any reduction in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter. Thereafter, evaluate at 10 percent and separately evaluate any residual effects of pernicious anemia, such as neurologic involvement causing peripheral neuropathy, myelopathy, dementia, or related gastrointestinal residuals, under the most appropriate diagnostic code', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7723', 'Acquired hemolytic anemia', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Note (1): A 100 percent evaluation for bone marrow transplant shall be assigned as of the date of hospital admission and shall continue for six months after hospital discharge with a mandatory VA examination six months following hospital discharge. Any reduction in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter Note (2): Separately evaluate splenectomy under diagnostic code 7706 and combine with an evaluation under diagnostic code 7723', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7724', 'Solitary plasmacytoma', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Note (1): A 100 percent evaluation shall continue beyond the cessation of any surgical therapy, radiation therapy, antineoplastic chemotherapy, or other therapeutic procedures (including autologous stem cell transplantation). Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter. If there has been no recurrence, rate residuals under the appropriate diagnostic codes Note (2): Rate a solitary plasmacytoma that has developed into multiple myeloma as symptomatic multiple myeloma Note (3): Rate residuals of plasma cell dysplasia (e.g., thrombosis) and adverse effects of medical treatment (e.g., neuropathy) under the appropriate diagnostic codes', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7725', 'Myelodysplastic syndromes', 'THE HEMATOLOGIC AND LYMPHATIC SYSTEMS', NULL, '38 CFR 4.117', 'Note (1): If the condition progresses to leukemia, evaluate as leukemia under diagnostic code 7703 Note (2): A 100 percent evaluation shall be assigned as of the date of hospital admission for peripheral blood or bone marrow stem cell transplant, or during the period of treatment with chemotherapy, and shall continue with a mandatory VA examination six months following hospital discharge or, in the case of chemotherapy treatment, six months after completion of treatment. Any reduction in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter. If there has been no recurrence, residuals will be rated under the appropriate diagnostic codes [60 FR 49227, Sept. 22, 1995, as amended at 77 FR 6467, Feb. 8, 2012; 79 FR 2100, Jan. 13, 2014; 83 FR 54254, Oct. 29, 2018; 83 FR 54881, Nov. 1, 2018]', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7800', 'Burn scar(s) of the head, face, or neck; scar(s) of the head, face, or neck due to other causes; or other disfigurement of the head, face, or neck.', 'THE SKIN', NULL, '38 CFR 4.118', 'Note (1):The 8 characteristics of disfigurement, for purposes of evaluation under , are: Scar 5 or more inches (13 or more cm.) in length. Scar at least one-quarter inch (0.6 cm.) wide at widest part. Surface contour of scar elevated or depressed on palpation. Scar adherent to underlying tissue. Skin hypo-or hyper-pigmented in an area exceeding six square inches (39 sq. cm.). Skin texture abnormal (irregular, atrophic, shiny, scaly, etc.) in an area exceeding six square inches (39 sq. cm.). Underlying soft tissue missing in an area exceeding six square inches (39 sq. cm.). Skin indurated and inflexible in an area exceeding six square inches (39 sq. cm.). Note (2): Rate tissue loss of the auricle under DC 6207 (loss of auricle) and anatomical loss of the eye under DC 6061 (anatomical loss of both eyes) or DC 6063 (anatomical loss of one eye), as appropriate. Note (3): Take into consideration unretouched color photographs when evaluating under these criteria. Note (4): Separately evaluate disabling effects other than disfigurement that are associated with individual scar(s) of the head, face, or neck, such as pain, instability, and residuals of associated muscle or nerve injury, under the appropriate diagnostic code(s) and apply to combine the evaluation(s) with the evaluation assigned under this diagnostic code. Note (5): The characteristic(s) of disfigurement may be caused by one scar or by multiple scars; the characteristic(s) required to assign a particular evaluation need ', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7801', 'Burn scar(s) or scar(s) due to other causes, not of the head, face, or neck that are associated with underlying soft tissue damage.', 'THE SKIN', NULL, '38 CFR 4.118', 'Rating Note (1): For the purposes of DCs 7801 and 7802, the six (6) zones of the body are defined as each extremity, anterior trunk, and posterior trunk. The midaxillary line divides the anterior trunk from the posterior trunk. Note (2): A separate evaluation may be assigned for each affected zone of the body under this diagnostic code if there are multiple scars, or a single scar, affecting multiple zones of the body. Combine the separate evaluations under . Alternatively, if a higher evaluation would result from adding the areas affected from multiple zones of the body, a single evaluation may also be assigned under this diagnostic code.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7802', 'Burn scar(s) or scar(s) due to other causes, not of the head, face, or neck that are not associ- ated with underlying soft tissue damage.', 'THE SKIN', NULL, '38 CFR 4.118', 'Note (1): For the purposes of DCs 7801 and 7802, the six (6) zones of the body are defined as each extremity, anterior trunk, and posterior trunk. The midaxillary line divides the anterior trunk from the posterior trunk. Note (2): A separate evaluation may be assigned for each affected zone of the body under this diagnostic code if there are multiple scars, or a single scar, affecting multiple zones of the body. Combine the separate evaluations under . Alternatively, if a higher evaluation would result from adding the areas affected from multiple zones of the body, a single evaluation may also be assigned under this diagnostic code.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7804', 'Scar(s), unstable or painful', 'THE SKIN', NULL, '38 CFR 4.118', 'Note (1): An unstable scar is one where, for any reason, there is frequent loss of covering of skin over the scar. Note (2): If one or more scars are both unstable and painful, add 10 percent to the evaluation that is based on the total number of unstable or painful scars Note (3): Scars evaluated under diagnostic codes 7800, 7801, 7802, or 7805 may also receive an evaluation under this diagnostic code, when applicable', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7805', 'Scars, other; and other effects of scars evaluated under diagnostic codes 7800, 7801, 7802, or 7804.', 'THE SKIN', NULL, '38 CFR 4.118', 'Characteristic lesions involving less than 5 percent of the entire body affected; or Characteristic lesions involving less than 5 percent of exposed areas affected. Or rate as disfigurement of the head, face, or neck (DC 7800) or scars (DCs 7801, 7802, 7804, or 7805), depending upon the predominant disability. This rating instruction does not apply to DC 7824.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7806', 'Dermatitis or eczema', 'THE SKIN', NULL, '38 CFR 4.118', 'Evaluate under the General Rating Formula for the Skin. 20 7807 American (New World) leishmaniasis (mucocutaneous, espundia): Rate as disfigurement of the head, face, or neck (DC 7800), scars (DC’s 7801, 7802, 7803, 7804, or 7805), or dermatitis (DC 7806), depending upon the predominant disability. Note: Evaluate non-cutaneous (visceral) leishmaniasis under DC 6301 (visceral leishmaniasis).', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7807', 'Leishmaniasis, American (New World)', 'THE SKIN', NULL, NULL, NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7808', 'Leishmaniasis, Old World', 'THE SKIN', NULL, '38 CFR 4.118', 'Old World leishmaniasis (cutaneous, Oriental sore): Rate as disfigurement of the head, face, or neck (DC 7800), scars (DC’s, 7801, 7802, 7803, 7804, or 7805), or dermatitis (DC 7806), depending upon the predominant disabililty. Note: Evaluate non-cutaneous (visceral) leishmaniasis under DC 6301 (visceral leishmaniasis).', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7809', 'Discoid lupus erythematosus', 'THE SKIN', NULL, '38 CFR 4.118', 'Evaluate under the General Rating Formula for the Skin. Note: Do not combine with ratings under DC 6350.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7811', 'Tuberculosis luposa (lupus vulgaris)', 'THE SKIN', NULL, '38 CFR 4.118', 'active or inactive: Rate under § or 4.89, whichever is appropriate. Department of Veterans Affairs Rating', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7813', 'Dermatophytosis', 'THE SKIN', NULL, '38 CFR 4.118', '(ringworm: Of body, tinea corporis; of head, tinea capitis; of feet, tinea pedis; of beard area, tinea barbae; of nails, tinea unguium (onychomycosis); of inguinal area (jock itch), tinea cruris; tinea versicolor). Evaluate under the General Rating Formula for the Skin.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7815', 'Bullous disorders', 'THE SKIN', NULL, '38 CFR 4.118', '(including pemphigus vulgaris, pemphigus foliaceous, bullous pemphigoid, dermatitis herpetiformis, epidermolysis bullosa acquisita, benign chronic familial pemphigus (Hailey-Hailey), and porphyria cutanea tarda). Evaluate under the General Rating Formula for the Skin. Note: Rate complications and residuals of mucosal involvement (ocular, oral, gastrointestinal, respiratory, or genitourinary) separately under the appropriate diagnostic code.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7816', 'Psoriasis', 'THE SKIN', NULL, '38 CFR 4.118', 'Evaluate under the General Rating Formula for the Skin. Note: Rate complications such as psoriatic arthritis and other clinical manifestations (e.g., oral mucosa, nails) separately under the appropriate diagnostic code.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7817', 'Erythroderma', 'THE SKIN', NULL, '38 CFR 4.118', 'Note: Treatment failure is defined as either disease progression, or less than a 25 percent reduction in the extent and severity of disease after four weeks of prescribed therapy, as documented by medical records.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7818', 'Malignant skin neoplasms', 'THE SKIN', NULL, '38 CFR 4.118', '(other than malignant melanoma): Rate as disfigurement of the head, face, or neck (DC 7800), scars (DC’s 7801, 7802, 7803, 7804, or 7805), or impairment of function. Note: If a skin malignancy requires therapy that is comparable to that used for systemic malignancies, i.e., systemic chemotherapy, X-ray therapy more extensive than to the skin, or surgery more extensive than wide local excision, a 100-percent evaluation will be assigned from the date of onset of treatment, and will continue, with a mandatory VA examination six months following the completion of such antineoplastic treatment, and any change in evaluation based upon that or any subsequent examination will be subject to the provisions of §3.105(e) of this chapter. If there has been no local recurrence or metastasis, evaluation will then be made on residuals. If treatment is confined to the skin, the provisions for a 100percent evaluation do not apply.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7819', 'Benign skin neoplasms', 'THE SKIN', NULL, '38 CFR 4.118', 'Rate as disfigurement of the head, face, or neck (DC 7800), scars (DC’s 7801, 7802, 7803, 7804, or 7805), or impairment of function.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7820', 'Infections of the skin', 'THE SKIN', NULL, '38 CFR 4.118', 'not listed elsewhere (including bacterial, fungal, viral, treponemal, and parasitic diseases). Evaluate under the General Rating Formula for the Skin.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7821', 'Cutaneous manifestations of collagen-vascular diseases not listed elsewhere', 'THE SKIN', NULL, '38 CFR 4.118', '(including scleroderma, calcinosis cutis, subacute cutaneous lupus erythematosus, and dermatomyositis). Evaluate under the General Rating Formula for the Skin.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7822', 'Papulosquamous disorders not listed elsewhere', 'THE SKIN', NULL, '38 CFR 4.118', '(including lichen planus, large or small plaque parapsoriasis, pityriasis lichenoides et varioliformis acuta (PLEVA), lymphomatoid papulosus, mycosis fungoides, and pityriasis rubra pilaris (PRP)). Evaluate under the General Rating Formula for the Skin.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7823', 'Vitiligo', 'THE SKIN', NULL, '38 CFR 4.118', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7824', 'Keratinization, diseases', 'THE SKIN', NULL, '38 CFR 4.118', 'Diseases of keratinization (including icthyoses, Darier’s disease, and palmoplantar keratoderma). Evaluate under the General Rating Formula for the Skin.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7825', 'Chronic urticaria', 'THE SKIN', NULL, '38 CFR 4.118', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7826', 'Vasculitis, primary cutaneous', 'THE SKIN', NULL, '38 CFR 4.118', 'Recurrent documented vasculitic episodes occurring one to three times over the past 12-month period, and requiring intermittent systemic immunosuppressive therapy for control; or Without recurrent documented vasculitic episodes but requiring continuous systemic medication for control. Or rate as disfigurement of the head, face, or neck (DC 7800) or scars (DCs 7801, 7802, 7804, or 7805), depending upon the predominant disability.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7827', 'Erythema multiforme', 'THE SKIN', NULL, '38 CFR 4.118', 'One to three episodes of mucosal, palmar, or plantar involvement not impairing mastication, use of hands, or ambulation, occurring over the past 12-month period AND requiring intermittent systemic therapy; or Without recurrent episodes, but requiring continuous systemic medication for control. Or rate as disfigurement of the head, face, or neck (DC 7800) or scars (DCs 7801, 7802, 7804, or 7805), depending upon the predominant disability. Note: For the purposes of this DC only, systemic therapy may consist of one or more of the following treatment agents: immunosuppressives, antihistamines, or sympathomimetics.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7828', 'Acne', 'THE SKIN', NULL, '38 CFR 4.118', 'Or rate as disfigurement of the head, face, or neck (DC 7800) or scars (DCs 7801, 7802, 7804, or 7805), depending upon the predominant disability.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7829', 'Chloracne', 'THE SKIN', NULL, '38 CFR 4.118', 'Or rate as disfigurement of the head, face, or neck (DC 7800) or scars (DCs 7801, 7802, 7804, or 7805), depending upon the predominant disability.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7830', 'Scarring alopecia', 'THE SKIN', NULL, '38 CFR 4.118', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7831', 'Alopecia areata', 'THE SKIN', NULL, '38 CFR 4.118', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7832', 'Hyperhidrosis', 'THE SKIN', NULL, '38 CFR 4.118', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7833', 'Malignant melanoma', 'THE SKIN', NULL, '38 CFR 4.118', 'Rate as scars (DC’s 7801, 7802, 7803, 7804, or 7805), disfigurement of the head, face, or neck (DC 7800), or impairment of function (under the appropriate body system). Note: If a skin malignancy requires therapy that is comparable to that used for systemic malignancies, i.e., systemic chemotherapy, X-ray therapy more extensive than to the skin, or surgery more extensive than wide local excision, a 100-percent evaluation will be assigned from the date of onset of treatment, and will continue, with a mandatory VA examination six months following the completion of such antineoplastic treatment, and any change in evaluation based upon that or any subsequent examination will be subject to the provisions of §3.105(e). If there has been no local recurrence or metastasis, evaluation will then be made on residuals. If treatment is confined to the skin, the provisions for a 100-percent evaluation do not apply. Department of Veterans Affairs (Authority: 38 U.S.C. 1155) [67 FR 49596, July 31, 2002; 67 FR 58448, 58449, Sept. 16, 2002; 73 FR 54710, Oct. 23, 2008; 77 FR 2910, Jan. 20, 2012; 83 FR 32597, July 13, 2018; 83 FR 38663, Aug. 7, 2018]', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7900', 'Hyperthyroidism, including, but not limited to, Graves’ disease', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Thereafter, rate residuals of disease or complications of medical treatment within the appropriate diagnostic code(s) within the appropriate body system. Note (1): If hyperthyroid cardiovascular or cardiac disease is present, separately evaluate under DC 7008 (hyperthyroid heart disease). Note (2): Separately evaluate eye involvement occurring as a manifestation of Graves’ Disease as diplopia (DC 6090); impairment of central visual acuity (DCs 6061–6066); or under the most appropriate DCs in .', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7901', 'Thyroid enlargement, toxic', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note (1): Evaluate symptoms of hyperthyroidism under DC 7900, hyperthyroidism, including, but not limited to, Graves’ disease. Note (2): If disfigurement of the neck is present due to thyroid disease or enlargement, separately evaluate under DC 7800 (burn scar(s) of the head, face, or neck; scar(s) of the head, face, or neck due to other causes; or other disfigurement of the head, face, or neck).', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7902', 'Thyroid enlargement, nontoxic', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note (1): Evaluate symptoms due to pressure on adjacent organs (such as the trachea, larynx, or esophagus) under the appropriate diagnostic code(s) within the appropriate body system. Note (2): If disfigurement of the neck is present due to thyroid disease or enlargement, separately evaluate under DC 7800 (burn scar(s) of the head, face, or neck; scar(s) of the head, face, or neck due to other causes; or other disfigurement of the head, face, or neck).', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7903', 'Hypothyroidism', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note (1): This evaluation shall continue for six months beyond the date that an examining physician has determined crisis stabilization. Thereafter, the residual effects of hypothyroidism shall be rated under the appropriate diagnostic code(s) within the appropriate body system(s) (e.g., eye, digestive, and mental disorders). Hypothyroidism without myxedema 30 Rating Note (2): This evaluation shall continue for six months after initial diagnosis. Thereafter, rate residuals of disease or medical treatment under the most appropriate diagnostic code(s) under the appropriate body system (e.g., eye, digestive, mental disorders). Note (3): If eye involvement, such as exophthalmos, corneal ulcer, blurred vision, or diplopia, is also present due to thyroid disease, also separately evaluate under the appropriate diagnostic code(s) in , Schedule of Ratings—Eye (such as diplopia (DC 6090) or impairment of central visual acuity (DCs 6061– 6066)).', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7904', 'Hyperparathyroidism', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note (1): After six months, rate on residuals under the appropriate diagnostic code(s) within the appropriate body system(s) based on a VA examination. Hypercalcemia (indicated by at least one of the following: Total Ca greater than 12 mg/dL (3– 3.5 mmol/L), Ionized Ca greater than 5.6 mg/dL (2–2.5 mmol/L), creatinine clearance less than 60 mL/min, bone mineral density T-score less than 2.5 SD (below mean) at any site or previous fragility fracture) 60 Note (2): Where surgical intervention is indicated, this evaluation shall continue until the day of surgery, at which time the provisions pertaining to a 100-percent evaluation shall apply. Note (3): Where surgical intervention is not indicated, this evaluation shall continue for six months after pharmacologic treatment begins. After six months, rate on residuals under the appropriate diagnostic code(s) within the appropriate body system(s) based on a VA examination. Symptoms such as fatigue, anorexia, nausea, or constipation that occur despite surgery; or in individuals who are not candidates for surgery but require continuous medication for control 10 Asymptomatic 0 Note (4): Following surgery or other treatment, evaluate chronic residuals, such as nephrolithiasis (kidney stones), decreased renal function, fractures, vision problems, and cardiovascular complications, under the appropriate diagnostic codes.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7905', 'Hypoparathyroidism', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Thereafter, evaluate chronic residuals, such as nephrolithiasis (kidney stones), cataracts, decreased renal function, and congestive heart failure under the appropriate diagnostic codes.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7906', 'Thyroiditis', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note: Manifesting as hyperthyroidism, evaluate as hyperthyroidism, including, but not limited to, Graves’ disease (DC 7900); manifesting as hypothyroidism, evaluate as hypothyroidism (DC 7903).', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7907', 'Cushing’s syndrome', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note: The evaluations specifically indicated under this diagnostic code shall continue for six months following initial diagnosis. After six months, rate on residuals under the appropriate diagnostic code(s) within the appropriate body system(s).', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7908', 'Acromegaly', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7909', 'Diabetes insipidus', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note: Thereafter, if diabetes insipidus has subsided, rate residuals under the appropriate diagnostic code(s) within the appropriate body system. With persistent polyuria or requiring continuous hormonal therapy 10', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7911', 'Addison’s disease (adrenocortical insufficiency)', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note (1): An Addisonian ‘‘crisis’’ consists of the rapid onset of peripheral vascular collapse (with acute hypotension and shock), with findings that may include: anorexia; nausea; vomiting; dehydration; profound weakness; pain in abdomen, legs, and back; fever; apathy, and depressed mentation with possible progression to coma, renal shutdown, and death. Note (2): An Addisonian ‘‘episode,’’ for VA purposes, is a less acute and less severe event than an Addisonian crisis and may consist of anorexia, nausea, vomiting, diarrhea, dehydration, weakness, malaise, orthostatic hypotension, or hypoglycemia, but no peripheral vascular collapse. Note (3): Tuberculous Addison’s disease will be evaluated as active or inactive tuberculosis. If inactive, these evaluations are not to be combined with the graduated ratings of 50 percent or 30 percent for non-pulmonary tuberculosis specified under . Assign the higher rating.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7912', 'Polyglandular syndrome (multiple endocrine neoplasia, autoimmune polyglandular syndrome)', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Evaluate according to major manifestations to include, but not limited to, Type I diabetes mellitus, hyperthyroidism, hypothyroidism, hypoparathyroidism, or Addison’s disease.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7913', 'Diabetes mellitus', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Note (1): Evaluate compensable complications of diabetes separately unless they are part of the criteria used to support a 100-percent evaluation. Noncompensable complications are considered part of the diabetic process under DC 7913. Note (2): When diabetes mellitus has been conclusively diagnosed, do not request a glucose tolerance test solely for rating purposes.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7914', 'Malignant neoplasm', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'NOTE: A rating of 100 percent shall continue beyond the cessation of any surgical, X-ray, antineoplastic chemotherapy or other therapeutic procedure. Six months after discontinuance of such treatment, the appropriate disability rating shall be determined by mandatory VA examination. Any change in evaluation based upon that or any subsequent examination shall be subject to the provisions of §3.105(e) of this chapter. If there has been no local recurrence or metastasis, rate on residuals.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7915', 'Benign neoplasm', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'Neoplasm, benign, any specified part of the endocrine system: Rate as residuals of endocrine dysfunction.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7916', 'Hyperpituitarism', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', '(prolactin secreting pituitary dysfunction): Note: Evaluate as malignant or benign neoplasm, as appropriate.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7917', 'Hyperaldosteronism', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', '(benign or malignant): Note: Evaluate as malignant or benign neoplasm, as appropriate.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7918', 'Pheochromocytoma', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', '(benign or malignant): Note: Evaluate as malignant or benign neoplasm as appropriate.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('7919', 'C-cell hyperplasia, thyroid', 'THE ENDOCRINE SYSTEM', NULL, '38 CFR 4.119', 'C-cell hyperplasia of the thyroid: If antineoplastic therapy is required, evaluate as a malignant neoplasm under DC 7914. If a prophylactic thyroidectomy is performed (based upon genetic testing) and antineoplastic therapy is not required, evaluate as hypothyroidism under DC 7903. [61 FR 20446, May 7, 1996, as amended at 82 FR 50804, Nov. 2, 2017] Department of Veterans Affairs Evaluations by comparison. Disability in this field is ordinarily to be rated in proportion to the impairment of motor, sensory or mental function. Consider especially psychotic manifestations, complete or partial loss of use of one or more extremities, speech disturbances, impairment of vision, disturbances of gait, tremors, visceral manifestations, injury to the skull, etc. In rating disability from the conditions in the preceding sentence refer to the appropriate schedule. In rating peripheral nerve injuries and their residuals, attention should be given to the site and character of the injury, the relative impairment in motor function, trophic changes, or sensory disturbances. Identification of epilepsy. When there is doubt as to the true nature of epileptiform attacks, neurological observation in a hospital adequate to make such a study is necessary. To warrant a rating for epilepsy, the seizures must be witnessed or verified at some time by a physician. As to frequency, competent, consistent lay testimony emphasizing convulsive and immediate post-convulsive characteristics may be accepted. The fr', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8000', 'Encephalitis, epidemic, chronic', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', NULL, '38 CFR 4.124a', 'Brain, new growth of:', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8002', 'Malignant', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Brain, New Growth of', '38 CFR 4.124a', 'NOTE: The rating in code 8002 will be continued for 2 years following cessation of surgical, chemotherapeutic or other treatment modality. At this point, if the residuals have stabilized, the rating will be made on neurological residuals according to symptomatology. Minimum rating 30', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
