INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8013', 'Syphilis, cerebrospinal', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Brain, New Growth of', '38 CFR 4.124a', NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8014', 'Syphilis, meningovascular', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Brain, New Growth of', '38 CFR 4.124a', NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8015', 'Tabes dorsalis', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Brain, New Growth of', '38 CFR 4.124a', 'NOTE: Rate upon the severity of convulsions, paralysis, visual impairment or psychotic involvement, etc.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8017', 'Amyotrophic lateral sclerosis', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Brain, New Growth of', '38 CFR 4.124a', 'NOTE: Consider the need for special monthly compensation.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8018', 'Multiple sclerosis', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Brain, New Growth of', '38 CFR 4.124a', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8019', 'Meningitis, cerebrospinal, epidemic', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Brain, New Growth of', '38 CFR 4.124a', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8020', 'Brain, abscess', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Brain, New Growth of', '38 CFR 4.124a', 'Spinal cord, new growths of:.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8021', 'Malignant', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Spinal Cord, New Growths', '38 CFR 4.124a', 'NOTE: The rating in code 8021 will be continued for 2 years following cessation of surgical, chemotherapeutic or other treatment modality. At this point, if the residuals have stabilized, the rating will be made on neurological residuals according to symptomatology. Minimum rating 30', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8022', 'Benign', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Spinal Cord, New Growths', '38 CFR 4.124a', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8023', 'Progressive muscular atrophy', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Spinal Cord, New Growths', '38 CFR 4.124a', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8024', 'Syringomyelia', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Spinal Cord, New Growths', '38 CFR 4.124a', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8025', 'Myasthenia gravis', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Spinal Cord, New Growths', '38 CFR 4.124a', 'NOTE: It is required for the minimum ratings for residuals under diagnostic codes 8000–8025, that there be ascertainable residuals. Determinations as to the presence of residuals not capable of objective verification, i.e., headaches, dizziness, fatigability, must be approached on the basis of the diagnosis recorded; subjective residuals will be accepted when consistent with the disease and not more likely attributable to other disease or no disease. It is of exceptional importance that when ratings in excess of the prescribed minimum ratings are assigned, the diagnostic codes utilized as bases of evaluation be cited, in addition to the codes identifying the diagnoses. 30 8045 Residuals of traumatic brain injury (TBI): There are three main areas of dysfunction that may result from TBI and have profound effects on functioning: cognitive (which is common in varying degrees after TBI), emotional/behavioral, and physical. Each of these areas of dysfunction may require evaluation.. Department of Veterans Affairs Rating Cognitive impairment is defined as decreased memory, concentration, attention, and executive functions of the brain. Executive functions are goal setting, speed of information processing, planning, organizing, prioritizing, self-monitoring, problem solving, judgment, decision making, spontaneity, and flexibility in changing actions when they are not productive. Not all of these brain functions may be affected in a given individual with cognitive impairment, and some', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8045', 'Residuals of traumatic brain injury (TBI)', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Spinal Cord, New Growths', NULL, NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8046', 'Cerebral arteriosclerosis', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Spinal Cord, New Growths', '38 CFR 4.124a', 'Rating Purely neurological disabilities, such as hemiplegia, cranial nerve paralysis, etc., due to cerebral arteriosclerosis will be rated under the diagnostic codes dealing with such specific disabilities, with citation of a hyphenated diagnostic code (e.g., 8046–8207). Purely subjective complaints such as headache, dizziness, tinnitus, insomnia and irritability, recognized as symptomatic of a properly diagnosed cerebral arteriosclerosis, will be rated 10 percent and no more under diagnostic code 9305. This 10 percent rating will not be combined with any other rating for a disability due to cerebral or generalized arteriosclerosis. Ratings in excess of 10 percent for cerebral arteriosclerosis under diagnostic code 9305 are not assignable in the absence of a diagnosis of multi-infarct dementia with cerebral arteriosclerosis. NOTE: The ratings under code 8046 apply only when the diagnosis of cerebral arteriosclerosis is substantiated by the entire clinical picture and not solely on findings of retinal arteriosclerosis. OTHER RESIDUALS OF TBI NOT OTHERWISE L e v e l F a c e ts o f c o g n i t i v e o f im p a i r m e n t a n d o t h e r i m - Criteria r e s i d u a ls o f T B I n o t p a i r - o t h e r w i s e c l a s s i f i e d m e n t Memory, attention, con0 No complaints of impairment of memory, attention, concentration, or executive functions. 1 A complaint of mild loss of memory (such as having difficulty following a conversation, recalling recent conversations, remember', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8100', 'Migraine', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Miscellaneous Diseases', '38 CFR 4.124a', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8103', 'Tic, convulsive', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Miscellaneous Diseases', '38 CFR 4.124a', 'NOTE: Depending upon frequency, severity, muscle groups involved.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8104', 'Paramyoclonus multiplex', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Miscellaneous Diseases', '38 CFR 4.124a', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8105', 'Chorea, Sydenham’s', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Miscellaneous Diseases', '38 CFR 4.124a', 'NOTE: Consider rheumatic etiology and complications.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8106', 'Chorea, Huntington’s', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Miscellaneous Diseases', '38 CFR 4.124a', 'Rate as Sydenham’s chorea. This, though a familial disease, has its onset in late adult life, and is considered a ratable disability.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8107', 'Athetosis, acquired', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Miscellaneous Diseases', '38 CFR 4.124a', 'Rate as chorea.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8108', 'Narcolepsy', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Miscellaneous Diseases', '38 CFR 4.124a', 'Rate as for epilepsy, petit mal. Rating Disability from lesions of peripheral portions of first, second, third, fourth, sixth, and eighth nerves will be rated under the Organs of Special Sense. The ratings for the cranial nerves are for unilateral involvement; when bilateral, combine but without the bilateral factor. Fifth (trigeminal) cranial nerve', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8205', 'Fifth (trigeminal), paralysis', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'The Cranial Nerves', '38 CFR 4.124a', 'Rating NOTE: Dependent upon relative degree of sensory manifestation or motor loss.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8207', 'Seventh (facial), paralysis', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'The Cranial Nerves', '38 CFR 4.124a', 'NOTE: Dependent upon relative loss of innervation of facial muscles.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8209', 'Ninth (glossopharyngeal), paralysis', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'The Cranial Nerves', '38 CFR 4.124a', 'NOTE: Dependent upon relative loss of ordinary sensation in mucous membrane of the pharynx, fauces, and tonsils.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8210', 'Tenth (pneumogastric, vagus), paralysis', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'The Cranial Nerves', '38 CFR 4.124a', 'Incomplete, moderate NOTE : Dependent upon extent of sensory and motor loss to organs of voice, respiration, pharynx, stomach and heart.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8211', 'Eleventh (spinal accessory, external branch), paralysis', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'The Cranial Nerves', '38 CFR 4.124a', 'NOTE: Dependent upon loss of motor function of sternomastoid and trapezius muscles.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
