INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8412', 'Neuralgia, twelfth cranial nerve', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'The Cranial Nerves', '38 CFR 4.124a', 'Neuralgia. Rating Schedule of ratings Major Minor The term ‘‘incomplete paralysis,’’ with this and other peripheral nerve injuries, indicates a degree of lost or impaired function substantially less than the type picture for complete paralysis given with each nerve, whether due to varied level of the nerve lesion or to partial regeneration. When the involvement is wholly sensory, the rating should be for the mild, or at most, the moderate degree. The ratings for the peripheral nerves are for unilateral involvement; when bilateral, combine with application of the bilateral factor. Upper radicular group (fifth and sixth cervicals)', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8510', 'Upper radicular group, paralysis', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Peripheral Nerves', '38 CFR 4.124a', NULL, true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
