INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8540', 'Soft-tissue sarcoma (Neurogenic origin)', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'Peripheral Nerves', '38 CFR 4.124a', 'NOTE: The 100 percent rating will be continued for 6 months following the cessation of surgical, X-ray, antineoplastic chemotherapy or other therapeutic procedure. At this point, if there has been no local recurrence or metastases, the rating will be made on residuals. Rating A thorough study of all material in § and 4.122 of the preface and under the ratings for epilepsy is necessary prior to any rating action.', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
