INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8910', 'Grand mal', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'The Epilepsies', '38 CFR 4.124a', 'Epilepsy, grand mal. Rate under the general rating formula for major seizures. 30 8911 Epilepsy, petit mal. Department of Veterans Affairs Rating Rate under the general rating formula for minor seizures. NOTE (1): A major seizure is characterized by the generalized tonic-clonic convulsion with unconsciousness. NOTE (2): A minor seizure consists of a brief interruption in consciousness or conscious control associated with staring or rhythmic blinking of the eyes or nodding of the head (‘‘pure’’ petit mal), or sudden jerking movements of the arms, trunk, or head (myoclonic type) or sudden loss of postural control (akinetic type). General Rating Formula for Major and Minor Epileptic Seizures: Averaging at least 1 major seizure per month over the last year Averaging at least 1 major seizure in 3 months over the last year; or more than 10 minor seizures weekly Averaging at least 1 major seizure in 4 months over the last year; or 9–10 minor seizures per week At least 1 major seizure in the last 6 months or 2 in the last year; or averaging at least 5 to 8 minor seizures weekly At least 1 major seizure in the last 2 years; or at least 2 minor seizures in the last 6 months 20 A confirmed diagnosis of epilepsy with a history of seizures 10 NOTE(1): When continuous medication is shown necessary for the control of epilepsy, the minimum evaluation will be 10 percent. This rating will not be combined with any other rating for epilepsy. NOTE (2): In the presence of major and minor seizures,', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8911', 'Petit mal', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'The Epilepsies', NULL, NULL, false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8912', 'Jacksonian and focal motor or sensory', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'The Epilepsies', '38 CFR 4.124a', 'Epilepsy, Jacksonian and focal motor or sensory.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8913', 'Diencephalic', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'The Epilepsies', '38 CFR 4.124a', 'Epilepsy, diencephalic. Rate as minor seizures, except in the presence of major and minor seizures, rate the predominating type.', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('8914', 'Psychomotor', 'ORGANIC DISEASES OF THE CENTRAL NERVOUS SYSTEM', 'The Epilepsies', '38 CFR 4.124a', '60 FR 42540, Sept. 15, 1975; 41 FR 11302, Mar. 18, 1976; 43 FR 45362, Oct. 2, 1978; 54 FR 4282, Jan. 30, 1989; 54 FR 49755, Dec. 1, 1989; 55 FR 154, 40 Jan. 3, 1990; 56 FR 51653, Oct. 15, 1991; 57 FR 24364, June 9, 1992; 70 FR 75399, Dec. 20, 2005; 73 FR 54705, Sept. 23, 2008; 73 FR 69554, Nov. 19, 2008; 76 FR 78824, Dec. 20, 2011; 79 FR 2100, Jan. 13, 2014] Diagnosis of mental disorders. (a) If the diagnosis of a mental disorder does not conform to DSM–5 or is not supported by the findings on the examination report, the rating agency shall return the report to the examiner to substantiate the diagnosis. Diagnostic and Statistical Manual of Mental Disorders, Fifth Edition (DSM–5), American Psychiatric Association (2013), is incorporated by reference into this section with the approval of the Director of the Federal Register under 5 U.S.C. 552(a) and 1 CFR part 51. To enforce any edition other than that specified in this section, the Department of Veterans Affairs must publish notice of change in the FEDERAL REGISTER and the material must be available to the public. All approved material is available from the American Psychiatric Association, 1000 Wilson Boulevard, Suite 1825, Arlington, VA 22209–3901, 703–907–7300, http://www.dsm5.org. It is also available for inspection at the Office of Regulation Policy and Management, Department of Veterans Affairs, 810 Vermont Avenue NW., Room 1068, Washington, DC 20420. It is also available for inspection at the National Archives and Rec', true, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
INSERT INTO ref.rating_code (code, name, body_system, subsection, cfr_section, notes, has_criteria, status, status_note, source_ids) VALUES ('9201', 'Schizophrenia', 'MENTAL DISORDERS', NULL, '38 CFR 4.130', '9202 [Removed] 9203 [Removed] 9204 [Removed] 9205 [Removed]', false, 'UNVERIFIED', NULL, ARRAY['src.legacy.va_rating_app','src.cfr.38_part4']::text[]);
