INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5000:00', '5000', 0, 100, 'the pelvis, vertebrae, or extending into major joints, or with multiple localization or with long history of intractability and debility, anemia, amyloid liver changes, or other continuous constitutional symptoms');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5000:01', '5000', 1, 60, 'Frequent episodes, with constitutional symptoms');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5000:02', '5000', 2, 30, 'With definite involucrum or sequestrum, with or without discharging sinus');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5000:03', '5000', 3, 20, 'With discharging sinus or other evidence of active infection within the past 5 years');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5000:04', '5000', 4, 10, 'Inactive, following repeated episodes, without evidence of active infection in past 5 years');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5002:00', '5002', 0, 100, 'Arthritis rheumatoid (atrophic) As an active process: With constitutional manifestations associated with active joint involvement, totally incapacitating');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5002:01', '5002', 1, 60, 'Less than criteria for 100% but with weight loss and anemia productive of severe impairment of health or severely incapacitating exacerbations occurring 4 or more times a year or a lesser number over prolonged periods');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5002:02', '5002', 2, 40, 'Symptom combinations productive of definite impairment of health objectively supported by examination findings or incapacitating exacerbations occurring 3 or more times a year');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5002:03', '5002', 3, 20, 'One or two exacerbations a year in a well-established diagnosis');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5003:00', '5003', 0, 20, 'Degenerative arthritis established by X-ray findings will be rated on the basis of limitation of motion under the appropriate diagnostic codes for the specific joint or joints involved (DC 5200 etc.). When however, the limitation of motion of the specific joint or joints involved is noncompensable under the appropriate diagnostic codes, a rating of 10 pct is for application for each such major joint or group of minor joints affected by limitation of motion, to be combined, not added under diagnostic code 5003. Limitation of motion must be objectively confirmed by findings such as swelling, muscle spasm, or satisfactory evidence of painful motion. In the absence of limitation of motion, rate as below: ACUTE, SUBACUTE, ORCHRONICDISEASES— Continued Rating With X-ray evidence of involvement of 2 or more major joints or 2 or more minor joint groups, with occasional incapacitating exacerbations');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5003:01', '5003', 1, 10, 'With X-ray evidence of involvement of 2 or more major joints or 2 or more minor joint groups');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5012:00', '5012', 0, 100, 'Bones, new growths of, malignant');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5025:00', '5025', 0, 40, '(fibrositis, primary fibromyalgia syndrome) With widespread musculoskeletal pain and tender points, with or without associated fatigue, sleep disturbance, stiffness, paresthesias, headache, irritable bowel symptoms, depression, anxiety, or Raynaud’s-like symptoms: That are constant, or nearly so, and refractory to therapy');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5025:01', '5025', 1, 20, 'That are episodic, with exacerbations often precipitated by environmental or emotional stress or by overexertion, but that are present more than one-third of the time');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5025:02', '5025', 2, 10, 'That require continuous medication for control');
