INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5301:00', '5301', 0, 30, 'Group I. Function: Upward rotation of scapula; elevation of arm above shoulder level. Extrinsic muscles of shoulder girdle: (1) Trapezius; (2) levator scapulae; (3) serratus magnus. Severe 40');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5301:01', '5301', 1, 20, 'Moderately Severe 30');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5301:02', '5301', 2, 10, 'Moderate 10');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5301:03', '5301', 3, 0, 'Slight  0');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5302:00', '5302', 0, 30, 'Group II. Function: Depression of arm from vertical overhead to hanging at side (1, 2); downward rotation of scapula (3, 4); 1 and 2 act with Group III in forward and backward swing of arm. Extrinsic muscles of shoulder girdle: (1) Pectoralis major II (costosternal); (2) latissimus dorsi and teres major (teres major, although technically an intrinsic muscle, is included with latissimus dorsi); (3) pectoralis minor; (4) rhomboid. Severe 40');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5302:01', '5302', 1, 20, 'Moderately Severe 30');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5302:02', '5302', 2, 20, 'Moderate 20');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5302:03', '5302', 3, 0, 'Slight');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5303:00', '5303', 0, 30, 'Group III. Function: Elevation and abduction of arm to level of shoulder; act with 1 and 2 of Group II in forward and backward swing of arm. Intrinsic muscles of shoulder girdle: (1) Pectoralis major I (clavicular); (2) deltoid. Severe 40');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5303:01', '5303', 1, 20, 'Moderately Severe 30');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5303:02', '5303', 2, 20, 'Moderate 20');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5303:03', '5303', 3, 0, 'Slight  0');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5304:00', '5304', 0, 20, 'Group IV. Function: Stabilization of shoulder against injury in strong movements, holding head of humerus in socket; abduction; outward rotation and inward rotation of arm. Intrinsic muscles of shoulder girdle: (1) Supraspinatus; (2) infraspinatus and teres minor; (3) subscapularis; (4) coracobrachialis. Severe 30');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5304:01', '5304', 1, 20, 'Moderately Severe 20');
