INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5305:00', '5305', 0, 30, 'Group V. Function: Elbow supination (1) (long head of biceps is stabilizer of shoulder joint); flexion of elbow (1, 2, 3). Flexor muscles of elbow: (1) Biceps; (2) brachialis; (3) brachioradialis. Severe 40');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5305:01', '5305', 1, 20, 'Moderately Severe 30');
