INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5305:03', '5305', 3, 0, 'Slight  0');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5306:00', '5306', 0, 30, 'Group VI. Function: Extension of elbow (long head of triceps is stabilizer of shoulder joint). Extensor muscles of the elbow: (1) Triceps; (2) anconeus.. Severe 40');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5306:01', '5306', 1, 20, 'Moderately Severe 30');
