INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5307:00', '5307', 0, 30, 'Group VII. Function: Flexion of wrist and fingers. Muscles arising from internal condyle of humerus: Flexors of the carpus and long flexors of fingers and thumb; pronator. Severe 40');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5307:01', '5307', 1, 20, 'Moderately Severe 30');
