INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5307:03', '5307', 3, 0, 'Slight  0');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5308:00', '5308', 0, 20, 'Group VIII. Function: Extension of wrist, fingers, and thumb; abduction of thumb. Muscles arising mainly from external condyle of humerus: Extensors of carpus, fingers, and thumb; supinator. Severe 30');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5308:01', '5308', 1, 20, 'Moderately Severe 20');
