INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5310:00', '5310', 0, 30, 'Group X. Function: Movements of forefoot and toes; propulsion thrust in walking. Intrinsic muscles of the foot: Plantar: (1) Flexor digitorum brevis; (2) abductor hallucis; (3) abductor digiti minimi; (4) quadratus plantae; (5) lumbricales; (6) 0 flexor hallucis brevis; (7) adductor hallucis; (8) flexor digiti minimi brevis; (9) dorsal and plantar interossei. Other important plantar structures: Plantar aponeurosis, long plantar and calcaneonavicular ligament, tendons of posterior tibial, peroneus longus, and long flexors of great and little toes. Severe');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5310:01', '5310', 1, 20, 'Moderately Severe');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5310:02', '5310', 2, 10, 'Moderate');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5310:03', '5310', 3, 0, 'Slight');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5310:04', '5310', 4, 20, 'Dorsal: (1) Extensor hallucis brevis; (2) extensor digitorum brevis. Other important dorsal structures: cruciate, crural, deltoid, and other ligaments; tendons of long extensors of toes and peronei muscles. Severe');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5310:05', '5310', 5, 10, 'Moderately Severe');
