INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5310:07', '5310', 7, 0, 'Slight');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5311:00', '5311', 0, 30, 'Group XI. Function: Propulsion, plantar flexion of foot (1); stabilization of arch (2, 3); flexion of toes (4, 5); Flexion of knee (6). Posterior and lateral crural muscles, and muscles of the calf: (1) Triceps surae (gastrocnemius and soleus); (2) tibialis posterior; (3) peroneus longus; (4) peroneus brevis; (5) flexor hallucis longus; (6) flexor digitorum longus; (7) popliteus; (8) plantaris. Severe');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5311:01', '5311', 1, 20, 'Moderately Severe');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5312:00', '5312', 0, 30, 'Group XII. Function: Dorsiflexion (1); extension of toes (2); stabilization of arch (3). Anterior muscles of the leg: (1) Tibialis anterior; (2) extensor digitorum longus; (3) extensor hallucis longus; (4) peroneus tertius. Severe');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5312:01', '5312', 1, 20, 'Moderately Severe');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5312:02', '5312', 2, 10, 'Moderate');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5312:03', '5312', 3, 0, 'Slight');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5313:00', '5313', 0, 40, 'Group XIII. Function: Extension of hip and flexion of knee; outward and inward rotation of flexed knee; acting with rectus femoris and sartorius (see XIV, 1, 2) synchronizing simultaneous flexion of hip and knee and extension of hip and knee by belt-over-pulley action at knee joint. Posterior thigh group, Hamstring complex of 2-joint muscles: (1) Biceps femoris; (2) semimembranosus; (3) semitendinosus. Severe');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5313:01', '5313', 1, 30, 'Moderately Severe');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5313:02', '5313', 2, 10, 'Moderate');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5314:00', '5314', 0, 40, 'Group XIV. Function: Extension of knee (2, 3, 4, 5); simultaneous flexion of hip and flexion of knee (1); tension of fascia lata and iliotibial (Maissiat’s) band, acting with XVII (1) in postural support of body (6); acting with hamstrings in synchronizing hip and knee (1, 2). Anterior thigh group: (1) Sartorius; (2) rectus femoris; (3) vastus externus; (4) vastus intermedius; (5) vastus internus; (6) tensor vaginae femoris. Severe');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5314:01', '5314', 1, 30, 'Moderately Severe');
