INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5314:03', '5314', 3, 0, 'Slight');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5315:00', '5315', 0, 30, 'Group XV. Function: Adduction of hip (1, 2, 3, 4); flexion of hip (1, 2); flexion of knee (4). Mesial thigh group: (1) Adductor longus; (2) adductor brevis; (3) adductor magnus; (4) gracilis. Severe');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5315:01', '5315', 1, 10, 'Moderately Severe Moderate');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5316:00', '5316', 0, 40, 'Group XVI. Function: Flexion of hip (1, 2, 3). Pelvic girdle group 1: (1) Psoas; (2) iliacus; (3) pectineus. Severe');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5316:01', '5316', 1, 30, 'Moderately Severe');
