INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5316:03', '5316', 3, 0, 'Slight');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5317:00', '5317', 0, 40, 'Group XVII. Function: Extension of hip (1); abduction of thigh; elevation of opposite side of pelvis (2, 3); tension of fascia lata and iliotibial (Maissiat’s) band, acting with XIV (6) in postural support of body steadying pelvis upon head of femur and condyles of femur on tibia (1). Pelvic girdle group 2: (1) Gluteus maximus; (2) gluteus medius; (3) gluteus minimus. Severe *50 Moderately Severe');
