INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5317:03', '5317', 3, 30, '10 5318 Group XVIII. Function: Outward rotation of 0 thigh and stabilization of hip joint. Pelvic girdle group 3: (1) Pyriformis; (2) gemellus (superior or inferior); (3) obturator (external or internal); (4) quadratus femoris. Severe');
