INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5317:06', '5317', 6, 0, 'Slight');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5319:00', '5319', 0, 50, 'Group XIX. Function: Support and compression of abdominal wall and lower thorax; flexion and lateral motions of spine; synergists in strong downward movements of arm (1). Muscles of the abdominal wall: (1) Rectus abdominis; (2) external oblique; (3) internal oblique; (4) transversalis; (5) quadratus lumborum. Severe');
