INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5319:04', '5319', 4, 40, '0 5320 Group XX. Function: Postural support of body; extension and lateral movements of spine. Spinal muscles: Sacrospinalis (erector spinae and its prolongations in thoracic and cervical regions). Cervical and thoracic region:. Severe');
