INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('5321:00', '5321', 0, 20, 'Group XXI. Function: Respiration. Muscles of respiration: Thoracic muscle group. Severe or Moderately Severe');
