INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6315:04', '6315', 4, 10, 'Confirmed diagnosis with nonspecific symptoms such as: decreased appetite, weight loss, abdominal discomfort, weakness, inability to concentrate and irritability');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6325:00', '6325', 0, 100, '[[PAGE 462]] §4.88b As active disease');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6326:00', '6326', 0, 0, 'As acute or asymptomatic chronic disease');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6350:00', '6350', 0, 100, ', systemic (disseminated): Not to be combined with ratings under DC 7809 Acute, with frequent exacerbations, producing severe impairment of health');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6350:01', '6350', 1, 60, 'Exacerbations lasting a week or more, 2 or 3 times per year');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6350:02', '6350', 2, 10, 'Exacerbations once or twice a year or symptomatic during the past 2 years');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6351:00', '6351', 0, 100, 'AIDS with recurrent opportunistic infections (see Note 3) or with secondary diseases afflicting multiple body systems; HIV-related illness with debility and progressive weight loss');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6351:01', '6351', 1, 60, 'Refractory constitutional symptoms, diarrhea, and pathological weight loss; or minimum rating following development of AIDS-related opportunistic infection or neoplasm');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6351:02', '6351', 2, 30, 'Recurrent constitutional symptoms, intermittent diarrhea, and use of approved medication(s); or minimum rating with T4 cell count less than 200');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6351:03', '6351', 3, 10, 'Following development of HIV-related constitutional symptoms; T4 cell count between 200 and 500; use of approved medication(s); or with evidence of depression or memory loss with employment limitations');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6351:04', '6351', 4, 0, 'Asymptomatic, following initial diagnosis of HIV infection, with or without lymphadenopathy or decreased T4 cell count');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6354:00', '6354', 0, 100, 'Debilitating fatigue, cognitive impairments (such as inability to concentrate, forgetfulness, or confusion), or a combination of other signs and symptoms: Which are nearly constant and so severe as to restrict routine daily activities almost completely and which may occasionally preclude self-care');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6354:01', '6354', 1, 60, 'Which are nearly constant and restrict routine daily activities to less than 50 percent of the pre-illness level; or which wax and wane, resulting in periods of incapacitation of at least six weeks total duration per year');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6354:02', '6354', 2, 40, '[[PAGE 463]] Department of Veterans Affairs §4.89 Rating Which are nearly constant and restrict routine daily activities from 50 to 75 percent of the pre-illness level; or which wax and wane, resulting in periods of incapacitation of at least four but less than six weeks total duration per year');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6354:03', '6354', 3, 20, 'Which are nearly constant and restrict routine daily activities by less than 25 percent of the pre-illness level; or which wax and wane, resulting in periods of incapacitation of at least two but less than four weeks total duration per year');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6354:04', '6354', 4, 10, 'Which wax and wane but result in periods of incapacitation of at least one but less than two weeks total duration per year; or symptoms controlled by continuous medication');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6502:00', '6502', 0, 10, 'Traumatic only, With 50-percent obstruction of the nasal passage on both sides or complete obstruction on one side');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6504:00', '6504', 0, 30, 'Exposing both nasal passages');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6504:01', '6504', 1, 10, 'Loss of part of one ala, or other obvious disfigurement');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6514:00', '6514', 0, 50, 'General Rating Formula for Sinusitis (DC’s 6510 through 6514): Following radical surgery with chronic osteomyelitis, or; near constant sinusitis characterized by headaches, pain and tenderness of affected sinus, and purulent discharge or crusting after repeated surgeries');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6514:01', '6514', 1, 30, 'Three or more incapacitating episodes per year of sinusitis requiring prolonged (lasting four to six weeks) antibiotic treatment, or; more than six non-incapacitating episodes per year of sinusitis characterized by headaches, pain, and purulent discharge or crusting');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6514:02', '6514', 2, 10, 'One or two incapacitating episodes per year of sinusitis requiring prolonged (lasting four to six weeks) antibiotic treatment, or; three to six non-incapacitating episodes per year of sinusitis characterized by headaches, pain, and purulent discharge or crusting');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6514:03', '6514', 3, 0, 'Detected by X-ray only');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6516:00', '6516', 0, 30, 'Hoarseness, with thickening or nodules of cords, polyps, submucous infiltration, or pre-malignant changes on biopsy');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6516:01', '6516', 1, 10, 'Hoarseness, with inflammation of cords or mucous membrane');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6519:00', '6519', 0, 60, 'Constant inability to communicate by speech Constant inability to speak above a whisper');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6520:00', '6520', 0, 100, ', including residuals of laryngeal trauma (unilateral or bilateral): Forced expiratory volume in one second (FEV–1) less than 40 percent of predicted value, with Flow-Volume Loop compatible with upper airway obstruction, or; permanent tracheostomy');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6520:01', '6520', 1, 60, 'FEV–1 of 40to 55-percent predicted, with Flow-Volume Loop compatible with upper airway obstruction');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6520:02', '6520', 2, 30, 'FEV–1 of 56to 70-percent predicted, with Flow-Volume Loop compatible with upper airway obstruction');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6520:03', '6520', 3, 10, 'FEV–1 of 71to 80-percent predicted, with Flow-Volume Loop compatible with upper airway obstruction');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6521:00', '6521', 0, 50, 'Stricture or obstruction of pharynx or nasopharynx, or; absence of soft palate secondary to trauma, chemical burn, or granulomatous disease, or; paralysis of soft palate with swallowing difficulty (nasal regurgitation) and speech impairment');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6522:00', '6522', 0, 30, 'With polyps');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6522:01', '6522', 1, 10, 'Without polyps, but with greater than 50-percent obstruction of nasal passage on both sides or complete obstruction on one side');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6523:00', '6523', 0, 50, 'Rhinoscleroma');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6523:01', '6523', 1, 10, 'With permanent hypertrophy of turbinates and with greater than 50-percent obstruction of nasal passage on both sides or complete obstruction on one side');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6524:00', '6524', 0, 100, '[[PAGE 466]] §4.97 Wegener’s granulomatosis, lethal midline granuloma');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6524:01', '6524', 1, 20, 'Other types of granulomatous infection');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6600:00', '6600', 0, 100, 'FEV–1 less than 40 percent of predicted value, or; the ratio of Forced Expiratory Volume in one second to Forced Vital Capacity (FEV–1/FVC) less than 40 percent, or; Diffusion Capacity of the Lung for Carbon Monoxide by the Single Breath Method (DLCO (SB)) less than 40-percent predicted, or; maximum exercise capacity less than 15 ml/kg/min oxygen consumption (with cardiac or respiratory limitation), or; cor pulmonale (right heart failure), or; right ventricular hypertrophy, or; pulmonary hypertension (shown by Echo or cardiac catheterization), or; episode(s) of acute respiratory failure, or; requires outpatient oxygen therapy');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6600:01', '6600', 1, 60, 'FEV–1 of 40to 55-percent predicted, or; FEV–1/FVC of 40 to 55 percent, or; DLCO (SB) of 40to 55-percent predicted, or; maximum oxygen consumption of 15 to 20 ml/kg/min (with cardiorespiratory limit)');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6600:02', '6600', 2, 30, 'FEV–1 of 56to 70-percent predicted, or; FEV–1/FVC of 56 to 70 percent, or; DLCO (SB) 56to 65-percent predicted');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6600:03', '6600', 3, 10, 'FEV–1 of 71to 80-percent predicted, or; FEV–1/FVC of 71 to 80 percent, or; DLCO (SB) 66to 80-percent predicted');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6601:00', '6601', 0, 100, 'With incapacitating episodes of infection of at least six weeks total duration per year');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6601:01', '6601', 1, 60, 'With incapacitating episodes of infection of four to six weeks total duration per year, or; near constant findings of cough with purulent sputum associated with anorexia, weight loss, and frank hemoptysis and requiring antibiotic usage almost continuously');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6601:02', '6601', 2, 30, 'With incapacitating episodes of infection of two to four weeks total duration per year, or; daily productive cough with sputum that is at times purulent or blood-tinged and that requires prolonged (lasting four to six weeks) antibiotic usage more than twice a year');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6601:03', '6601', 3, 10, 'Intermittent productive cough with acute infection requiring a course of antibiotics at least twice a year');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6602:00', '6602', 0, 100, 'FEV–1 less than 40-percent predicted, or; FEV–1/FVC less than 40 percent, or; more than one attack per week with episodes of respiratory failure, or; requires daily use of systemic (oral or parenteral) high dose corticosteroids or immuno-suppressive medications');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6602:01', '6602', 1, 60, 'FEV–1 of 40to 55-percent predicted, or; FEV–1/FVC of 40 to 55 percent, or; at least monthly visits to a physician for required care of exacerbations, or; intermittent (at least three per year) courses of systemic (oral or parenteral) corticosteroids');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6602:02', '6602', 2, 30, 'FEV–1 of 56to 70-percent predicted, or; FEV–1/FVC of 56 to 70 percent, or; daily inhalational or oral bronchodilator therapy, or; inhalational anti-inflammatory medication');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6602:03', '6602', 3, 10, 'FEV–1 of 71to 80-percent predicted, or; FEV–1/FVC of 71 to 80 percent, or; intermittent inhalational or oral bronchodilator therapy');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6603:00', '6603', 0, 100, 'FEV–1 less than 40 percent of predicted value, or; the ratio of Forced Expiratory Volume in one second to Forced Vital Capacity (FEV–1/FVC) less than 40 percent, or; Diffusion Capacity of the Lung for Carbon Monoxide by the Single Breath Method (DLCO (SB)) less than 40-percent predicted, or; maximum exercise capacity less than 15 ml/kg/min oxygen consumption (with cardiac or respiratory limitation), or; cor pulmonale (right heart failure), or; right ventricular hypertrophy, or; pulmonary hypertension (shown by Echo or cardiac catheterization), or; episode(s) of acute respiratory failure, or; requires outpatient oxygen therapy.');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6603:01', '6603', 1, 60, 'FEV–1 of 40to 55-percent predicted, or; FEV–1/FVC of 40 to 55 percent, or; DLCO (SB) of 40to 55-percent predicted, or; maximum oxygen consumption of 15 to 20 ml/kg/min (with cardiorespiratory limit)');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6603:02', '6603', 2, 30, 'FEV–1 of 56to 70-percent predicted, or; FEV–1/FVC of 56 to 70 percent, or; DLCO (SB) 56to 65-percent predicted');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6603:03', '6603', 3, 10, 'FEV–1 of 71to 80-percent predicted, or; FEV–1/FVC of 71 to 80 percent, or; DLCO (SB) 66to 80-percent predicted');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6604:00', '6604', 0, 100, 'FEV–1 less than 40 percent of predicted value, or; the ratio of Forced Expiratory Volume in one second to Forced Vital Capacity (FEV–1/FVC) less than 40 percent, or; Diffusion Capacity of the Lung for Carbon Monoxide by the Single Breath Method (DLCO (SB)) less than 40-percent predicted, or; maximum exercise capacity less than 15 ml/kg/min oxygen consumption (with cardiac or respiratory limitation), or; cor pulmonale (right heart failure), or; right ventricular hypertrophy, or; pulmonary hypertension (shown by Echo or cardiac catheterization), or; episode(s) of acute respiratory failure, or; requires outpatient oxygen therapy.');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6604:01', '6604', 1, 60, 'FEV–1 of 40to 55-percent predicted, or; FEV–1/FVC of 40 to 55 percent, or; DLCO (SB) of 40to 55-percent predicted, or; maximum oxygen consumption of 15 to 20 ml/kg/min (with cardiorespiratory limit)');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6604:02', '6604', 2, 30, 'FEV–1 of 56to 70-percent predicted, or; FEV–1/FVC of 56 to 70 percent, or; DLCO (SB) 56to 65-percent predicted');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6604:03', '6604', 3, 10, 'FEV–1 of 71to 80-percent predicted, or; FEV–1/FVC of 71 to 80 percent, or; DLCO (SB) 66to 80-percent predicted');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6701:00', '6701', 0, 100, 'Tuberculosis, pulmonary, chronic, far advanced, active');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6702:00', '6702', 0, 100, 'Tuberculosis, pulmonary, chronic, moderately advanced, active');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6703:00', '6703', 0, 100, 'Tuberculosis, pulmonary, chronic, minimal, active');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6704:00', '6704', 0, 100, 'Tuberculosis, pulmonary, chronic, active, advancement unspecified');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6724:00', '6724', 0, 100, 'Tuberculosis, pulmonary, chronic, inactive, advancement unspecified. General Rating Formula for Inactive Pulmonary Tuberculosis: For two years after date of inactivity, following active tuberculosis, which was clinically identified during service or subsequently');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6724:01', '6724', 1, 50, 'Thereafter for four years, or in any event, to six years after date of inactivity');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6724:02', '6724', 2, 30, 'Thereafter, for five years, or to eleven years after date of inactivity');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6724:03', '6724', 3, 30, 'Following far advanced lesions diagnosed at any time while the disease process was active, minimum');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6724:04', '6724', 4, 20, 'Following moderately advanced lesions, provided there is continued disability, emphysema, dyspnea on exertion, impairment of health, etc');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6724:05', '6724', 5, 0, 'Otherwise');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6730:00', '6730', 0, 100, 'Tuberculosis, pulmonary, chronic, active');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6817:00', '6817', 0, 100, 'Primary pulmonary hypertension, or; chronic pulmonary thromboembolism with evidence of pulmonary hypertension, right ventricular hypertrophy, or cor pulmonale, or; pulmonary hypertension secondary to other obstructive disease of pulmonary arteries or veins with evidence of right ventricular hypertrophy or cor pulmonale');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6817:01', '6817', 1, 60, 'Chronic pulmonary thromboembolism requiring anticoagulant therapy, or; following inferior vena cava surgery without evidence of pulmonary hypertension or right ventricular dysfunction');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6817:02', '6817', 2, 30, 'Symptomatic, following resolution of acute pulmonary embolism');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6817:03', '6817', 3, 0, 'Asymptomatic, following resolution of pulmonary thromboembolism');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6819:00', '6819', 0, 100, ', any specified part of respiratory system exclusive of skin growths');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6824:00', '6824', 0, 100, 'General Rating Formula for Bacterial Infections of the Lung (diagnostic codes 6822 through 6824): Active infection with systemic symptoms such as fever, night sweats, weight loss, or hemoptysis');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6833:00', '6833', 0, 100, 'General Rating Formula for Interstitial Lung Disease (diagnostic codes 6825 through 6833): Forced Vital Capacity (FVC) less than 50-percent predicted, or; Diffusion Capacity of the Lung for Carbon Monoxide by the Single Breath Method (DLCO (SB)) less than 40-percent predicted, or; maximum exercise capacity less than 15 ml/kg/min oxygen consumption with cardiorespiratory limitation, or; cor pulmonale or pulmonary hypertension, or; requires outpatient oxygen therapy');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6833:01', '6833', 1, 60, 'FVC of 50to 64-percent predicted, or; DLCO (SB) of 40to 55-percent predicted, or; maximum exercise capacity of 15 to 20 ml/kg/min oxygen consumption with cardiorespiratory limitation');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6833:02', '6833', 2, 30, 'FVC of 65to 74-percent predicted, or; DLCO (SB) of 56to 65-percent predicted');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6833:03', '6833', 3, 10, 'FVC of 75to 80-percent predicted, or; DLCO (SB) of 66to 80-percent predicted');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6839:00', '6839', 0, 100, 'General Rating Formula for Mycotic Lung Disease (diagnostic codes 6834 through 6839): Chronic pulmonary mycosis with persistent fever, weight loss, night sweats, or massive hemoptysis..');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6839:01', '6839', 1, 50, 'Chronic pulmonary mycosis requiring suppressive therapy with no more than minimal symptoms such as occasional minor hemoptysis or productive cough');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6839:02', '6839', 2, 30, 'Chronic pulmonary mycosis with minimal symptoms such as occasional minor hemoptysis or productive cough');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6839:03', '6839', 3, 0, 'Healed and inactive mycotic lesions, asymptomatic');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6845:00', '6845', 0, 100, 'Chronic pleural effusion or fibrosis. General Rating Formula for Restrictive Lung Disease (diagnostic codes 6840 through 6845): FEV–1 less than 40 percent of predicted value, or; the ratio of Forced Expiratory Volume in one second to Forced Vital Capacity (FEV–1/FVC) less than 40 percent, or; Diffusion Capacity of the Lung for Carbon Monoxide by the Single Breath Method (DLCO (SB)) less than 40-percent predicted, or; maximum exercise capacity less than 15 ml/kg/min oxygen consumption (with cardiac or respiratory limitation), or; cor pulmonale (right heart failure), or; right ventricular hypertrophy, or; pulmonary hypertension (shown by Echo or cardiac catheterization), or; episode(s) of acute respiratory failure, or; requires outpatient oxygen therapy');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6845:01', '6845', 1, 60, 'FEV–1 of 40to 55-percent predicted, or; FEV–1/FVC of 40 to 55 percent, or; DLCO (SB) of 40to 55-percent predicted, or; maximum oxygen consumption of 15 to 20 ml/kg/min (with cardiorespiratory limit)');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6845:02', '6845', 2, 30, 'FEV–1 of 56to 70-percent predicted, or; FEV–1/FVC of 56 to 70 percent, or; DLCO (SB) 56to 65percent predicted');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6845:03', '6845', 3, 10, '[[PAGE 469]] Department of Veterans Affairs §4.104 Rating FEV–1 of 71to 80-percent predicted, or; FEV–1/FVC of 71 to 80 percent, or; DLCO (SB) 66to 80percent predicted');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6846:00', '6846', 0, 100, 'Cor pulmonale, or; cardiac involvement with congestive heart failure, or; progressive pulmonary disease with fever, night sweats, and weight loss despite treatment');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6846:01', '6846', 1, 60, 'Pulmonary involvement requiring systemic high dose (therapeutic) corticosteroids for control');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6846:02', '6846', 2, 30, 'Pulmonary involvement with persistent symptoms requiring chronic low dose (maintenance) or intermittent corticosteroids');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6846:03', '6846', 3, 0, 'Chronic hilar adenopathy or stable lung infiltrates without symptoms or physiologic impairment');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6847:00', '6847', 0, 100, '(Obstructive, Central, Mixed): Chronic respiratory failure with carbon dioxide retention or cor pulmonale, or; requires tracheostomy');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6847:01', '6847', 1, 50, 'Requires use of breathing assistance device such as continuous airway pressure (CPAP) machine');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6847:02', '6847', 2, 30, 'Persistent day-time hypersomnolence');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('6847:03', '6847', 3, 0, 'Asymptomatic but with documented sleep disorder breathing');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('7000:00', '7000', 0, 100, '(including rheumatic heart disease): During active infection with valvular heart damage and for three months following cessation of therapy for the active infection');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('7000:01', '7000', 1, 100, 'Thereafter, with valvular heart disease (documented by findings on physical examination and either echocardiogram, Doppler echocardiogram, or cardiac catheterization) resulting in: Chronic congestive heart failure, or; workload of 3 METs or less results in dyspnea, fatigue, angina, dizziness, or syncope, or; left ventricular dysfunction with an ejection fraction of less than 30 percent');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('7000:02', '7000', 2, 60, 'More than one episode of acute congestive heart failure in the past year, or; workload of greater than 3 METs but not greater than 5 METs results in dyspnea, fatigue, angina, dizziness, or syncope, or; left ventricular dysfunction with an ejection fraction of 30 to 50 percent');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('7000:03', '7000', 3, 30, 'Workload of greater than 5 METs but not greater than 7 METs results in dyspnea, fatigue, angina, dizziness, or syncope, or; evidence of cardiac hypertrophy or dilatation on electro-cardiogram, echocardiogram, or X-ray');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('7000:04', '7000', 4, 10, 'Workload of greater than 7 METs but not greater than 10 METs results in dyspnea, fatigue, angina, dizziness, or syncope, or; continuous medication required');
