INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('7805:04', '7805', 4, 0, 'Characteristic lesions involving at least 5 percent, but less than 20 percent, of the entire body affected; or At least 5 percent, but less than 20 percent, of exposed areas affected; or Intermittent systemic therapy including, but not limited to, corticosteroids, phototherapy, retinoids, biologics, photochemotherapy, PUVA, or other immunosuppressive drugs required for a total duration of less than 6 weeks over the past 12-month period. No more than topical therapy required over the past 12-month period and at least one of the following');
