INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('7817:02', '7817', 2, 60, 'Generalized involvement of the skin without systemic manifestations and one of the following. Constant or near-constant systemic therapy such as therapeutic doses of corticosteroids, other immunosuppressive drugs, retinoids, PUVA, UVB treatments, biologics, or electron beam therapy required over the past 12-month period; or No current treatment due to a documented history of treatment failure with 1 treatment regimen');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('7817:03', '7817', 3, 30, 'Any extent of involvement of the skin, and any of the following therapies required for a total duration of 6 weeks or more, but not constantly, over the past 12-month period: systemic therapy such as therapeutic doses of corticosteroids, other immunosuppressive drugs, retinoids, PUVA, UVB treatments, biologics, or electron beam therapy');
