INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('8914:00', '8914', 0, 40, 'Epilepsy, psychomotor. Major seizures: Psychomotor seizures will be rated as major seizures under the general rating formula when characterized by automatic states and/or generalized convulsions with unconsciousness. Minor seizures: Psychomotor seizures will be rated as minor seizures under the general rating formula when characterized by brief transient episodes of random motor movements, hallucinations, perceptual illusions, abnormalities of thinking, memory or mood, or autonomic disturbances. Mental Disorders in Epilepsies: A nonpsychotic organic brain syndrome will be rated separately under the appropriate diagnostic code (e.g., 9304 or 9326). In the absence of a diagnosis of non-psychotic organic psychiatric disturbance (psychotic, psychoneurotic or personality disorder) if diagnosed and shown to be secondary to or directly associated with epilepsy will be rated separately. The psychotic or psychroneurotic disorder will be rated under the appropriate diagnostic code. The personality disorder will be rated as a dementia (e.g., diagnostic code 9304 or 9326). §4.125 Epilepsy and Unemployability: (1) Rating specialists must bear in mind that the epileptic, although his or her seizures are controlled, may find employment and rehabilitation difficult of attainment due to employer reluctance to the hiring of the epileptic. (2) Where a case is encountered with a definite history of unemployment, full and complete development should be undertaken to ascertain whether the epilepsy is the determining fac to r in h is o r h e r in a b ili t y to o b ta i n e m p l o y m e n t. (3 ) T h e a s s e n t o f th e c l a im a n t s h o ul d f ir st b e obtained for permission to conduct this economic and social survey. The purpose of this survey is to secure all the relevant facts and data necessary to permit of a true judgment as to the reason for his or her unemployment and should include information as to: (a) Education; (b) Occupations prior and subsequent to service; (c) Places of employment and reasons for termination; (d) Wages received; (e) Number of seizures. (4) Upon completion of this survey and current examination, the case should have rating board consideration. Where in the judgment of the rating board the veteran’s unemployability is due to epilepsy and jurisdiction is not vested in that body by reason of schedular evaluations, the case should be sub100 mitted to the Compensation Service or the Director, Pension and Fiduciary Service. 80 (Authority: 38 U.S.C. 1155) [29 FR 6718, May 22, 1964, as amended at');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('9440:00', '9440', 0, 100, 'Total occupational and social impairment, due to such symptoms as: gross impairment in thought processes or communication; persistent delusions or hallucinations; grossly inappropriate behavior; persistent danger of hurting self or others; intermittent inability to perform activities of daily living (including maintenance of minimal personal hygiene); disorientation to time or place; memory loss for names of close relatives, own occupation, or own name.');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('9440:01', '9440', 1, 70, 'Occupational and social impairment, with deficiencies in most areas, such as work, school, family relations, judgment, thinking, or mood, due to such symptoms as: suicidal ideation; obsessional rituals which interfere with routine activities; speech intermittently illogical, obscure, or irrelevant; near-continuous panic or depression affecting the ability to function independently, appropriately and effectively; impaired impulse control (such as unprovoked irritability with periods of violence); spatial disorientation; neglect of personal appearance and hygiene; difficulty in adapting to stressful circumstances (including work or a worklike setting); inability to establish and maintain effective relationships.');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('9440:02', '9440', 2, 50, 'Occupational and social impairment with reduced reliability and productivity due to such symptoms as: flattened affect; circumstantial, circumlocutory, or stereotyped speech; panic attacks more than once a week; difficulty in understanding complex commands; impairment of shortand long-term memory (e.g., retention of only highly learned material, forgetting to complete tasks); impaired judgment; impaired abstract thinking; disturbances of motivation and mood; difficulty in establishing and maintaining effective work and social relationships.');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('9440:03', '9440', 3, 30, 'Occupational and social impairment with occasional decrease in work efficiency and intermittent periods of inability to perform occupational tasks (although generally functioning satisfactorily, with routine behavior, self-care, and conversation normal), due to such symptoms as: depressed mood, anxiety, suspiciousness, panic attacks (weekly or less often), chronic sleep impairment, mild memory loss (such as forgetting names, directions, recent events).');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('9440:04', '9440', 4, 10, 'Occupational and social impairment due to mild or transient symptoms which decrease work efficiency and ability to perform occupational tasks only during periods of significant stress, or symptoms controlled by continuous medication.');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('9440:05', '9440', 5, 0, 'A mental condition has been formally diagnosed, but symptoms are not severe enough either to interfere with occupational and social functioning or to require continuous medication.');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('9521:00', '9521', 0, 100, 'Self-induced weight loss to less than 80 percent of expected minimum weight, with incapacitating episodes of at least six weeks total duration per year, and requiring hospitalization more than twice a year for parenteral nutrition or tube feeding.');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('9521:01', '9521', 1, 60, 'Self-induced weight loss to less than 85 percent of expected minimum weight with incapacitating episodes of six or more weeks total duration per year.');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('9521:02', '9521', 2, 30, 'Self-induced weight loss to less than 85 percent of expected minimum weight with incapacitating episodes of more than two but less than six weeks total duration per year.');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('9521:03', '9521', 3, 10, 'Binge eating followed by self-induced vomiting or other measures to prevent weight gain, or resistance to weight gain even when below expected minimum weight, with diagnosis of an eating disorder and incapacitating episodes of up to two weeks total duration per year.');
INSERT INTO ref.rating_criterion (criterion_id, code, position, percent, criteria_text) VALUES ('9521:04', '9521', 4, 0, 'Binge eating followed by self-induced vomiting or other measures to prevent weight gain, or resistance to weight gain even when below expected minimum weight, with diagnosis of an eating disorder but without incapacitating episodes.');
